const FULL_ARTICLE_DETAILS: Record<string, FullArticleDetails> = {
    "Students’ Use of GitHub Copilot for Working with Large Code Bases": { "id": "ID01", "level": "A", "year": "2025", "source": " Proceedings of the 56th ACM Technical Symposium on Computer Science Education ", "authors": "Anshul Shah, Anya Chernova, Elena Tomson, Leo Porter, William G. Griswold, Adalbert Gerald Soosai Raj", "educationalObjectives": "This study was conducted to understand how undergraduate students utilize and experience GitHub Copilot when adding a feature to a large codebase, with an analysis of how they used the GitHub Copilot chat feature. The ultimate goal is for the computer science curriculum to adequately prepare students for a career in software engineering in the current landscape with LLMs (Large Language Models). The paper presents three research questions (RQs), which are: RQ1: \"How often do students use the diverse features of GitHub Copilot when adding a small feature to a large codebase?\" RQ2: \"How do students typically interact with the GitHub Copilot chat?\" RQ3: \"How much do students trust the output of GitHub Copilot for code generation and code comprehension features?\" The highlighted objectives are to prepare students for the effective use of LLMs in software engineering, developing skills such as navigating and modifying large codebases, best practices in using these tools, verification and debugging of LLM-generated outputs, in addition to fundamental competencies like decomposition, testing, and debugging. The paper seeks to teach how students can utilize GitHub Copilot as a tool to assist with complex software engineering tasks, such as working with extensive codebases, emphasizing the need for critical skills in verification, debugging, and decomposition, in addition to understanding the code itself.", "aiEmployment": "Initially, the instructor introduced Copilot's features in two lectures, with live demonstrations (such as the /explain, /fix, and /tests commands, etc.). Subsequently, students completed a small in-class activity using the tool. The main practical application occurred during an assignment that required adding a feature to a large, real-world codebase, within the context of the course (Working with Large Codebases). During this task, Copilot usage was observed through process diaries and chat transcripts, with the aim of understanding its application in real-world scenarios and reinforcing skills such as decomposition, verification, and debugging of AI-generated code. The primary objective was to observe how these students utilized the tool when tackling a complex programming task in a setting closer to a professional environment. The prompts and interactions with the AI were created by the students themselves while completing a designated programming task. The AI was used by the students as an assistant to aid in various stages of the software engineering task, from understanding the existing codebase and searching for relevant parts, through code generation and debugging, up to the creation of documentation and tests.", "llm": "GitHub Copilot", "metrics": "Questionnaires, User Satisfaction, Number of Interactions with Copilot Chat, and Rate of Use of Copilot Features", "metricsUsage": "A qualitative analysis of the Copilot Chat interactions was performed through open coding of the transcripts, categorizing the types of prompts and behaviors, such as one-shot prompting. Quantitatively, the most used features were also measured, including the Copilot Chat (97.9%) and the /explain command (66.7%), in addition to the frequency of strategies like one-shot prompting (63%).", "resources": "The study utilized in-class demonstrations, practical activities, the idlelib codebase, a programming assignment, usage diaries, and Copilot Chat transcripts.", "benefitsAndChallenges": "The study identified several benefits from using GitHub Copilot, such as the accelerated code comprehension via the /explain command, utilized by 66.7% of students, and the support from Copilot Chat (used by 97.9%) in the decomposition of complex problems. Rapid code generation through comments was also used by 37.5%, albeit with caveats. Features that promote transparency, such as clickable references, increased student trust. Conversely, challenges included the reliance on one-shot prompting (63% of students), which generated debugging cycles and time loss due to incorrect code. Trust in code generation was low, attributed to the lack of explanations and the occurrence of errors, such as hallucinations and ineffective commands.", "swebokAreas": "Software Construction", "swebokSubAreas": "Practical Considerations", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3641554.3701800", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Exploring LLMs Impact on Student-Created User Stories and Acceptance Testing in Software Development": { "id": "ID02", "level": "B", "year": "2025", "source": "", "authors": "Warren Liang, Wahib Mahana, Wanming Hu", "educationalObjectives": "This study specifically investigates the influence of Large Language Models (LLMs) on the quality, consistency, and efficiency with which students create user stories and acceptance tests. It also addresses the need to determine whether LLMs help students overcome common challenges in writing user stories and creating acceptance tests that are correctly aligned with requirements. The overarching goal is to enhance the students' learning experience and improve the quality of the software projects they create. This can be achieved by exploring the impact of LLMs on user story creation within the educational context. Potential advantages include reducing time spent on repetitive manual tasks and improving the clarity and structure of user stories.", "aiEmployment": "The article analyzes the interaction between students and LLMs (Large Language Models) during the creation of user stories. Among its main applications, the LLM assisted in the initial drafting of user stories, based on brief descriptions provided by the users or the team. Furthermore, the AI contributes to the refinement of these user stories, suggesting improvements that enhanced clarity. The role of the AI primarily appears to be that of an assistant in the creation process.", "llm": "ChatGPT-3 and ChatGPT-4", "metrics": "Comparison of Time, Quality, Consistency, and Efficiency of User Stories", "metricsUsage": "The time and quality of user story creation (with and without AI) were compared, along with the precision in defining the acceptance criteria.", "resources": "The only supplementary material evidenced in the text was the use of LLMs.", "benefitsAndChallenges": "The study identified that the use of LLMs (Large Language Models) brought benefits such as improved clarity, structure, and quality of user stories and acceptance criteria, in addition to increasing student productivity and facilitating the adoption of Agile practices. Conversely, challenges were observed related to the risk of excessive dependence on AI, which could compromise the development of students' critical thinking. It also became evident that there is a need to provide adequate training so that students are capable of evaluating and refining the content generated by the AI, thus preserving their creativity and ensuring that the artifacts remain aligned with the requirements.", "swebokAreas": "Software Requirements", "swebokSubAreas": "Software Requirements Fundamentals", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3641555.3705183?casa_token=VJycYFTNtkMAAAAA:zA5br9yM4eYbs1VpvtIvd7Srl7lACuldWKOSH9bqIBU40Eaoupb1GYa00Ufl548yVM7BQ9fNC8-9Jg", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Evaluating GenAI's Effectiveness for Students with Varied Programming Backgrounds in a Software Development Course": { "id": "ID03", "level": "A", "year": "2025", "source": "SIGCSE", "authors": "Warren Liang, Wahib Mahana e Wanming Hu", "educationalObjectives": "The article specifically focuses on practical software construction education, evaluating how tools like ChatGPT and Codex impact programming learning. It investigates the use of these tools for code generation, debugging, problem-solving, and the comprehension of algorithms and data structures, in addition to measuring the quality and efficiency of the code produced. Developing coding and debugging skills, including the generation, optimization, and correction of code, using Generative AI (GenAI) as a support to identify errors and explore alternatives. The tools were utilized to generate code, debug, reinforce concepts, explore new technologies, and optimize solutions. Beginner students used them as support to learn and gain confidence, while advanced students employed them to increase productivity.", "aiEmployment": "Intermediate students receive suggestions for improvements and advanced features; and advanced students utilize AI as a productivity tool. The study assessed the effectiveness of Generative AI in software development courses using a mixed-methods approach, combining quantitative metrics—such as code quality, completion time, problem-solving, engagement, and knowledge retention—with qualitative student feedback.", "llm": "ChatGPT and Codex", "metrics": "Questionnaires, Time comparison, Accuracy of generated code, User satisfaction", "metricsUsage": "The study collected feedback from students with varying levels of knowledge to understand their perception of GenAI tools. Completion time was one of the metrics evaluated, along with code accuracy. The study sought to understand students' perception of GenAI tools.", "resources": "Traditional materials, such as textbooks, lectures, and in-person mentoring (or face-to-face mentoring), were used in the teaching process.", "benefitsAndChallenges": "Among the benefits are real-time personalized support, code generation, debugging assistance, improved comprehension of complex concepts, greater accessibility, and increased productivity for advanced students. The main challenges include the risk of over-reliance on AI, gaps in deep conceptual understanding, and the need for constant instructor guidance.", "swebokAreas": "Software Construction, Computing Foundations", "swebokSubAreas": "Practical Considerations, Programming Fundamentals and Languages", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3641555.3705175?casa_token=SbS4b3JEAc4AAAAA:0MgmDy-EMI1MA23_n5OjnxoiyRQK5Dzps2EGvFrn_BKYz2f8Fe700oY1ceSdoUcwruZ6_Sm7gXtl2w", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Learning without Limits: Analysing the Usage of Generative AI in a Summative Assessment": { "id": "ID04", "level": "A", "year": "2025", "source": "Computing Education Practice (CEP 2025)", "authors": "Lee Clift e Olga Petrovska", "educationalObjectives": "The paper reports that students directly utilized LLMs during an assessment in a mobile application development course. The study aimed to teach students how to use Artificial Intelligence in a critical and practical manner in software development. It sought to prepare them for the job market by integrating current technologies into the curriculum.", "aiEmployment": "Students developed mobile applications in two stages: a short design phase (2 weeks) and a longer development phase (7 weeks), with freedom to use any tool, including AI. The focus of the assessment was on the final product and project comprehension, not the code. Final-year students developed apps in two stages, with the freedom to use Generative AI as they wished. After the submission, they completed a self-reflection form regarding their use of AI. Quantitative analysis showed that 100% of the students used AI, especially ChatGPT, and the majority considered the experience positive. Qualitative analysis revealed common uses such as code generation and bug fixing, alongside comments on utility, frustrations, and perceptions.", "llm": "ChatGPT", "metrics": "Questionnaires, Likert Scale, User satisfaction", "metricsUsage": "A post-assessment self-reflection form was administered to the students upon project submission. Students were requested to rate specific aspects on a 5-point Likert scale, focusing on their satisfaction and perceptions regarding the experience.", "resources": "Students utilized Dart, Flutter, and a standard IDE for app development, supported by resources such as online forums and weekly practical laboratory sessions.", "benefitsAndChallenges": "GenAI, as a tool, brought numerous benefits, including a positive learning experience, more ambitious and higher-quality projects, and increased speed in programming by automating simple tasks. Among the challenges, the majority of students found the process of citing AI-generated code frustrating, while concerns regarding privacy were minimal.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3702212.3702214", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Effect of Large Language Model Use on Programming Project Groups": { "id": "ID05", "level": "A", "year": "2025", "source": "Proceedings of the Doctoral Consortium of the 19th European Conference on Technology Enhanced Learning", "authors": "Laura Graf", "educationalObjectives": "AI has provided an environment that can enhance students' self-efficacy and motivation. However, there are concerns that frequent use may reduce autonomy by fostering dependency and hindering the development of proprietary problem-solving strategies. Programming skills (such as coding, debugging, code comprehension), teamwork/team collaboration in software engineering.", "aiEmployment": "The study employed collaborative programming projects in university courses as the main teaching activity. These projects simulate real-world software development scenarios where student groups work together. Within the scope of this project, students individually utilized Large Language Models (LLMs) to assist in programming problem-solving. Each student interacted with the model according to their own needs, which reflected an autonomous and contextualized use of the technology. The approach focuses on observing how the integration of LLMs affects both individual learning and group dynamics. The study adopts a mixed-methods approach. The quantitative analysis is based on data automatically extracted from the collaborative development environments. The qualitative analysis, on the other hand, uses interviews, self-assessments, and group assessments to capture perceptions regarding learning, contributions, AI usage, motivation, confidence, and the development of professional identity.", "llm": "An exact model such as ChatGPT was not specified.", "metrics": "Self-reports, Student interviews, and Collaborative platform log data", "metricsUsage": "The metrics were used to analyze students' perceptions of learning, self-efficacy, professional identity, and group collaboration through self-reports and interviews. Furthermore, log data were employed to identify objective patterns of contribution and coordination among group members.", "resources": "Students participated in practical, group programming projects conducted within collaborative version control environments, which allowed for detailed tracking of contributions and interactions among team members. Upon completion of the practical activity, self-assessment materials and interviews were administered to record individual and collective perceptions regarding learning, group collaboration, and the use of AI in the educational process.", "benefitsAndChallenges": "Some evidenced benefits include support in code comprehension, rapid generation of solutions, and increased confidence and motivation for less experienced students. As for the challenges, the risks presented are dependency, difficulties in judging colleagues' competence, problems with contribution transparency, imbalance in group effort, and potential negative effects on the construction of professional identity.", "swebokAreas": "Professional Practice", "swebokSubAreas": "Group Dynamics and Psychology", "doiOrLink": "https://ceur-ws.org/Vol-3927/paper16.pdf", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Exploring the Integration of Generative AI Tools in Software Testing Education: A Case Study on ChatGPT and Copilot for Preparatory Testing Artifacts in Postgraduate Learning": { "id": "ID06", "level": "B", "year": "2025", "source": "IEEE EDUCATION SOCIETY SECTION", "authors": "Susmita Haldar, Mary Pierce, e Luiz Fernando Capretz", "educationalObjectives": "Utilizing LLMs as a pedagogical support, the study promotes the creation of test artifacts, the practical understanding of functional and non-functional testing, and the application of critical and systematic thinking. Students learn prompt engineering, comparative analysis between manual and AI-generated results, and the identification of tool limitations, such as hallucinations and lack of context. RQ1: Can a single teaching approach be effective for all types of testing, or do different contexts necessitate specialized methods? RQ2: What should be the role of AI-based testing within the curriculum, and how should it be implemented? RQ3: Does the incorporation of LLMs into testing education help students develop skills aligned with industry needs?", "aiEmployment": "The 15-week course began with students manually creating test artifacts in groups (use cases, Requirements Traceability Matrices – RTMs, test cases, and test scripts) to consolidate foundational knowledge. Subsequently, they conducted an individual activity utilizing AI tools (ChatGPT 3.5 or Copilot) to generate the same artifacts, enabling a comparison between the manual and the AI-generated outcomes. The study employed a mixed-methods approach to analyze student responses regarding the use of generative AI in education. The quantitative analysis was based on the counting of keywords in the responses (such as “use cases” and “RTM”), allowing for the assessment of the generated artifacts' completeness and the identification of patterns, with results visualized in comparative bar charts between ChatGPT and Copilot. The qualitative analysis was performed using the VADER tool, which classified the responses as positive, neutral, or negative, providing insights into the emotional tone of the students' perceptions.", "llm": "ChatGPT 3.5 and Copilot.", "metrics": "Questionnaires, Likert Scale, Time Comparison, Accuracy of Generated Code, User Satisfaction", "metricsUsage": "Questionnaires comprising 11 analytical items were administered, including Likert scales to measure students' perception of the efficiency of both ChatGPT and Copilot. The assessment evaluated the speed of generation, the accuracy of the artifacts, in addition to the error rate—specifically AI hallucinations—while sentiment analysis was used to gauge student satisfaction", "resources": "The study utilized real-world software applications, such as a travel application and MoneyManagerEx, in addition to the generative AI tools ChatGPT 3.5 and Copilot for teaching software testing.", "benefitsAndChallenges": "Copilot was more highly valued for its speed, whereas ChatGPT performed better regarding ease of use and test case coverage. Both tools aided in complementing manual work by offering support for brainstorming and providing models for comparison. However, students also identified challenges, such as the necessity for human supervision to validate the accuracy and relevance of the outcomes, in addition to the occurrence of hallucinations.", "swebokAreas": "Software Testing", "swebokSubAreas": "Testing of and Testing Through Emerging Technologies, Testing Techniques", "doiOrLink": "https://ieeexplore.ieee.org/abstract/document/10904141", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Exploring the Use of Large Language Models in Requirements Engineering Education: An Experience Report with ChatGPT 3.5": { "id": "ID07", "level": "B", "year": "2024", "source": "(SBQS 2024)", "authors": "Sávio Sampaio, Márcia Lima, Eriky Rodrigues, Maria Alcimar Meireles, Marcela Pessoa, e Tayana Conte.", "educationalObjectives": "This article seeks to promote the integration of technologies such as Large Language Models (LLMs) into teaching-learning processes, with a special focus on the requirements elicitation phase, which is a crucial step for the success of software projects. The central objective of the study is to investigate how the use of LLMs affects learning outcomes and socio-affective aspects in collaborative programming projects, especially among novice programmers.", "aiEmployment": "The teaching strategy is based on collaborative programming projects, and the research seeks to understand how students' integration of LLMs within this strategy affects their learning outcomes and socio-affective results. The study uses a mixed-methods approach, combining quantitative and qualitative analyses to investigate the effects of using LLMs in collaborative programming projects. The first focus will examine how the use of LLMs affects individual perceptions and group socio-affective attitudes, with data collected through self-assessments and interviews. The second focus will analyze process data obtained from code logs, AI interactions, and planning documents, seeking relationships between contribution patterns, perceived effort, confidence, mutual support, and identification with the field.", "llm": "ChatGPT 3.5", "metrics": "Questionnaires, Time Comparison, User Satisfaction", "metricsUsage": "The qualitative analysis focused on students' perceptions regarding the use of ChatGPT 3.5, specifically the advantages and disadvantages they observed. The teams/pairs utilized a spreadsheet for the assessment of the Functional Requirements (FRs) and Non-Functional Requirements (NFRs) generated by ChatGPT 3.5. In this spreadsheet, they responded to specific questions for each requirement generated by the AI, evaluating them under three main criteria: equivalence, innovation, and pertinence.", "resources": "The experience with ChatGPT 3.5 was structured with a detailed script (protocol), training, reports, assessment spreadsheets, and ethical consent.", "benefitsAndChallenges": "The study results reveal that students perceived ChatGPT 3.5 as a useful tool in Requirements Engineering, highlighting benefits such as the generation of equivalent or innovative requirements and the acceleration of the elicitation process with skills approaching those of requirements engineers. On the other hand, challenges were also identified, including the need for prior knowledge, inaccuracies in responses, confusion between requirement types, generation of generic or unnecessary requirements, and dependence on well-structured prompts.", "swebokAreas": "Software Requirements", "swebokSubAreas": "Requirements Elicitation, Requirements Analysis, Requirements Validation", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3701625.3701687?casa_token=6VuWOhinK_oAAAAA:FyS_qF-DyuUSKeHZyti5VtZOsFDpsmaQyErIe7XVM0ohP2R3S3gT1C7eakSJ8YWoM4mAhV7sY5AwRw", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Integrating AI Tutors in a Programming Course": { "id": "ID08", "level": "A", "year": "2024", "source": "SIGCSE Virtual 2024", "authors": "Iris Ma, Alberto Krone Martins, e Cristina Videira Lopes", "educationalObjectives": "The paper seeks to teach, through generative AI, primarily the comprehension of programming concepts, the development of problem-solving skills, and the mastery of challenging material in an introductory course. Furthermore, it promotes engagement, offering support for both task-specific queries and general programming questions.", "aiEmployment": "The teaching strategy focused on providing individualized and interactive support through generative AI, which acts as a guide, directing students toward reasoning and the discovery of solutions, rather than simply providing them. RAGMan was deployed as an optional resource for the students. The AI tutors were available 24/7, offering personalized, on-demand assistance. The AI primarily functioned as a tutor, specifically in the role of a Teaching Assistant. The prompts are neither fixed nor solely created by the students; they are automatically constructed by the system based on the students' free-form questions, but always within a pre-defined template set by the instructors, for example, to avoid giving direct answers about the code.", "llm": "The generative AI tool utilized was OpenAI, integrated into the RAGMan tutoring system.", "metrics": "Questionnaires/Surveys, Error Rate, User Satisfaction, AI Tool Usage Rate", "metricsUsage": "The survey/questionnaire sought student feedback regarding their overall experience with the AI tutors, including their perceived usefulness, advantages, and disadvantages. A random sample of 248 conversations (37% of the total) was analyzed to determine the quality of the responses. Students appreciated the AI tutors' ability to clearly explain assignments, provide step-by-step guidance, and, notably, create a safe, judgment-free learning environment. Finally, the study also quantified the general usage of AI tools, with 79% of students using at least one AI tool in the course.", "resources": "18 laboratory exercises, 5 major assignments, 5 Workout Projects (WPs) with optional 24/7 support from RAGMan AI tutors, and a final exam as part of the assessment.", "benefitsAndChallenges": "The perceived benefits of using LLMs included: effective help with projects, clear explanations, step-by-step guidance, a judgment-free environment, high-quality responses (94%), conversational ability, and potential support for struggling students. Conversely, the reported challenges were: tutor slowness, contradictory responses in some cases, lack of detailed explanations, and the risks associated with the use of unrestricted AIs, which can compromise learning by providing direct answers without stimulating reasoning.", "swebokAreas": "Software Construction, Computing Foundations", "swebokSubAreas": "Practical Considerations, Programming Fundamentals and Languages, User and Developer Human Factors, Artificial Intelligence and Machine Learning", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3649165.3690094", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Experiences from Integrating Large Language Model Chatbots into the Classroom": { "id": "ID09", "level": "A", "year": "2024", "source": "SIGCSE Virtual 2024", "authors": " Arto Hellas, Juho Leinonen e Leo Leppänen", "educationalObjectives": "The educational objectives include introducing the working principles and use of LLMs, applying these tools across the various phases of the Software Development Life Cycle (SDLC), and carrying out practical tasks such as documentation, programming, and testing with AI support. The focus is on skill updating and the integration of LLMs into professional software engineering practices. The article reports that students directly utilized LLMs in the educational context. They had access to a GPT-4-based chatbot, integrated into the course's learning platform, allowing for authentic and unfiltered interactions. The use was permitted to support learning, such as obtaining explanations, identifying code errors, or requesting assistance with tasks, but not for generating complete solutions. Most students (98%) in the course focused on Software Engineering with LLMs used the chatbot, indicating high adherence and perceived utility in this context. The Software Engineering with LLMs course aimed to teach students the working principles and use of Large Language Models (LLMs), with a focus on their practical application in software development life cycle tasks, such as documentation, programming, and testing. Furthermore, the course explored how LLMs can support code generation and the construction of complete applications, including problem decomposition and graphical interface development.", "aiEmployment": "The core strategy involved the direct integration of an LLM-based chatbot into the courses' online learning platform. Students were given unrestricted and free access to the chatbot, allowing them to use it similarly to ChatGPT. The chatbot was utilized as an assistive technology to support learning, for example, by explaining code, identifying errors, and offering assistance with programming tasks, but strictly without permitting the direct generation of solutions for assignments. In the Software Engineering with LLMs course, the chatbot was used in a central, curriculum-integrated manner, with practical activities involving documentation, programming, and testing with the assistance of the LLM, in addition to showcasing examples of code generation and application development. In the other courses, the usage was more limited, serving only as supplementary support. This approach also enabled the observation of student autonomy in their use of AI.", "llm": "ChatGPT 4.0", "metrics": "Questionnaires, User Satisfaction,", "metricsUsage": "A voluntary background survey was administered to the students. Furthermore, at the conclusion of each dialogue with the chatbot, students were asked to rate the chatbot's utility on a 1-to-5 star scale.", "resources": "The course utilized interactive e-books with embedded tasks hosted on an online learning platform, an AI chatbot (GPT−4) integrated into the course materials, practical projects, and programming exercises.", "benefitsAndChallenges": "Among the benefits, the high utility of the chatbot in the LLM-focused course was highlighted, evidenced by positive ratings and intensive use for solving programming problems and exploring code generation capabilities. Generally, students who used the chatbot considered it useful, especially for explaining code, identifying bugs (albeit with limitations), and offering assistance when they were stuck. Conversely, usage was low in the courses not focused on LLMs, concentrated among a small number of users ('superusers'). The limitations included the chatbot’s poor performance in debugging larger codebases and in supporting very recent technologies, such as Svelte 5 alpha and Deno KV, due to the lag in its training data. Furthermore, the AI tool did not replace human support, with students continuing to seek assistance in labs and on the platform.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3649165.3690101", "interaction": "Free Prompts", "analysis": "Quantitative", "usedByStudents": "Yes" },
    "Unrestricted Use of LLMs in a Software Project Course: Student Perceptions on Learning and Impact on Course Performance": { "id": "ID10", "level": "A", "year": "2024", "source": "Koli Calling ’24", "authors": "Kai Korpimies, Antti Laaksonen, Matti Luukkainen", "educationalObjectives": "The educational objectives included learning how to conceptualize, design, implement, test, and document an application, thereby developing competencies in development methodologies, version control, UML modeling, automated testing, and software design principles. The educational objectives for the software design course focused on aspects such as software development, design, testing, documentation, and quality. Generative AI was integrated as a support tool, not as the primary focus", "aiEmployment": "Course participants were freely permitted to utilize Large Language Models (LLMs) to develop a small application; the tool was employed as a programming assistance tool for students in a software design course. The prompts provided to the Generative AI were created by the students themselves. The closed-ended questions analyzed the frequency of LLM usage in tasks such as code generation and code improvement, as well as documentation. Meanwhile, the open-ended questions explored perceptions regarding the benefits and challenges of using these tools. The analysis considered student performance, the time invested in the project, and usage patterns, leading to the identification of two distinct groups.", "llm": "ChatGPT, Google Gemini, Microsoft Copilot and GitHub Copilot.", "metrics": "Questionnaires, Time Comparison, User Satisfaction", "metricsUsage": "he core methodology involved conducting surveys through an online form. The study compared the time invested by each student in the project (time-on-task). Part 2 of the survey consisted of open-ended questions where participants were able to elaborate on how beneficial they found the different uses of LLMs for the learning process.", "resources": "Online discussion environment, an initial in-person class, optional lab guidance, practical exercises on Git, testing, and UML, an online form about the use of LLMs, and support from teaching assistants.", "benefitsAndChallenges": "The study shows that students view LLMs as useful tools, highlighting benefits such as 24/7 personalized assistance, time savings, support in debugging, explanations, brainstorming, and motivation. However, concerns also arise regarding dependency, inconsistent answer quality, difficulty with prompt engineering, lack of context, and the risk of superficial learning.", "swebokAreas": "Software Construction, Computing Foundations", "swebokSubAreas": " Practical Considerations, Software Construction Fundamentals, Programming Fundamentals and Languages", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3699538.3699541", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Enhancing educational efficiency: Generative AI chatbots and DevOps in Education 4.0": { "id": "ID11", "level": "A", "year": "2023", "source": "Computer Applications in Engineering Education", "authors": "Edis Mekić, Mihailo Jovanović, Kristijan Kuk, Bojan Prlinčević e Ana Savić", "educationalObjectives": "The article addresses Software Engineering education, focusing on the practical and modern training of students by integrating agile methodologies, DevOps, and generative artificial intelligence into the teaching process, with an emphasis on code generation. The article teaches Content Management System development with a practical focus on object-oriented PHP, WordPress theme creation, and plugin development.", "aiEmployment": "ChatGPT is used as a support tool for debugging, code generation, reverse engineering, and solution creation, promoting a more active, autonomous, and efficient learning process. Efficiency metrics were used to compare groups of students who employed the traditional methodology with those who utilized AI and DevOps, demonstrating improvement in productivity and learning quality. ChatGPT acted as an auxiliary tool for debugging, generation, and refinement of solutions, while DevOps tools (Git, GitHub, Trello) facilitated version control and task management.", "llm": "ChatGPT 3.5", "metrics": "Production Rate", "metricsUsage": "The main form of assessment was through efficiency formulas based on artifact production rates.", "resources": "Slides and theoretical materials, practical programming exercises in PHP, templates and source code for developing WordPress themes and plugins, virtual environments for development and testing, in addition to digital tools such as ChatGPT for support in debugging and code generation, Git and GitHub for version control and collaboration, and Trello for task management.", "benefitsAndChallenges": "The study demonstrates that the use of LLMs in Software Engineering education yields significant benefits, such as accelerated learning, support for code generation and debugging, complex problem solving, and assisted reverse engineering, thereby increasing student efficiency and engagement. However, challenges were also identified, including the need for constant supervision and debugging by teaching staff, limitations in model comprehension, and risks of excessive dependency.", "swebokAreas": "Software Construction", "swebokSubAreas": "Practical Considerations", "doiOrLink": "https://onlinelibrary.wiley.com/doi/pdf/10.1002/cae.22804?casa_token=gUc2znEhjaYAAAAA%3AAZN58VQHYsX2SF1iLfFAL3deVH7LhJN5xKk4AVmqh4FUt_zVonhlL86azL8G9MRgeQIsgILwv9_5QAE", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "DevCoach: Supporting Students in Learning the Software Development Life Cycle at Scale with Generative Agents": { "id": "ID12", "level": "A", "year": "2024", "source": " Proceedings of the Eleventh ACM Conference on Learning", "authors": " Tianjia Wang, Ramaraja Ramanujan, Yi Lu, Chenyu Mao, Yan Chen e Chris Brown", "educationalObjectives": "The article about DevCoach highlights the primary educational objective of enabling students to practically understand and apply the Software Development Life Cycle (SDLC), with a focus on the planning, design, and development phases. The focus is on providing students with an in-depth understanding of the Software Development Life Cycle (SDLC) and the dynamics of teamwork.", "aiEmployment": "The DevCoach tool uses generative AI to simulate interactions with typical roles in a development team. The process included a pre-questionnaire to measure initial knowledge, a tutorial, the execution of tasks in the \"\"Plan and Design\"\" and \"\"Develop\"\" phases, a post-questionnaire, and a survey on usability and experience.", "llm": " GPT-4 Turbo", "metrics": "Questionnaires, Likert Scale, Time Comparison, User Satisfaction", "metricsUsage": "A pre-questionnaire and a post-questionnaire were administered to assess participants' understanding of the Software Development Life Cycle (SDLC). A Likert scale was utilized in a post-use survey (post-survey) to collect participants' opinions about the system. The time spent completing the tasks in each phase was monitored and recorded. Finally, user satisfaction was captured by the high average ratings given by the participants in the post-use survey.", "resources": "The system offers practical tasks with real-time feedback, a code editor, a terminal, and chat-based interactions. Tutorials, questionnaires, and a textbook are also utilized to support SDLC learning.", "benefitsAndChallenges": "DevCoach utilized AI with Large Language Models (LLMs) to simulate a development team and teach the Software Development Life Cycle (SDLC) in a practical, interactive, and personalized manner. The approach was highly rated, proven effective for learning, and faced no reported technical challenges.", "swebokAreas": "Software Engineering Process, Software Requirements", "swebokSubAreas": "Software Engineering Process Fundamentals, Life Cycles,Requirements Elicitation, Persona", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3657604.3664663", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "An Exploratory Study on Upper-Level Computing Students' Use of Large Language Models as Tools in a Semester-Long Project": { "id": "ID13", "level": "B", "year": "2024", "source": "ASEE 2024", "authors": "Ben Arie Tanay, Lexy Arinze, Siddhant S. Joshi, Kirsten A. Davis e James C. Davis", "educationalObjectives": "The study investigates how software engineering students are taught to use Large Language Models (LLMs) in core software lifecycle activities, such as requirements elicitation, design, implementation, testing, and project management. The course teaches, through project-based learning, all stages of the software engineering lifecycle, including technical aspects (such as requirements, design, implementation, and testing) and social aspects (such as ethics and teamwork).", "aiEmployment": "The course adopted a practical, project-based approach, requiring the mandatory use of Large Language Models (LLMs) throughout a semester-long team project. To support this integration, a specific module on LLMs was developed, including a lecture, hands-on instructions, and an applied assignment. Students were also required to describe the responsible use of these tools in their project plans. The study utilized a qualitative methodology, focusing on understanding how computer engineering students used LLMs in a project. Interviews were conducted with nine students at two points during the semester, and the data was analyzed using thematic analysis. This approach allowed for the identification of students' perceptions, experiences, and uses of LLMs in the educational context.", "llm": "ChatGPT and GitHub Copilot", "metrics": "User Satisfaction", "metricsUsage": "Students discussed how Large Language Models (LLMs) increased their productivity, the ease of access to information and solutions, and concerns regarding knowledge retention and dependency.", "resources": "The course utilized materials such as a dedicated AI module, practical assignments (or hands-on tasks), a revised curriculum (or syllabus), and online resources to integrate Large Language Models (LLMs) into software engineering education.", "benefitsAndChallenges": "Students in the course perceived that Large Language Models (LLMs), such as ChatGPT and Copilot, increased their productivity, facilitated access to information and solutions, and fostered greater autonomy in learning. However, they reported challenges such as potential detriment to knowledge retention, the need for technical prerequisites for effective use, the risk of dependency, and dilemmas concerning authorship and ethical use.", "swebokAreas": "Software Engineering Process", "swebokSubAreas": "Software Process Assessment and Improvement,  Life Cycles", "doiOrLink": "https://arxiv.org/pdf/2403.18679", "interaction": "Hybrid", "analysis": "Qualitative", "usedByStudents": "Yes" },
    "An Empirical Study on How Large Language Models Impact Software Testing Learning": { "id": "ID14", "level": "B", "year": "2024", "source": " EASE 2024", "authors": "Simone Mezzaro, Alessio Gambi, e Gordon Fraser", "educationalObjectives": "The article analyzes the use of Large Language Models (LLMs) in teaching software testing through the game Code Defenders and the AI assistant AI Defenders. It focuses on Software Testing, exploring concepts such as mutation testing, mocking, and student performance metrics. The article investigates how generative AI can support the teaching of Software Testing in Software Engineering, focusing on content such as testing concepts, mutation testing, mocking, and the writing of effective tests.", "aiEmployment": "Utilizing the gamified environment Code Defenders and an AI assistant, the study aims to help students comprehend testing technologies, apply concepts in practice, resolve doubts, and develop reasoning and problem-solving skills. The quantitative analysis compared performance with and without the AI, using the Wilcoxon test to check for statistical differences. The qualitative analysis, on the other hand, examined questions asked by students, the AI's responses, and student feedback on utility and expectations. The students' ability to correct errors generated by the AI was also assessed.", "llm": "GPT-3.5", "metrics": "Questionnaires, Error Rate, User Satisfaction.", "metricsUsage": "An optional questionnaire was administered at the end of the session. Code Defenders collected metrics on Failing Tests. Finally, satisfaction was evaluated through the survey responses regarding the perceived utility of the assistant.", "resources": "The gamified platform Code Defenders, an AI assistant (AI Defenders), real Java classes, and a survey for feedback were used.", "benefitsAndChallenges": "The study showed that LLMs, such as GPT, can offer useful explanations and help with conceptual doubts in Software Engineering education, but their unrestricted use may hinder learning. While some students benefited, the majority performed worse. Thus, the use of LLMs must be guided and mediated to prevent unrealistic expectations and misuse.", "swebokAreas": "Software Testing", "swebokSubAreas": "Testing Techniques", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3661167.3661273", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "The Impact of Large Language Models on Programming Education and Student Learning Outcomes": { "id": "ID15", "level": "A", "year": "2024", "source": "MDPI", "authors": "Gregor Jošt, Viktor Taneski e Sašo Karakatič", "educationalObjectives": "The article reports on the direct use of Large Language Models (LLMs) such as ChatGPT, Copilot, Bing Chat, and Gemini by students in a programming course. Over nine weeks, they were allowed to freely use these tools to generate code, debug bugs, and seek explanations, simulating a real-world programming environment. The article investigates how the informal and self-directed use of LLMs, such as ChatGPT and Copilot, by Software Engineering students impacts the learning of React with TypeScript and the development of essential skills (or core competencies) such as code generation, debugging, autonomous problem-solving, and seeking explanations.", "aiEmployment": "The students completed four projects over nine weeks, with the freedom to use LLMs for support, in addition to human assistance. Following this phase, they completed a final task without LLMs to assess independent learning. The experiment involved 32 participants and lasted 10 weeks: nine with free LLM use and one with restricted use. During the unrestricted phase, students carried out progressive tasks in React with TypeScript, with permission to use LLMs and support from tutors. In the controlled phase, they completed a task without LLMs, relying only on Google and the official documentation. After this phase, they responded to a questionnaire on their LLM usage habits, with responses collected on a Likert scale.", "llm": "ChatGPT, Google Gemini, Microsoft Copilot and GitHub Copilot.", "metrics": "Questionnaires, Time Comparison", "metricsUsage": "After the completion of the controlled phase task, participants filled out a questionnaire. This questionnaire was designed to gather feedback on their study habits and implementation strategies during the experiment. The study investigated the impact of using LLMs for code generation and debugging on student performance.", "resources": "The main resources utilized were practical programming tasks involving React and TypeScript, freedom to use LLMs, assistance from experienced tutors, and access to Google and official documentation during the AI-free phase.", "benefitsAndChallenges": "The study highlights that LLMs offer benefits such as support for additional explanations, quick access to information, aid in debugging, increased productivity, personalization of learning, and the stimulation of creativity, thus preparing students for an AI-infused future. However, challenges include the risk of excessive dependence that detrimental to critical and independent skills, the generation of incorrect information, and plagiarism.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages", "doiOrLink": "https://www.mdpi.com/2076-3417/14/10/4115", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "An Empirical Study on Usage and Perceptions of LLMs in a Software Engineering Project": { "id": "ID16", "level": "A", "year": "2024", "source": "(ICSE 2024)", "authors": "Sanka Rasnayaka, Guanlin Wang, Ridwan Shariffdeen, Ganesh Neelakanta Iyer", "educationalObjectives": "The research investigated the use of LLMs by 214 students working in teams, directly capturing and analyzing the AI-generated code, the prompts used to generate this code, and the levels of human intervention required to integrate the code into the project's codebase. The study investigated the students' autonomy in using LLMs in Software Engineering projects by encouraging them, without imposing, to integrate these tools as they deemed productive. The 214 students were free to choose between tools such as GitHub Copilot, ChatGPT-3.5, and 4, using them for different purposes.", "aiEmployment": "The study employed a project-based approach, simulating industry practices, where students worked in teams to develop a static analyzer in C++ over the course of the semester. The strategy included Agile methodologies, the use of tools such as JIRA and code review, in addition to the active and autonomous integration of LLMs into the workflow. Students also documented their AI usage, and a survey based on the UTAUT model was applied to analyze perceptions and prepare students for effective collaboration with AI.", "llm": "copilot, chatGPT-3.5 and chatGPT-4", "metrics": "Questionnaires, Likert Scale, Accuracy of generated code, User Satisfaction, Level of Human Intervention", "metricsUsage": "A voluntary online survey was conducted with 139 students to collect their perceptions, with many survey questions formulated on a 5-point Likert scale. Student satisfaction and perceptions were measured through the responses to the online survey and the two open-ended questions included. Finally, students were instructed to annotate the AI-generated code with the level of human intervention required to integrate it into the project.", "resources": "The materials used included a course website with information and requirements, code repositories for project development and submission, as well as industry tools like JIRA for Agile management. Practical exercises within the semester project and instructions for annotating AI-generated code were also utilized", "benefitsAndChallenges": "Student perceptions regarding the use of LLMs in the project highlighted benefits such as increased productivity, assistance in the initial phase, support with syntax and debugging, improvement in code quality, and simplification of repetitive tasks. However, concerns were also raised regarding the loss of coding skills, excessive dependence on AI, the need for human intervention to adjust the generated code, the impact on the job market, and the reduction in the tools' utility as project complexity increased.", "swebokAreas": "Software Construction, Software Engineering Process", "swebokSubAreas": "Life Cycles, Construction Technologies", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3643795.3648379", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "AI-Tutoring in Software Engineering Education Experiences with Large Language Models in Programming Assessments": { "id": "ID17", "level": "B", "year": "2024", "source": "International Conference on Software Engineering: Software Engineering Education and Training (ICSESEET)", "authors": "Eduard Frankford, Clemens Sauerwein, Patrick Bassner, Stephan Krusche, and Ruth Breu", "educationalObjectives": "The study specifically explores the experience and interaction of students with Large Language Models (LLMs), a powerful tool, in the context of an Introduction to Programming course. Another focus on the use of AI is its potential to personalize instruction, offer contextualized feedback, and support the development of fundamental skills, such as algorithmic thinking, debugging, and problem-solving. The objective also includes evaluating the efficacy of the AI as a support tool for the work of human tutors, enabling them to concentrate on more significant interactions with students. Students were tasked with solving a specific programming assignment: the implementation of Pascal's Triangle. The novelty of the study was the integration of an AI-Tutor (based on GPT-3.5-Turbo). Students had the option to request feedback from the AI on their current code at any time. The generative AI did not replace instruction but was integrated as a support tool to enhance the feedback experience, allowing students to receive additional and real-time guidance on their code during the problem-solving process.", "aiEmployment": "The study utilized a mixed-methods approach for data collection (combining empirical interaction data and survey data), but the primary analysis was qualitative, focusing on understanding the interaction patterns and the students' experiences with the AI-Tutor. The study's methodology involved three distinct stages: Integration: The GPT-3.5-Turbo model was integrated as an AI-Tutor into the Artemis platform, allowing students to solicit feedback on their code at any time. Practical Application: A practical application was conducted with novice programming students, who were given one week to implement Pascal's Triangle in C. Students had the option to choose whether or not to use the AI-Tutor. Assessment: A questionnaire based on the Technology Acceptance Model (TAM) was administered to evaluate the students' perception of ease of use and usefulness, and to gather qualitative feedback regarding their experience.", "llm": " GPT-3.5", "metrics": "Questionnaires, Likert Scale, User Satisfaction, Quality of AI Feedback", "metricsUsage": "The questionnaire aimed to collect students' experiences and perceptions regarding the use of the AI-Tutor. Responses to these questions were gathered using a Likert scale, and the analysis presented the average sentiment of these responses.", "resources": "The main resources utilized in the educational process included the Artemis system (APAS) with its online code editor, where students implemented Pascal's Triangle in C. Students were provided with a task description, an an initial template, and unit tests for automatic evaluation. Submissions were stored via GitLab, and the data was logged in a database. Following the activity, a questionnaire collected students' perceptions regarding the use of the AI-Tutor.", "benefitsAndChallenges": "The study identified benefits and challenges in using the AI-Tutor. Among the benefits, notable ones include immediate and scalable feedback, support for human tutors, the ability to provide broader feedback than unit tests, ease of adaptation through prompt engineering, and perceived ease of use. On the other hand, the challenges included generic feedback, low interactivity, lack of concrete examples, variable reliability (with 26.6% of the feedback considered unhelpful), and the risk of hindering independent learning.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3639474.3640061", "interaction": "Fixed Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Diverging assessments: What, Why, and Experiences": { "id": "ID18", "level": "B", "year": "2024", "source": "SIGCSE 2024", "authors": "Amin Sakzad, David Paul, Judithe Sheard, Ljiljana Brankovic, Matthew P. Skerritt, Nan Li, Sepehr Minagar, Simon e William Billingsly", "educationalObjectives": "The article primarily focuses on practical Software Engineering education, addressing the integrated teaching of construction, testing, security, configuration management, and computing fundamentals. The objectives include: teaching how to integrate AI into the problem-solving process, how to formulate effective prompts, and how to critically evaluate the responses obtained.", "aiEmployment": "Each student receives unique data (such as pcap files, VHDs, websites, or compiled programs), which prevents generic answers and encourages self-assessment, debugging, and peer discussion without compromising academic integrity. The strategy also allows and encourages the responsible use of generative AI tools. Independent surveys were conducted at three of the four participating universities, focusing on students' perceptions of the divergent assessments. The analysis yielded overall impressions, highlighting that students valued the assessments for reflecting real industry practices.", "llm": "ChatGPT", "metrics": "Questionnaires", "metricsUsage": "Independent surveys were conducted on the divergent assessments in courses at three of the four participating universities.", "resources": "The article describes the use of personalized assessments featuring unique data for each student, employing industry tools and environments to solve real-world problems. Preparatory materials and support for the use of generative AI were also provided.", "benefitsAndChallenges": "The study highlights that divergent assessments enable and incentivize the use of generative AI tools, promoting active learning, metacognition, and the development of strategic AI usage skills. Among the benefits are the personalization of the learning experience and the training of students for the conscious use of the technology. As a challenge, there are concerns regarding academic integrity, but the assessments maintain their validity by utilizing complex and specific data.", "swebokAreas": "Professional Practice", "swebokSubAreas": "Group Dynamics and Psychology", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3626252.3630832", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Computer Science Education in ChatGPT Era: Experiences from an Experiment in a Programming Course for Novice Programmers": { "id": "ID19", "level": "A", "year": "2024", "source": "MDPI", "authors": "Tomaž Kosar, Dragana Ostojić, Yu David Liu e Marjan Mernik", "educationalObjectives": "This study specifically focuses on the use of Large Language Models (LLMs) in the context of Software Engineering education. The research centers on the practical teaching of programming and software construction with AI support, assessing its pedagogical impact, as well as the quality, ethics, and educational processes involved. In this paper, fundamental skills for software developers are highlighted, such as the understanding of basic object-oriented concepts (classes, inheritance, methods), practical coding in C++, code analysis and modification, problem-solving, and critical thinking. The course covered content such as object-oriented programming in C++, practical coding, code analysis, comprehension, and refactoring.", "aiEmployment": "ChatGPT was primarily used by students to optimize and compare code, rather than to generate complete solutions. The study employed a mixed-methods approach, with an emphasis on quantitative analysis and qualitative elements, through a controlled experiment involving 182 introductory programming students divided into two groups. One group was incentivized to use ChatGPT, and the other was not. The quantitative analysis compared academic performance, specifically tasks, exams, and final grades. The qualitative analysis examined student perceptions via feedback questionnaires.", "llm": "GPT-3.5", "metrics": "Questionnaires, User Satisfaction", "metricsUsage": "The study administered initial, weekly, and final questionnaires to collect student data, monitor the use of ChatGPT, and evaluate perceptions and comprehension of tasks. Likert scales were utilized in some of the questionnaires. Participant satisfaction was primarily assessed through the feedback questionnaires.", "resources": "The course utilized a combination of lectures, practical assignments, supporting materials, IDEs (Integrated Development Environments), and paper-based assessments.", "benefitsAndChallenges": "The study identified that ChatGPT offers benefits such as learning support, enhanced code comprehension, motivation, and use for optimization and debugging. However, it also presented challenges, including risks of inaccuracy, excessive dependency, loss of essential skills, plagiarism, and difficulties in use by beginners.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "User and Developer  Human Factors, Programming Fundamentals and Languages", "doiOrLink": "https://www.mdpi.com/2227-7390/12/5/629", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Incorporating Generative AI into Software Development Education": { "id": "ID20", "level": "A", "year": "2024", "source": "Computing Education Practice (CEP 2024)", "authors": "Olga Petrovska, Lee Clift, Faron Moller, e Rebecca Pearsall", "educationalObjectives": "This article addresses Software Engineering education, focusing on the use of generative AI to support the teaching of programming, software construction, testing, and maintenance. Generative AI was employed in the study as a tool for direct integration into assessments. The prompts used in the study were created by the students themselves.", "aiEmployment": "Students generated and analyzed code and textual arguments, compared them with their own work, reflected on their experience with the tool, and discussed its limitations and implications. Data collection included online surveys with students and industry professionals, and experimental assessments involving practical tasks for generating and analyzing code and text. AI was employed both as a programming tool and as an object of critical analysis and ethical discussion.", "llm": "ChatGPT", "metrics": "Questionnaires, Likert Scale, Accuracy of generated code, User Satisfaction.", "metricsUsage": "Three anonymous online surveys were conducted to collect background data and opinions. First-year students evaluated the quality of pre-generated Java code by ChatGPT for a Stack class using a 5-point Likert scale. The summative assessment included the creation and use of a coding scheme to measure sentiment toward different tasks and the usability of GenAI.", "resources": "In the teaching process, the main resources used were ChatGPT for code and text generation and analysis, online surveys for data collection, pre-generated code and code developed by the students, in addition to written reflection activities and discussions on ethical and professional aspects.", "benefitsAndChallenges": "The study revealed that the use of LLMs like ChatGPT in Software Engineering education brings benefits such as increased efficiency, time savings, idea generation, and programming support, in addition to preparing students for the job market. However, challenges exist, including limitations in the quality and robustness of the generated code, difficulties with specific languages, and criticisms regarding the quality of the texts produced.", "swebokAreas": "Professional Practice", "swebokSubAreas": "Professionalism", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3633053.3633057", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Analyzing the uses and perceptions of computer science students towards generative AI tools": { "id": "ID21", "level": "A", "year": "2024", "source": "Não identifiquei", "authors": "Alisha HASAN, Bogdan SIMION, Florin POP", "educationalObjectives": "Reinforce knowledge, enhance programming and prompt engineering skills, develop effective learning habits, and teach the ethical and responsible use of AI. Students employ Generative AI (GenAI) as an auxiliary tool to learn concepts, generate code, and review text, treating it as a personalized tutor.", "aiEmployment": "The main focus of the article was to analyze how Computer Science students themselves are already utilizing and perceiving these tools in their learning process. The prompts are created and refined by the students themselves. The study employed a data collection approach using a questionnaire that included Likert scale questions (quantitative) and open-ended questions (qualitative). The quantitative analysis identified patterns of use and perceptions regarding GenAI, while the qualitative analysis extracted themes from the open-ended responses.", "llm": "ChatGPT and GitHub Copilot", "metrics": "Questionnaires, Likert Scale, User Satisfaction", "metricsUsage": "The data was collected using a questionnaire distributed to Computer Science students across three institutions. The questionnaire included Likert scale questions. Students' overall satisfaction was analyzed based on their positive perceptions of GenAI's usefulness and assistance in the learning process.", "resources": "The study does not describe specific pedagogical materials or resources utilized by the institutions.", "benefitsAndChallenges": "The study highlights benefits such as time saving, increased productivity, learning support, and ease of use. Simultaneously, students pointed out challenges like the risk of over-reliance (or over-dependence), inaccuracy of responses, and concerns regarding privacy, bias, and skill degradation (or loss of skills).", "swebokAreas": "Computing Foundations", "swebokSubAreas": "User and Developer  Human Factors, Programming Fundamentals and Languages", "doiOrLink": "https://ibn.idsi.md/sites/default/files/imag_file/ICVL_2024.pdf#page=363", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "A Conceptual Framework to Transform Coding Education in Times of Generative AI": { "id": "ID22", "level": "B", "year": "2024", "source": "Lecture Notes in Informatics (LNI)", "authors": "Stefan Bente, Natasha Randall, Dennis Wäckerle", "educationalObjectives": "The study addresses the necessity of adapting Software Engineering curricula, specifically focusing on coding education, due to the use of generative AI tools like ChatGPT. Initially, the goal is for students to learn the basics of coding, applying syntax rules to small-scale tasks.", "aiEmployment": "The objective is to teach students how to strategically interact with and utilize generative AI tools within the context of coding education, in addition to ensuring the development of fundamental programming skills. Instead of using AI merely as a tool to generate code for simple exercises, the study seeks the critical evaluation of AI's capabilities and limitations in coding, and the strategic and autonomous integration of AI in solving high-complexity Software Engineering problems. The article adopts an educational strategy based on a framework that guides coding instruction in Software Engineering. This approach organizes the students' learning journey into three stages based on Bloom’s Revised Taxonomy and the complexity of the coding tasks. Stage 1: The focus is on coding fundamentals, with the prohibition of using AI tools such as ChatGPT and GitHub Copilot. The strategy is centered on hands-on experience, allowing students to develop technical knowledge without resorting to shortcuts. Stage 2: Students advance to what is called \"\"unassisted coding\"\", where the use of AI is permitted and explicitly integrated into the pedagogical activities. In this phase, activities are proposed such as analyzing AI-generated code, comparing it with self-developed solutions, refactoring, debugging, and reflecting on the use of the tools. The main goal is to develop AI literacy among participants, empowering students to identify the strengths and limitations of these technologies and to use them critically and consciously. Stage 3: Students are given broader-scoped tasks involving the unrestricted and implicit use of AI tools.", "llm": "ChatGPT 4.0, ChatGPT 3.0 and GitHub Copilot", "metrics": "Time Comparison, Ability to Handle Scope and Complexity", "metricsUsage": "The study explicitly analyzed how the AI's capability varied with the scope (code size) and the cognitive complexity (Bloom's level) of the tasks.", "resources": "The main materials and resources utilized in the teaching process include coding exercises and tasks with varying levels of complexity and modules, digital examinations conducted in the laboratory, generative AI tools, task descriptions, as well as development environments and computer labs.", "benefitsAndChallenges": "Among the benefits, the study highlights the ability to quickly and accurately generate low-scope code, assist in error detection, support the learning of new technologies, and perform effective refactoring. Conversely, the challenges involve the risks of misuse (such as replacing learning with copying), cognitive overload for beginners, difficulties in tasks with complex logic or architectural principles, and limitations in assessment, requiring new exam formats and grading criteria.", "swebokAreas": "Professional Practice, Software Construction", "swebokSubAreas": "Professionalism, Practical Considerations", "doiOrLink": "https://dl.gi.de/server/api/core/bitstreams/64e215b9-70d1-427d-ba07-550a21a1f8f6/content", "interaction": "Fixed Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Twisted Games: A First Experience of Inclusion of AI tools in First Year Programming Classes": { "id": "ID23", "level": "A", "year": "2024", "source": "Latin American Conference on Computational Intelligence (LA-CCI)", "authors": "Pedro Wightman", "educationalObjectives": "This mapping specifically addresses the integration of Large Language Models (LLMs) within the context of Software Engineering education. It aims to develop students' capacity to define and adapt high-level requirements, craft effective prompts, test and debug AI-generated code, and integrate these components into existing systems. Students were responsible for defining and adapting requirements, utilizing LLMs in an iterative development process, creating and refining prompts, debugging code, and making project decisions such as the programming language and the specific AI tool used. The research indicated that the majority felt capable of defining requirements, although many found it challenging to express them in effective prompts.", "aiEmployment": "The study adopted a Project-Based Learning (PBL) strategy, integrating collaboration with generative AI tools in an introductory programming course. Students developed modified versions of classic games with direct support from Large Language Models (LLMs) of their choice, such as ChatGPT and Copilot, following an iterative process of prompt creation, evaluation, debugging, and refinement. The research employed a mixed-methods approach to evaluate the students' experience using Artificial Intelligence (AI) tools in programming classes, combining qualitative and quantitative analyses. The qualitative analysis was based on the final reports prepared by the student groups. These reports included records of development milestones, the prompts used, screenshots, and reflections on the process and the final outcome. The quantitative analysis, in turn, was conducted using a questionnaire administered to all students, which collected data on the use of the AI tools and their perception of the experience. The results showed that the majority of students used ChatGPT, followed by other tools like Claude, Copilot, and Gemini, primarily for research and text generation.", "llm": "ChatGPT was the most used generative AI tool and considered most effective by students, followed by Claude, Copilot, and Gemini.", "metrics": "Questionnaires, Time Comparison, User Satisfaction", "metricsUsage": "A survey was administered to all students to assess their perception and the impact of the experience on their programming competencies (or skills). Students evaluated the perceived time savings. Ninety-two percent (92%) of students agreed that the AI tool saved them time on coding compared to starting from scratch. The overall satisfaction and student perception ultimately indicated a positive student experience.", "resources": "The study utilized modified and challenging game projects as its practical basis. The process involved iterative interaction with the AIs, documentation in final reports, and a perception survey.", "benefitsAndChallenges": "The study's findings indicate that students had a positive perception regarding the use of LLMs in programming classes, highlighting benefits such as time savings, assistance with coding, useful feedback, and improvements in professional skills (or competencies). The majority intend to continue using these tools in the future. However, they faced challenges with prompt creation, debugging, and the learning process for the tools themselves.", "swebokAreas": "Software Construction, Computing Foundations", "swebokSubAreas": "Practical Considerations, Programming Fundamentals and Languages, User and Developer Human Factors", "doiOrLink": "https://ieeexplore.ieee.org/document/10814750?denied=", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Investigating Developers' Preferences for Learning and Issue Resolution Resources in the ChatGPT Era": { "id": "ID24", "level": "A", "year": "2024", "source": "International Conference on Software Maintenance and Evolution (ICSME 2024)", "authors": "Ahmad Tayeb, Mohammad Alahmadi, Elham Tajik e Sonia Haiduc", "educationalObjectives": "The paper focuses on Education, specifically within the context of programming learning, coding problem-solving, and technology exploration, utilizing AI tools as complements or substitutes for traditional methods such as video and written tutorials. The study highlights the use of AI for concept comprehension, code development and refinement, personalized learning support, information synthesis, task automation, and, to a lesser extent, academic assistance and ethical considerations.", "aiEmployment": "The principal uses include queries for concept explanation, problem-solving and debugging, code generation and refinement, learning with personalized support, exploration of new technologies, information synthesis, and automation of practical tasks. The study employed a mixed-methods approach to analysis, combining quantitative and qualitative methods. The quantitative analysis was based on questionnaires with multiple-choice and ranking questions, allowing for the calculation of the average preference for different learning resources and the frequency of ChatGPT use. The qualitative analysis, on the other hand, was performed using 1,520 open-ended responses.", "llm": "ChatGPT", "metrics": "Questionnaires, User Satisfaction, Frequency of LLM Use", "metricsUsage": "The primary data collection tool was a questionnaire structured into four sections. The perceived advantages of the AI chatbots and frequent usage serve as indirect indicators of user satisfaction or acceptance regarding the features. Responses indicated usage levels such as weekly, daily, monthly, rarely, or never. ", "resources": "The materials utilized included video and written tutorials, API documentation, AI chatbots, question-and-answer forums (or Q&A forums), search engines, discussion platforms, and books.", "benefitsAndChallenges": "The main reported benefits include efficiency, accessibility, personalized responses, on-demand educational support, technical coding assistance, information summarization, and interactivity. Participants valued the speed of the responses and the AI's adaptability to their queries. On the other hand, the most frequently cited challenges were the limited reliability of the responses, the risk of over-reliance (or excessive dependency), technical limitations, difficulties in prompt formulation, barriers to deep understanding, and ethical concerns.", "swebokAreas": "Professional Practice", "swebokSubAreas": "Professionalism", "doiOrLink": "https://ieeexplore.ieee.org/document/10795042?denied=", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "How LLMs Aid in UML Modeling: An Exploratory Study with Novice Analysts": { "id": "ID25", "level": "A", "year": "2024", "source": "Software Services Engineering (SSE 2024)", "authors": "Beian Wang, Chong Wang, Peng Liang, Bing Li eCheng Zeng", "educationalObjectives": "The article investigates how Large Language Models (LLMs), such as ChatGPT, assist students in the creation of UML diagrams from textual descriptions. Furthermore, it discusses AI fundamentals, professional practices, and educational and industrial implications. The educational objectives in Software Engineering, within the context of requirements analysis and UML modeling, include: Teaching students how to create UML models (use case, class, and sequence diagrams). Equipping them to use LLMs as auxiliary tools with a critical eye and without excessive dependency. The study aims to teach and assess the skill of creating UML models (use case, class, and sequence diagrams) with the support of LLMs, developing students' proficiency in the critical use of these tools.", "aiEmployment": "The study utilized a Project-Based Learning (PBL) approach, in which undergraduate Software Engineering students applied their UML modeling knowledge with the aid of LLMs such as ChatGPT. The central activity involved the creation of models for a case study, with the submission of diagrams and the interaction history with the AI. The study employed a predominantly quantitative methodology, with qualitative elements in the interpretation of the results. Conducted with 45 Software Engineering students, the experiment involved the creation of three UML models (use case, class, and sequence diagrams) with the mandatory assistance of LLMs, such as ChatGPT. The output formats and the interaction patterns with the LLMs were also assessed, highlighting that the best results were obtained through hybrid approaches involving human intervention.", "llm": "ChatGPT 3.5 and ChatGPT 4.0", "metrics": "Correction Rate", "metricsUsage": "For each evaluation criterion defined for the UML models, the correction rate was calculated.", "resources": "In the experiment, the students used a case study, LLMs, and tools such as StarUML to create UML models.", "benefitsAndChallenges": "The study showed that LLMs, such as ChatGPT, can assist novice students in UML model creation, proving effective at identifying elements like classes, use cases, and objects. However, they face difficulties in correctly representing the relationships between these elements and may generate inconsistent output or information loss.", "swebokAreas": "Software Requirements, Software Design", "swebokSubAreas": "Requirements Specification, Recording Software Designs", "doiOrLink": "https://ieeexplore.ieee.org/document/10664407?denied=", "interaction": "Free Prompts", "analysis": "Quantitative", "usedByStudents": "Yes" },
    "Teaching UML using a RAG-based LLM": { "id": "ID26", "level": "A", "year": "2024", "source": "International Joint Conference on Neural Networks (IJCNN)", "authors": "Pasquale Ardimento, Mario Luca Bernardi e Marta Cimitile", "educationalObjectives": "The article's primary focus is the teaching of UML in Software Engineering courses. It aims to understand and improve student behavior and capabilities during modeling activities. The system seeks to support professors in student monitoring and assessment and reduce the teacher's effort. (Software Engineering Models and Methods) (Modeling, Methods, and Techniques). The paper proposes an approach utilizing a cloud-based tool that employs a Large Language Model (LLM) with Retrieval-Augmented Generation (RAG) to provide personalized feedback to students.", "aiEmployment": "The strategy involves the integration of a supervised and non-intrusive modeling environment capable of automatically capturing and analyzing the UML diagrams created by students. Using the UML Info plugin, the graphical diagrams are converted into text and stored in a vector repository. When a student or professor submits a prompt, the system retrieves relevant information and sends it, along with the context, to LLaMA, which then generates personalized feedback. In the quantitative analysis, the objective was to measure the precision, recall, and F1 score of the system's responses in identifying entities and relationships within the UML diagrams. A set of 422 diagrams from the ModelSet database were used, and the system's responses were compared against expert-provided annotations. The results showed that the configuration with RAG (Retrieval-Augmented Generation) consistently outperformed the non-RAG version across all metrics, proving to be more relevant than simply increasing the size of the LLaMA model. For the qualitative analysis, 12 participants (students, experts, and novices) interacted with the system and responded to a questionnaire containing open- and closed-ended questions. The analysis indicated a significantly positive perception regarding the usability, accuracy of suggestions, and utility of the feedback, based on statistical tests.", "llm": "LLaMA", "metrics": "Questionnaires, Likert Scale, T-tests", "metricsUsage": "T-tests were performed to test whether the users' perception of the system was significantly better than a neutral value. A comprehensive questionnaire was administered to 12 participants following their interaction with the system. The questionnaire contained both closed-ended and open-ended questions. Responses to the closed-ended questions were quantified using a Likert scale from 1 to 5.", "resources": "The study utilizes UML diagrams created by students, a cloud-based modeling environment, and LLaMA models for automated feedback generation as its primary resources.", "benefitsAndChallenges": "The main benefits include providing automated and immediate feedback, which assists students in correcting errors and improving their capabilities, as well as reducing teacher effort in monitoring and assessment. On the other hand, the study also identified challenges, such as the precision limitations of the LLMs, the influence of biases in the training data, the difficulty of replicating results due to the variability in responses, and the limitation in generalizing the findings, since the utilized data is specific to the aviation industry.", "swebokAreas": "Models and Methods", "swebokSubAreas": "Modeling, Analysis of Models", "doiOrLink": "https://ieeexplore.ieee.org/document/10651492?denied=", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Cultivating Software Quality Improvement in the Classroom: An Experience with ChatGPT": { "id": "ID27", "level": "B", "year": "2023", "source": "(CSEE&T) 2024", "authors": "Eman Abdullah AlOmar e Mohamed Wiem Mkaouer", "educationalObjectives": "The study addresses various educational objectives in Software Engineering, such as fostering a culture of bug fixing and software quality improvement through the use of tools like PMD, as well as developing students' code debugging skills and their ability to recognize poor programming practices. It also aims to promote the critical use of LLMs like ChatGPT, stimulating students' analytical reasoning, the validation of generated responses, and awareness of their limitations. Students utilized the tool to analyze problems identified by PMD, decide on their relevance, and suggest corrections. A total of 102 submissions were analyzed, with students being instructed to critically validate the model's responses. The study also included prior training and required students to report their use of ChatGPT. According to the survey, 85.9% considered the tool useful in the debugging process.", "aiEmployment": "The article proposes the use of ChatGPT as a support tool in Software Engineering and Computer Science education, focusing on software quality improvement and bug fixing. The contents and skills taught to students include: code debugging, identification and refactoring of poor practices, understanding of static code analysis, and development of analytical and critical thinking. The study adopted a mixed-methods approach, combining quantitative and qualitative analyses, with the goal of investigating the use of PMD and ChatGPT in teaching software quality assurance. Conducted within a course involving 102 undergraduate and graduate students in Software Engineering and Computer Science, the study involved the inspection of open-source Java projects using PMD to identify and discuss quality issues. Data were collected from 102 submissions, totaling 1,230 analyzed rules, and via an online survey with open- and closed-ended questions regarding the students' experience with ChatGPT. The quantitative analysis examined the types of problems selected, the correction time by category, and the degree of success of ChatGPT based on the feedback. The qualitative analysis involved the categorization of student comments and the evaluation of the produced artifacts.", "llm": "ChatGPT", "metrics": "Questionnaires, Time Comparison, Accuracy of Generated Code", "metricsUsage": "The study utilized an online survey (with 6 open-ended and 16 multiple-choice questions) to collect feedback from 102 students regarding their use of ChatGPT, addressing demographics, utility, and accuracy. The correction time by problem type and the quality of the generated solutions were also analyzed. Although 85.9% considered ChatGPT useful, 20.4% reported regressions, and 13.6% noted new violations generated by the corrections.", "resources": "The activity was integrated into a software quality course and included lectures, supporting materials, detailed instructions, and an online questionnaire to collect student feedback on the use of ChatGPT.", "benefitsAndChallenges": "Among the benefits, key points include debugging automation, improved code quality, detailed explanations, ease of use, and the stimulation of critical thinking. Students also perceived ChatGPT as a helpful \"\"coding companion,\"\" especially for novices. Conversely, the main challenges included its limitation in understanding complex contexts, the introduction of regressions, dependence on prompt quality, lack of originality, difficulty with propagated problems (e.g., those arising from cascading errors), and the necessity of human validation.", "swebokAreas": "Software Quality", "swebokSubAreas": "Software Quality Assurance Process", "doiOrLink": "https://ieeexplore.ieee.org/document/10663028?denied=", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Using Generative AI to Create User Stories in the Software Engineering Classroom": { "id": "ID28", "level": "B", "year": "2024", "source": "Conference on Software Engineering Education and Training (CSEE&T)", "authors": "Allan Brockenbrough e Dominic Salinas", "educationalObjectives": "The educational objectives in Software Engineering, with the introduction of Generative AI, include: emphasis on skills beyond coding, such as requirements, design, and testing; teaching the fundamentals of requirements engineering, including structured user stories, Definition of Done (DoD), and traceability; and evaluating artifact quality using frameworks like INVEST. The article aims to teach the fundamentals of requirements engineering, focusing on the structured creation of user stories, including elements such as Definition of Done and traceability.", "aiEmployment": "Students performed a practical task based on user feedback and were divided into two groups: one utilizing ChatGPT 3.5 and one without. The strategy promoted the creation and critical evaluation of requirements both with and without AI assistance, encouraging the conscious use of technology. The study conducted a quantitative analysis to evaluate the quality and creation time of user stories with and without the use of ChatGPT. The user stories were assessed by two professors based on the INVEST model. A total of 75 user stories were analyzed (38 with AI, 37 without). The task completion time was also measured. The results showed that the AI group produced higher-quality stories and was, on average, 38.1% faster.", "llm": "ChatGPT 3.5", "metrics": "Time Comparison, User Stories", "metricsUsage": "The study analyzed the quality of the user stories using an INVEST classification system. The study also investigated the impact of ChatGPT on the time students took to create the user stories.", "resources": "Materials used included a theoretical lecture on user stories and an explanation of the standard format. Following the lecture, students performed a practical task based on fictitious feedback.", "benefitsAndChallenges": "The use of ChatGPT in user story creation resulted in 17% higher quality, a greater proportion of high-quality stories (58%), and 38.1% faster completion. It excelled particularly in grammar and traceability, but showed limitations in grouping related feedback, creating detailed Definitions of Done, and maintaining consistency. Despite being useful, ChatGPT did not guarantee consistent quality and required critical review from the students.", "swebokAreas": "Software Requirements", "swebokSubAreas": "Requirements Elicitation, Requirements Specification", "doiOrLink": "https://ieeexplore.ieee.org/document/10662994?denied=", "interaction": "Fixed", "analysis": "Quantitative", "usedByStudents": "Yes" },
    "Automated Programming Exercise Generation in the Era of Large Language Models": { "id": "ID29", "level": "C", "year": "2024", "source": "CSEE&T 2024", "authors": "Niklas Meißner, Sandro Speth, Steffen Becker", "educationalObjectives": "Generative AI is used to assist in the creation of exercises aimed at developing practical programming skills and the comprehension of fundamental and advanced concepts within a beginner-to-intermediate-level programming course.", "aiEmployment": "The underlying teaching strategy is practice-based and problem-solving learning, where students acquire programming skills by executing exercises on specific topics. The study employed a mixed-methods analysis, combining qualitative and quantitative approaches. The qualitative component involved the manual assessment of the quality of the exercises generated by the LLM tools, based on criteria such as accuracy, relevance, and completeness, in addition to the researchers' usability analysis of the tools. The quantitative analysis, on the other hand, considered the number of prompts required to obtain satisfactory responses, as a measure of the simplicity of the generation process.", "llm": "ChatGPT, Bing AI Chat and Google Bard", "metrics": "Quality of Generated Exercises", "metricsUsage": "The quality analysis of the generated exercises was predominantly qualitative, with complementary categorization. It utilized the evaluation criteria to classify the exercises as \"\"poor,\"\" \"\"mediocre\"\" (or \"\"average\"\"), or \"\"good.\"\" The assessment was conducted manually by the researchers, considering aspects such as adherence to object-orientation, creativity, correctness, use of API descriptions, and the inclusion of intentional errors.", "resources": "The materials included Java code, API descriptions, and tasks covering flow control, advanced Object-Oriented Programming (OOP), and error identification. These resources were used to support practical programming instruction.", "benefitsAndChallenges": "Among the main benefits are the simplification and efficiency of the creation process, the generation of initial drafts and quality variants, and the standout performance of ChatGPT with GPT-4 as the most effective tool, especially for topics like OOP (Object-Oriented Programming), API usage, flow control, and error identification. On the other hand, the challenges include the need for manual refinement of the generated exercises, error patterns in complex concepts, and the limited performance of other tools like Bing AI Chat and Google Bard, which struggled to produce useful exercises.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages", "doiOrLink": "https://ieeexplore.ieee.org/document/10662984/?denied=", "interaction": "Fixed", "analysis": "Mixed", "usedByStudents": "No" },
    "Students' Perspectives on AI Code Completion: Benefits and Challenges": { "id": "ID30", "level": "A", "year": "2024", "source": "Annual Computers, Software, and Applications Conference (COMPSAC)", "authors": "Wannita Takerngsaksiri, Cleshan Warusavitarne, Christian Yaacoub, Matthew Hee Keng Hou, Chakkrit Tantithamthavorn", "educationalObjectives": "The article discusses the perspectives of computer science students on AI code assistance in the context of programming education. Through an analysis of student benefits, challenges, and expectations, it highlights the importance of students developing a deep understanding of programming concepts, strong problem-solving skills, creativity, the ability to critically evaluate code, and adherence to best practices. The issue of over-reliance on automation is also addressed.", "aiEmployment": "The students utilized the AutoAurora tool as a Visual Studio Code extension to complete programming tasks; specifically, the students used AutoAurora as an intelligent coding assistant within Visual Studio Code to aid in programming problem-solving. The participants used this tool to perform two competitive programming tasks in Python, involving string, file, and array manipulation. During the activities, the AI generated real-time code suggestions, which the students could accept or ignore. Furthermore, they were able to adjust the tool's settings, such as the number of lines and suggestions generated, to explore its functionality and potential. The analysis conducted in the study was qualitative. Ten undergraduate computer science students from Monash University, Australia, were interviewed. The participants were aged between 18 and 22 and had at least one year of programming experience. The participants used the AutoAurora tool to complete two competitive programming tasks in Python. The tasks included string and text file manipulation, and array manipulation. Following the completion of the tasks, an interview composed of open-ended questions was conducted to collect participant feedback on code completion tools in the educational context. The interviews were recorded and transcribed.", "llm": "AutoAurora, a tool developed by the researchers themselves to serve as a research instrument.", "metrics": "User Satisfaction and Open-Ended Question Interviews", "metricsUsage": "The students' perceptions regarding the benefits, challenges, and expectations of AI code completion were the central focus of the study. Interviews were the primary data collection methodology. The data were recorded and transcribed. Grounded Theory was used to analyze the interview transcripts.", "resources": "The AutoAurora extension for Visual Studio Code, specifically developed for the study, is based on the StarCoder AI model and offers code completion suggestions. Two practical programming tasks in Python were applied, focusing on string, text file, and array manipulation, such as reading and processing files and generating modified outputs.", "benefitsAndChallenges": "The study highlights that AI tools, such as coding assistants, can boost productivity, aid in syntax learning, and suggest best practices and alternative solutions, thus serving as a support in the coding process. Conversely, it warns of challenges, such as the risk of over-dependence, the need to critically evaluate the AI-generated code, and the importance of revising assessment methods, including documentation, oral interviews, and randomized evaluations. Furthermore, students expect the tools to offer code explanations, refactoring suggestions, and customization, which opens the door for future improvements in the use of AI in programming education.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages", "doiOrLink": "https://arxiv.org/pdf/2311.00177", "interaction": "Free Prompts", "analysis": "Qualitative", "usedByStudents": "Yes" },
    "Developing Critical Thinking Practices Interwoven with Generative AI usage in an Introductory Programming Course": { "id": "ID31", "level": "B", "year": "2024", "source": "EDUCON 2024", "authors": " Arne Styve, Outi T. Virkki, e Usman Naeem", "educationalObjectives": "The main motivation of the study was to investigate how to design learning activities that introduce generative AI tools (GitHub Copilot and ChatGPT) for programming, while promoting critical thinking practices among students in an introductory programming course. The key objectives include: fostering comprehensive mastery in programming, moving beyond simple language learning toward building robust and sustainable solutions; adopting good Software Engineering practices from the outset, with emphasis on code quality and readability, coding style, design principles such as SOLID, unit testing, and robustness. The course also seeks to teach the responsible use of generative AI tools, such as GitHub Copilot and ChatGPT, by encouraging critical thinking to evaluate the reliability and security of the generated code. The paper reports that students directly utilized tools based on Large Language Models (LLMs) in an introductory programming course. Specifically, they used GitHub Copilot as an aid for generating code and ChatGPT 3.5 as a \"\"peer reviewer\"\" to analyze that code. The study's goal was to integrate these tools into the learning process while simultaneously encouraging the development of students' critical thinking skills.", "aiEmployment": "The proposal fostered reflection on the use of AI, promoting individual responsibility for software quality. Pre- and post-intervention research assessed changes in critical thinking practices, and the assessment was conducted via a portfolio, rather than a written examination, favoring an approach more aligned with the practical use of AI. The study adopted a mixed-methods methodology, with an emphasis on quantitative data, characterizing it as a study. It was conducted in an introductory Object-Oriented Programming (Java) course aimed at first-semester students. The main intervention was the \"\"AI with CT\"\" task, which integrated the use of the GitHub Copilot and ChatGPT tools with the objective of promoting the responsible use of AI and the development of critical thinking. Data collection combined quantitative and qualitative instruments. Out of the 90 students in the course, 55 responded to the questionnaires, and 88 submitted the assignment with their reflections.", "llm": "ChatGPT 3.5 and GitHub Copilot", "metrics": "Questionnaires, Likert Scale, User Satisfaction, Behavioral Change Analysis", "metricsUsage": "Questionnaires were administered before and after the intervention to collect students' opinions and practices related to programming and studying. Students were asked to critically analyze the code suggested by GitHub Copilot concerning the criteria for quality and robustness taught in the course. The responses from the pre- and post-intervention questionnaires were compared to observe changes in students' opinions and behaviors.", "resources": "The study utilized generative AI tools (GitHub Copilot and ChatGPT 3.5) integrated into IDEs such as IntelliJ and VS Code. Questionnaires and open-ended reflections were used to assess the development of students' critical thinking.", "benefitsAndChallenges": "Among the benefits, highlights include support for productivity, the reinforcement of understanding regarding code quality and robustness, and the stimulation of critical reflection, preparing students for the responsible use of these tools in the job market. Conversely, the challenges include the generation of inaccurate or incomplete code, risks to quality and security, a potential reduction in students' critical thinking and sense of responsibility, as well as difficulties in educational assessment and in combating the uncritical use of AI tools.", "swebokAreas": "Software Quality, Professional Practice", "swebokSubAreas": "Professionalism, Software Quality Assurance Process", "doiOrLink": "https://ieeexplore.ieee.org/document/10578746?denied=", "interaction": "Fixed", "analysis": "Mixed", "usedByStudents": "Yes" },
    "How Far Are We? The Triumphs and Trials of Generative AI in Learning Software Engineering": { "id": "ID32", "level": "A", "year": "2024", "source": "ICSE 2024", "authors": "Rudrajit Choudhuri, Dylan Liu, Igor Steinmacher, Marco Gerosa, Anita Sarma", "educationalObjectives": "The study's educational objective was to equip students with the ability to use APIs, develop skills for identifying and correcting code errors, improve code quality through the identification and correction of code smells, and master tools such as Git and GitHub. These objectives were defined to develop practical and contextualized competencies, especially in tasks requiring decision-making, critical analysis, and the application of development best practices. The article sought to teach and assess Software Engineering skills, such as API usage (interaction with the NOAA_SDK library), code debugging (correcting functions with incorrect logic, errors in API usage, and issues in web scraping with Selenium), code quality improvement (removal of code smells such as global variables, unused imports, dead code, and magic numbers), and version management with Git and GitHub.", "aiEmployment": "The study employed a mixed-methods analysis, combining quantitative and qualitative methods to evaluate the effectiveness and limitations of generative AI. The research utilized a cross-over experimental design, dividing the students into two groups: one that exclusively used ChatGPT (GPT-4) and another that used traditional resources without generative AI. The approach centered on task-based learning in Software Engineering, featuring three main challenges: (1) debugging and API usage (such as NOAA_SDK and Selenium), (2) code quality improvement, focusing on the removal of code smells, and (3) version management with Git and GitHub, including the creation of branches, commits, and pull requests. The tasks were developed in collaboration with the instructor, aligned with the course objectives, and adjusted to the level of the students, who were novices in SE. For the experimental group, ChatGPT provided contextualized support via natural language, assisting them in overcoming the challenges. Furthermore, the study assessed the tool's impacts on productivity, self-efficacy, future usage intention, and the perceived limitations of AI in the learning process.", "llm": "ChatGPT 4.0", "metrics": "Questionnaires, Accuracy of Generated Code", "metricsUsage": "An adapted questionnaire was used to assess the students' perception of their ability to perform the tasks. It was administered both before and after the tasks. Additionally, the students' satisfaction regarding the use of ChatGPT was evaluated.", "resources": "The materials used included ChatGPT (GPT-4) as the exclusive tool for the experimental group and traditional online resources, excluding generative AI, for the control group. The tasks were developed in collaboration with the instructor, aligned with the course objectives, addressing API usage, debugging, code quality, and version management.", "benefitsAndChallenges": "The perceived benefits of using ChatGPT were the possibility of natural language dialogue, contextualized help, and support with general information, such as Git commands. There was also a slight improvement in the removal of \"\"code smells.\"\" However, the challenges stood out, including increased frustration, higher cognitive load, and a perception of lower performance. There were no significant gains in overall productivity or self-efficacy, and students even experienced a drop in confidence regarding their comprehension of Python code when using ChatGPT.", "swebokAreas": "Software Construction, Software Quality", "swebokSubAreas": "Debugging, Code Smells, Software Construction Tools, Practical Considerations, Software Quality Assurance Process", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3597503.3639201", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Analyzing the Learning Effectiveness of Generative AI for Software Development for Undergraduates in Sri Lanka": { "id": "ID33", "level": "A", "year": "2024", "source": "International Research Conference on Smart Computing and Systems Engineering (SCSE)", "authors": "Pramodya Samarakoon, Shantha Jayalal, Dinesh Asanka, Nirasha Jayalath", "educationalObjectives": "The core motivation of the research was to investigate the effectiveness of Generative AI in enhancing students' coding proficiency. The study seeks to evaluate the impact of Generative AI on learning outcomes, student engagement, and the overall educational experience. The educational objectives of the study focus on improving the coding proficiency of university students, fostering active learning, the acquisition of practical skills (or competencies), and the application of knowledge in real-world contexts.", "aiEmployment": "The study adopted an instructional strategy based on coding problem-solving, augmented by the use of Generative AI. This approach was divided into three phases: a pre-assessment to measure students' initial proficiency without AI, an intermediate assessment where participants utilized Generative AI tools to solve progressive Object-Oriented Programming (OOP) problems, and a post-assessment to verify retention and understanding after the intervention. Additionally, the study employed scenario-based questions derived from 18 objective criteria and utilized Google Classroom as the platform for activity application and data collection. The study employed a quantitative approach to evaluate the effectiveness of Generative AI in enhancing coding proficiency, without the use of qualitative methods. The research was conducted with 57 undergraduate students and involved three assessment phases, all focused on Object-Oriented Programming (OOP). The assessments, delivered via Google Classroom, consisted of scenario-based questions analyzed against 18 objective code quality criteria, including readability, functionality, and documentation. A demographic questionnaire collected information about the participants to investigate the influence of variables such as age, gender, and preferred programming language. The data were analyzed using mean scores, which indicated a learning gain of (0.33), revealing progress in learning with the use of Generative AI.", "llm": " ChatGPT", "metrics": "Questionnaires, Accuracy of Generated Code, Pre-test, Mid-test, and Post-test Scores", "metricsUsage": "The study administered three assessments to measure coding proficiency: a pre-assessment (without AI), an intermediate assessment (with the use of Generative AI), and a post-assessment (without AI). The intermediate assessment specifically focused on the quality and originality of the solutions produced. The mean scores for the assessments were: 11.54 (pre), 14.49 (intermediate), and 13.66 (post), out of a maximum of 18 points. The code submitted by the participants was subjected to manual review (or manual grading). Finally, a questionnaire was used to collect data on participant demographics, such as gender, age, academic level (or year of study), and field of study.", "resources": "The study utilized Generative AI tools to support coding problem-solving in scenario-based Object-Oriented Programming (OOP) assessments. The activities were administered via Google Classroom, with participants having the flexibility to choose their programming language.", "benefitsAndChallenges": "The study identified several benefits of using Generative AI in software development education, such as improved coding proficiency, real-time assistance, learning personalization, support for students with low experience, and aid in problem-solving. However, several challenges were also highlighted, including copyright concerns, risks of academic dishonesty (or fraud), limitations in AI accuracy, difficulties with non-textual descriptions, and variations in learning gains.", "swebokAreas": "Software Construction, Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages, Practical Considerations", "doiOrLink": "https://ieeexplore.ieee.org/document/10550837?denied=", "interaction": "Free Prompts", "analysis": "Quantitative", "usedByStudents": "Yes" },
    "ChatGPT as a Software Development Bot: A Project-Based Study": { "id": "ID34", "level": "A", "year": "2024", "source": "ENASE 2024", "authors": " Muhammad Waseem, Teerath Das, Aakash Ahmad, Peng Liang, Mahdi Fahmideh, Tommi Mikkonen", "educationalObjectives": "The study aimed to evaluate the role of ChatGPT as a support tool throughout the various phases of the software development lifecycle, as performed by students. Furthermore, the paper addressed recurring challenges faced by students, such as difficulties in understanding software architecture, system integration, program design, tool usage, in addition to deficiencies in the deployment and software management stages. The paper has the following research questions: \"\"What are the impacts, advantages, and limitations of using ChatGPT as a development bot in each phase of the software lifecycle?\"\" \"\"How did the use of ChatGPT in projects influence students' learning curve and skill development?\"\" \"\"To what extent did the use of ChatGPT contribute to improving students' proficiency in software development concepts?\"\" \"\"What challenges did students face when utilizing ChatGPT as a development bot?\"\" The educational objectives in Software Engineering are to empower students with the knowledge, skills, and techniques for all phases of the software development lifecycle. This includes understanding architectural concepts, system integration, debugging, program design, error identification, and production of quality code.", "aiEmployment": "The seven undergraduate students were engaged in three publicly announced software projects over a three-month period. These projects were for real clients. ChatGPT (versions GPT-3.5 and GPT-4) was utilized to support the students across all phases of the software development lifecycle (SDLC). The projects included activities such as requirements gathering, CI/CD setup, development, testing, and deployment, in addition to collaboration with real clients. Learning occurred both through the use of ChatGPT and by overcoming the challenges associated with the tool. The methodology involved the use of real-world software projects with clients, public repositories for collaboration, CI/CD infrastructure, interaction with specialists, and ChatGPT as a support tool across all development phases.", "llm": "GPT-3.5 and GPT-4", "metrics": "Questionnaires, Likert Scale, Time Comparison, Accuracy of Generated Code, User Satisfaction", "metricsUsage": "Entry questionnaires (53 questions) and exit questionnaires (114 questions), both utilizing closed-ended questions on a 5-level Likert scale, were employed to collect data regarding the students' experience. The analysis focused on ChatGPT's effectiveness in reducing the time required for tasks such as requirements definition, as well as assessing the improvement in code quality, including error reduction and early defect detection. Student satisfaction regarding ChatGPT's contributions during the software development process was also investigated.", "resources": "Real-world software projects with clients, public repositories for collaboration, CI/CD infrastructure, interaction with specialists, and ChatGPT as a support tool across all development phases were utilized.", "benefitsAndChallenges": "The article evidenced that ChatGPT had a positive impact across all phases of software development, improving clarity, code quality, testing, and deployment, although it has limitations such as the risk of dependency, quality challenges, and ethical concerns. Students reported that using ChatGPT accelerated the learning curve, enhanced technical and problem-solving skills, and fostered innovative thinking. There was also a consensus regarding the enrichment of knowledge in software development. Despite the ease of use, the challenges faced were considered learning opportunities, including issues related to quality, integration, privacy, and the reliability of the generated code.", "swebokAreas": "Software Engineering Process", "swebokSubAreas": "Software Engineering Process Fundamentals, Life Cycles", "doiOrLink": "https://arxiv.org/pdf/2310.13648", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Examining the Utilization of Artificial Intelligence Tools by Students in Software Engineering Projects": { "id": "ID35", "level": "B", "year": "2024", "source": "(CSEDU 2024)", "authors": "Amir Dirin e Teemu Laine", "educationalObjectives": "The article aims to answer the following questions: \"\"How does the use of AI tools affect the functionalities implemented in software engineering students' projects?\"\" \"\"How does the use of AI tools affect the tasks completed per sprint in software engineering students' projects?\"\" \"\"How do software engineering students perceive the use of AI tools in academic projects?\"\" The article intends to evaluate the impacts of AI tools, specifically ChatGPT and GitHub Copilot, on the outcomes, student motivation, and perceived potential in software engineering student projects. They also sought to evaluate the quality of the resulting software, the number of implemented functionalities, and the impact of AI on the implementation of tasks and user stories within the Agile methodology.", "aiEmployment": "The study’s methodology was developed within the context of a software engineering project course, aimed at fourth-semester students who had already completed full-stack development courses. The course lasted eight weeks and was structured into four bi-weekly sprints, following the Agile Scrum approach. In this environment, students formed nine teams of four members, totaling 36 participants. These teams were organized into three groups, based on different levels of permission for the use of Artificial Intelligence (AI) tools: Group 1 (AITU - AI Tools Unlimited): Had total freedom to use ChatGPT and GitHub Copilot. Group 2 (PAIU - Prior Approval for AI Use): Could use AI tools subject to prior instructor approval. Group 3 (NAIA - No Access to AI): Had no access to any type of AI tool, developing their projects based solely on their own knowledge. During the course, the teams carried out typical software engineering project activities within the Scrum methodology, including the free selection of technologies, mandatory adoption of agile practices, use of Trello for task management, and rotation of the Scrum Master role. The study observes and analyzes how AI is applied by students in the learning and execution of traditional software engineering skills and content, such as project management, requirements definition (or requirements elicitation), implementation, and testing. The study reveals how AI impacts (both positively and negatively, such as concerning code quality) these areas.", "llm": "ChatGPT and GitHub Copilot", "metrics": "Questionnaires, Quality of the Resulting Software, and Implemented Features", "metricsUsage": "Questionnaires were utilized as part of the mixed-methods approach to address the research questions. These questionnaires were used to collect students' perceptions regarding the use of AI tools. The study also compared how the use of AI tools affected the number of functionalities implemented in the software projects.", "resources": "The study noted the use of Trello for project management and progress tracking. The AI tools themselves, ChatGPT and GitHub Copilot, were resources introduced into the process for two of the three groups.", "benefitsAndChallenges": "Students and researchers perceived that LLMs can boost productivity and creativity in Software Engineering tasks, effectively functioning as assistants. However, the use of these tools introduces challenges related to the initial learning curve (or initial learning time), a tendency to prioritize task quantity over quality, which resulted in a lower quality of the final software. This outcome highlights the need for greater emphasis on quality assurance when utilizing LLMs.", "swebokAreas": "Software Engineering Process", "swebokSubAreas": "Life Cycles, Software Process Assessment and Improvement", "doiOrLink": "https://www.scitepress.org/Papers/2024/127294/127294.pdf", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Toward an AI Knowledge Assistant for Context-Aware Learning Experiences in Software Capstone Project Development": { "id": "ID36", "level": "A", "year": "2024", "source": " Transactions on Learning Technologies (TLT)", "authors": "Andrés Neyem, Luis A. González, Marcelo Mendoza, Juan Pablo Sandoval Alcocer, Leonardo Centellas, and Carlos Paredes", "educationalObjectives": "The study analyzed the use of an AI Knowledge Assistant by students, comparing three query strategies: direct queries to GPT-3.5, queries enriched with lessons learned, and queries enriched with data from Stack Overflow. Students preferred direct queries or those enriched with course content, highlighting their effectiveness. This approach proved to be as useful as more complex methods, suggesting that Large Language Models (LLMs) could replace traditional lessons learned repositories.", "aiEmployment": "Artificial Intelligence was employed in the study through a Knowledge Assistant, an educational tool designed to offer context-aware learning experiences in software development courses. For general interaction with the assistant, students could formulate their own questions through a chat interface. Its primary role is described as an assistant, learning facilitator, and problem-solving support. The assistant functions as a real-time chatbot, offering personalized support to students based on multiple knowledge sources: course lessons learned, LLMs (GPT-4, GPT-3.5, LLaMa 2), and Stack Overflow. Recommendation strategies were used to compare responses with and without contextual enrichment. The quantitative evaluation included feedback rubrics, readability metrics, and textual similarity analyses. The qualitative assessment was based on open-ended student feedback. Participants interacted with the AI Knowledge Assistant integrated into their Kanban board, utilizing strategies with different LLMs and knowledge sources.", "llm": "The study integrated the GPT-4, GPT-3.5 Turbo, and LLaMa 2 models into the AI Knowledge Assistant.", "metrics": "Questionnaires, Error Rate, User Satisfaction.", "metricsUsage": "The evaluation was based on a user-centered framework for recommender systems. Students mentioned the need for improved error handling during API calls.", "resources": "The environment included documentation tools, client meetings, and evaluation rubrics.", "benefitsAndChallenges": "Highlights include an improved understanding of the recommendations, greater relevance, novelty, and serendipity of the responses, in addition to overall satisfaction with the use of the system. However, significant challenges were identified, such as slow response times, inaccuracies or a lack of clarity in some answers, the need for user interface and error handling improvements, as well as low textual quality in some models or when using information from Stack Overflow.", "swebokAreas": "Professional Practice", "swebokSubAreas": "Communication Skills", "doiOrLink": "https://ieeexplore.ieee.org/document/10518103?denied=", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Practical Application of AI and Large Language Models in Software Engineering Education": { "id": "ID37", "level": "B", "year": "2024", "source": "IJACSA", "authors": "Vasil Kozov, Galina Ivanova, Desislava Atanasova", "educationalObjectives": "The article addresses how to teach and apply AI in all phases of the software development lifecycle, developing practical skills, critical thinking, and the strategic use of modern tools, preparing students for the real-world challenges of the job market in the Industry 4.0 era. Students learn to use Large Language Models (LLMs) like ChatGPT to generate project ideas, refine functional requirements, and design databases and interfaces.", "aiEmployment": "In the Requirements Analysis, Artificial Intelligence, and Introduction to Programming courses, students learn to use AI to generate and refine ideas, create and populate databases, suggest interface designs, and automate tasks. Workshops featuring ChatGPT were conducted in three courses, and positive motivational effects were observed. Data collection methods included student surveys, interviews during project presentations, and comparative observations with previous cohorts.", "llm": "ChatGPT and Bard", "metrics": "Questionnaires, User Satisfaction", "metricsUsage": "Students were surveyed, and their feedback was analyzed. A positive impact was observed both during and after the workshops.", "resources": "Os recursos incluíram guias de prompt engineering, vídeos de backup, bibliotecas de programação e conjuntos de dados.", "benefitsAndChallenges": "The study highlights that LLMs motivate students and facilitate complex tasks, enhancing skills, especially for lower-performing students. However, they present shortcomings such as providing inaccurate responses, requiring prior knowledge, and being dependent on well-crafted prompts.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Data Structures and Algorithms,  Programming Fundamentals and Languages", "doiOrLink": "https://pdfs.semanticscholar.org/8525/101b70d5d5073364f3f4c7bd02329aad4c13.pdf", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "A Systematic Evaluation of Code-generating Chatbots for Use in Undergraduate Computer Science Education": { "id": "ID38", "level": "B", "year": "2024", "source": "Frontiers in Education Conference", "authors": "Adam Torek, Elijah Sorensen, Natalie Hahle, Casey Kennington", "educationalObjectives": "The article focuses on the assessment of code-generating chatbots for use in the context of Computer Science Education. The study suggests a pedagogical progression, stating that novice programmers should first master important programming concepts without the aid of code assistants to demonstrate their comprehension and to learn how to evaluate the assistants' output. Once intermediate skills, such as Object-Oriented Programming (OOP) and data structures are mastered, the introduction of coding assistants is appropriate to aid with specific tasks. Among the topics covered are: basic concepts, object-oriented programming, data structures, algorithm analysis, and specific coding problem-solving. AI was also utilized to support novice programmers in understanding Python language conventions. Research Questions (RQs) RQ1: What are the capabilities and limitations of code-based chatbots, and how do they affect student responses to questions and problems from authentic Computer Science assignments? RQ2: How do these capabilities and limitations impact human-chatbot conversations and the chatbots' capacity to answer questions? RQ3: Is it possible to integrate code-based chatbots in a way that assists both novice and experienced programmers in performing programming tasks more efficiently?", "aiEmployment": "The study was divided into two experiments. In Experiment 1, the capability of four open-source chatbots to solve authentic university course assignments was assessed through a simulated interaction between an experienced student and the chatbots, following a trial-and-error process. This simulation replicated how students might use chatbots to debug or resolve programming problems. In Experiment 2, novice and experienced programmers utilized the Llama chatbot, integrated into VSCode, as a coding assistant to solve problems in Python. It was observed that the AI was particularly useful for novices in understanding language conventions and implementing basic functions.", "llm": "CodeLlama, Phind-CodeLlama, OctoCoder and WizardCoder", "metrics": "Questionnaires, Code Accuracy, Error Rate, User Satisfaction", "metricsUsage": "Upon completion of the tasks, participants filled out questionnaires with questions regarding their experiences and the perceived difficulty of the tasks. Open-ended feedback and testimonials were also collected from participants, providing qualitative insights into their perceptions of and experiences with the AI tool. For tasks that included test cases, the percentage of tests that the generated code successfully passed was measured, indicating the solution's completeness with respect to the requirements.", "resources": "Authentic programming exercises from the Computer Science (CS) curriculum (Java and Python) were utilized, along with task descriptions, test cases, reference solutions, and a runtime analyzer. The VSCode environment was employed, with the Llama chatbot integrated for Experiment 2.", "benefitsAndChallenges": "Overall, while AI tools demonstrate significant potential to assist in programming, especially for novices on specific tasks, their limitations in accuracy, conversational behavior, and the potential for misuse pose significant challenges to their integration into the educational setting.", "swebokAreas": "Software Construction", "swebokSubAreas": "Practical Considerations, Software Construction Tools", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10893165&casa_token=hW_Z71RTB0EAAAAA:shXRW9bz85-BjBamVQdv88WJYhZisd5eRD3oSgD5ccf57el2xyk4_g-l8cBcRZg16p-Q4gYOoPU&tag=1", "interaction": "Fixed", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Integrating Conversational Large Language Models into Student Learning: A Case Study of ChatGPT in Software Engineering Education": { "id": "ID39", "level": "A", "year": "2023", "source": " Frontiers in Education Conference (FIE)", "authors": "Yi Liu", "educationalObjectives": "Students were assigned to a project in which they were required to use ChatGPT as a tool to assist in various stages of the software development process, including problem clarification, modeling assistance, system design feedback, and implementation support. They were encouraged to use ChatGPT 3.5 to enhance their understanding of the problem, refine their models, and receive assistance with debugging. The paper explores the use of ChatGPT as an educational support tool in a \"\"Formal Methods for Software Engineering\"\" course. The learning objectives include: (1) applying model-based formal methods, (2) modeling solutions with Finite State Machines (FSM), and (3) implementing models using concurrent programming in Java.", "aiEmployment": "ChatGPT was integrated as a support tool at various stages: problem clarification, modeling, system design, and implementation/debugging. Students were instructed not to request code directly and to apply critical thinking when evaluating the AI's responses. The assessment included the analysis of the students' modeling, implementation, and feedback, in addition to the logs of their interactions with ChatGPT. Generative AI was employed in the study as a tool to support and assist the students' learning process in a Software Engineering course. The prompts were primarily created by the students. Data was collected from three sources: student performance on the project, the logs of interactions with ChatGPT, and a questionnaire with 10 questions (7 Likert scale and 4 open-ended). The quantitative analysis involved evaluating student grades and aggregating the Likert scale responses. The qualitative analysis examined the textual feedback from the questionnaire and the conversation logs to identify patterns, limitations, and the effectiveness of using ChatGPT.", "llm": "ChatGPT 3.5", "metrics": "Questionnaires, Likert Scale, User Satisfaction", "metricsUsage": "A 10-item questionnaire was used, which was delivered along with the other project requirements. The questionnaire included 7 Likert-scale questions to quantify students' perceptions of the usefulness of and satisfaction with ChatGPT during different phases of the project, such as problem clarification, modeling assistance, system design feedback, and support.", "resources": "The primary materials used in the study included the project description, guidelines for the use of ChatGPT 3.5, the AI tool itself, languages such as FSP and Java, a questionnaire with open-ended and Likert-scale questions, and the logs of the students' conversations with ChatGPT.", "benefitsAndChallenges": "Among the benefits, support for problem clarification, design feedback, assistance with Java implementation and debugging, and a positive impact on learning were highlighted. The challenges, in turn, included limitations in modeling, a dependency on prompt quality, the need for refining questions, the risk of over-reliance and incorrect answers, as well as feedback that some students deemed basic or redundant.", "swebokAreas": "Models and Methods", "swebokSubAreas": "Analysis of Models, Software Engineering Methods", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10893046&casa_token=XtR-VXhF8oEAAAAA:lISA2zg8HCCk899xwR0A1QabLfK0_4w2TbBQg-FExPGTRFGfi7Kib6u3AW3KGvCW-h3jF2XKduM", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Incorporating AI in the Teaching of Requirements Tracing Within Software Engineering": { "id": "ID40", "level": "B", "year": "2024", "source": "Frontiers in Education Conference (FIE)", "authors": "Juan Ortiz Coude, William C. Daniel A. Machado, Omar Ochoa", "educationalObjectives": "The primary motivation of the study was to address the challenge of adequately teaching requirements traceability in a traditional classroom environment. The study sought to incorporate the use of AI (Large Language Models - LLMs) into the teaching of requirements traceability. The paper aims to investigate whether LLMs can be used as a tool to teach requirements traceability to students and track their progress. The study proposes integrating the use of LLMs into requirements engineering education to bridge the gap between what is taught in the classroom and what is used in the industry. The paper seeks to teach and assist with the skill of Requirements Traceability, including the process of tracing requirements back to their originating artifact and handling the traceability of modified requirements.", "aiEmployment": "A division of groups was established to allow for a performance comparison between the LLMs and the students. The first group consisted of 20 master's students in Software Engineering, who performed the requirements traceability manually. They analyzed a client interview transcript, a requirements specification document, and visual prototypes to create a traditional traceability matrix. The second and third groups consisted of the GPT-3.5 and GPT-4 versions, respectively. Both were provided with the same artifacts used by the students. To ensure a fair evaluation, the models were tested with multiple prompts, adjusting the instructions to optimize their performance on the traceability task. The prompts were fixed and iterated upon by the researchers throughout the experiment to improve performance. In the experiment, the AI acted as an executor of the traceability task. Based on the results, the paper suggests its potential role as a tool for testing the completeness of the traceability process and as a self-assessment tool for students.", "llm": " GPT-3.5 and GPT-4", "metrics": "Comparison of Traced Requirements", "metricsUsage": "Metrics (counts of traced requirements) were used to compare the performance of the LLMs (GPT-3.5 and GPT-4) with the performance of the master's student group on the traceability task. The quantitative results were used to validate the capability of LLMs in assisting with or performing the traceability and to assess the performance difference between the GPT versions and in comparison to human performance.", "resources": "Transcript of an interview between clients and the engineering team. Requirements Specification Document (SRS) containing 888 elicited requirements. Visual prototypes used to validate requirements with clients.", "benefitsAndChallenges": "LLMs demonstrated benefits in teaching requirements traceability, acting as support tools to test the completeness of students' work and to assist in their self-assessment. They also traced some requirements that the students did not identify. Furthermore, they indicate a potential to reduce the gap between education and industry practices, especially with GPT-4's performance compared to GPT-3.5, owing to its better contextual understanding and larger input capacity. However, they still exhibit limitations, such as inferior performance to students in tracing modified requirements, difficulty in interpreting images, and a dependency on prompt formulation. Therefore, they do not replace human requirements engineers.", "swebokAreas": "Software Requirements", "swebokSubAreas": "Practical Considerations, Requirements Specification, Requirements Validation", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10892858&casa_token=BB-02Lml2CIAAAAA:cxieEYV0I8SH3__goM_94FtfLyMEJ7IshPxApr6tlTpa7VgcWFxM1ntsOcsvhFHov3cPp209ORU", "interaction": "Fixed Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Use of Generative Artificial Intelligence in the Education of Software Verification and Validation": { "id": "ID41", "level": "A", "year": "2024", "source": "Frontiers in Education Conference (FIE)", "authors": "Ayca Tuzmen, afiliada a Ira A. Fulton Schools of Engineering, Arizona State University, Tempe, Arizona", "educationalObjectives": "O artigo relata que alunos de pós-graduação usaram diretamente LLMs, como ChatGPT 3.5 e Bard, em um curso de Verificação e Validação de Software. Eles aplicaram essas ferramentas para gerar casos de teste de unidade, explorando suas capacidades e limitações. O artigo busca ensinar conteúdos e habilidades em Engenharia de Software com foco em Verificação e Validação e no uso de IA Generativa. Entre os principais objetivos estão, aplicar testes de unidade com frameworks adequados, desenvolver senso crítico para avaliar e complementar os testes gerados pela IA, entender os princípios de garantia de qualidade de software e explorar as limitações e potencialidades da GenAI.", "aiEmployment": "A IA generativa foi integrada ao currículo por meio de um exercício prático redesenhado, no qual os alunos implementaram um algoritmo, escolheram ferramentas e usaram a GenAI para gerar e avaliar casos de teste. O estudo utilizou uma análise descritiva com abordagem mista, baseada em 290 relatórios de 180 alunos de pós-graduação. A parte quantitativa incluiu dados como frequências de linguagens e frameworks utilizados e a ausência de correlações significativas entre variáveis técnicas. A parte qualitativa envolveu a avaliação dos testes gerados pela GenAI, análise de lacunas e feedback dos estudantes sobre eficácia e limitações da IA.", "llm": "ChatGPT 3.5, with some students also using Bard-AI", "metrics": "Analise dos relatorios ", "metricsUsage": "A análise dos resultados foi realizada com base em quatro aspectos principais: o tipo de framework de unidade utilizado, a cobertura dos testes de unidade, a eficácia dos casos de teste e as avaliações dos alunos sobre a GenAI na criação de testes de nível de unidade.", "resources": "Os alunos usaram ferramentas como ChatGPT 3.5 e Bard-AI para criar e avaliar casos de teste com frameworks como JUnit e PyTest. Eles tinham liberdade para escolher linguagem, IDE e criar seus próprios prompts, com suporte disponível em horários de atendimento.", "benefitsAndChallenges": "O estudo identificou benefícios como a geração rápida de testes de alto nível, apoio na resolução criativa de problemas e co-criação de soluções válidas com a GenAI, considerada útil e eficaz pelos alunos. No entanto, também foram observadas limitações, como a cobertura insuficiente de casos de canto, falta de criatividade e expertise de domínio da GenAI, variação nas respostas e risco de alucinações. ", "swebokAreas": "Software Testing, Software Quality", "swebokSubAreas": "Test Levels, Software Quality Assurance Process", "doiOrLink": "https://ieeexplore.ieee.org/document/10893333", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "AI2SQL.io: Empowering SQL Learning and SocialChange Through IT-Enabled Smart Tutoring in Computer Science and Engineering": { "id": "ID42", "level": "A", "year": "2024", "source": "2024 International Conference on Artificial Intelligence and Quantum Computation-Based Sensor Application (ICAIQSA)", "authors": "Dr. Rashmi Dixit e Nikhil Gajjam", "educationalObjectives": "The educational objectives in Software Engineering addressed by the article focus on enhancing the teaching and learning of SQL, an essential skill within the discipline. The study aims to develop students' fundamental competencies in the language, improve their theoretical understanding and practical application, and facilitate the transition from foundational knowledge to advanced use in real-world scenarios. It also supports the achievement of curriculum objectives related to SQL proficiency. Furthermore, this approach promotes learning with real-time feedback, adapts to varying skill levels, and seeks to increase student engagement through more dynamic and interactive methods. The article aims to teach and improve both practical and theoretical proficiency in SQL. By utilizing the AI tool AI2SQL.io, the study centers on developing database skills, specifically in the formulation, comprehension, and optimization of SQL queries. The tool also assists in translating natural language into SQL, allowing for daily practice and the application of theoretical concepts in practical settings, such as professional environments.", "aiEmployment": "The article compares two SQL teaching strategies: a traditional one and an innovative approach using the AI tool AI2SQL.io. The traditional approach involved lectures, textbook exercises, and manual feedback. In contrast, the AI-driven approach implemented an Intelligent Tutoring System that offered personalized learning, daily query-based practice, instant feedback, and natural language to SQL translation. The tool also encouraged collaborative learning and created a safe environment for experimentation. This strategy supplemented, rather than replaced, traditional instruction, promoting a more dynamic learning experience adapted to individual student needs. The analysis conducted in the study was of a mixed-methods nature, combining quantitative and qualitative approaches. The methodology involved pre-tests and post-tests with randomized groups, comprising a total of 60 students divided equally into a control group (traditional teaching) and a treatment group (using the AI2SQL.io tool). Quantitative data were collected through exams, engagement surveys, and tool usage metrics, while qualitative data were gathered from interviews with students and instructors.", "llm": "AI2SQL.io Although AI2SQL.io has the capability to convert natural language input into SQL queries and generate context-specific queries, the study presents it as a specialized AI tutor for teaching SQL, rather than as a general-purpose generative AI tool.", "metrics": "Questionnaires, Time Comparison, Code Accuracy, User Satisfaction", "metricsUsage": "Questionnaires were administered to measure student engagement levels. The treatment group, which benefited from AI2SQL, showed a significant decrease in task completion time compared to the control group. Furthermore, the treatment group demonstrated a substantial increase in the accuracy of their queries following the intervention with AI2SQL", "resources": "The traditional teaching method utilized textbooks, lectures, homework assignments, and instructor feedback. In contrast, the AI-assisted group used the AI2SQL.io tool, which provided personalized SQL queries, instant feedback, natural language to SQL translation, step-by-step visualizations, and customized exercises", "benefitsAndChallenges": "The study highlights that the use of AI2SQL.io yielded several benefits, such as simplifying the SQL learning process, enhancing in-depth comprehension, and accelerating the learning curve. It also provided accessibility for students at different skill levels and offered a safe environment for experimentation. Among the challenges, the study noted the AI's difficulty in understanding context and nuances, its dependence on the quality of the training data, and the fact that it cannot completely replace the role of a human instructor.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Database Management, Artificial Intelligence and Machine Learning", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10882332&casa_token=bfjwWiQuTNkAAAAA:YqwplATvMnKgXu3A7-zcvrwMQdrZfozuLOdrm1iAgFFmsuIn2DxW3r9ZZYt5KSH9KrGkA7XAT9c", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Roadmap for Software Engineering Education using ChatGPT": { "id": "ID43", "level": "B", "year": "2023", "source": "International Conference on Artificial Intelligence Science and Applications in Industry and Society (CAISAIS)", "authors": "Aly Maher Abdelfattah, Hany H Ammar, Nabila Ahmed Ali, e Mohamed Abd Elaziz", "educationalObjectives": "The proposal highlights the active interaction of students with AI for gathering user stories, creating diagrams (use case, class, and sequence), and refining the results. The proposal focuses on requirements modeling, guiding students in defining and extracting user stories, and in generating use case, class, and sequence diagrams. The study also promotes the practical application of knowledge in real-world scenarios, encouraging critical thinking, problem-solving, and communication skills.", "aiEmployment": "The approach adopts an agile methodology, promoting an immersive environment where students interact directly with the AI to create and refine artifacts such as user stories, use case, class, and sequence diagrams. The process is collaborative, featuring feedback loops between the student and ChatGPT, allowing for the enhancement of the generated artifacts. In the study, Artificial Intelligence was employed as a virtual assistant to support students in the Requirements Engineering process. The analysis conducted in the study was qualitative in nature, based on collecting student feedback to gain insights into the effectiveness of the proposed methodology. Although it does not use formal qualitative analysis methods, such as thematic analysis, the assessment was descriptive and observational, highlighting perceived experiences and benefits.", "llm": "ChatGPT-3 and ChatGPT-4 ", "metrics": "User Satisfaction", "metricsUsage": "The effectiveness of the interactive learning experience was evaluated by collecting feedback from the students. The data gathered from this feedback provided insights into the utility of ChatGPT as a learning tool and its impact on the students' understanding of requirements engineering.", "resources": "The primary materials used in the study included the project description, guidelines for using ChatGPT 3.5, the AI tool itself, languages such as FSP and Java, a questionnaire with open-ended and Likert-scale questions, and the logs of the students' conversations with ChatGPT.", "benefitsAndChallenges": "Among the benefits, the study highlighted support in clarifying problems, feedback on design, assistance with Java implementation and debugging, and a positive impact on learning. The challenges included limitations in modeling, dependency on prompt quality, the need for refining questions, the risk of over-reliance, and incorrect answers, in addition to feedback that was considered basic or redundant by some students.", "swebokAreas": "Software Requirements", "swebokSubAreas": "User Stories, Requirements Elicitation, Requirements Analysis, Requirements Specification", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10270477&casa_token=5R49R6e2t2oAAAAA:zlznaKYR2yMZpO9dYpB3xGZWHuoN_zgfzn3YtQL3i3huvSLCePV8qnAqt0a_sstWHq8KpaSoWo8", "interaction": "Hybrid", "analysis": "Qualitative", "usedByStudents": "Yes" },
    "A Data Science Course Utilizing GenAI": { "id": "ID44", "level": "A", "year": "2024", "source": "Frontiers in Education Conference (FIE)", "authors": "Jonathan W. Browning, John Bustard, Neil Anderson, e Leo Galway", "educationalObjectives": "The article describes the application of ChatGPT in a Data Science course for master's students in software development. Students investigated an industrial sector, collected and analyzed a relevant dataset, and ultimately produced two detailed reports. The use of ChatGPT was mandatory and integrated into all phases of this project. The study aims to ensure that students achieve a solid understanding of essential disciplines, such as requirements engineering, design, and testing, which constitute the foundation for developing high-quality systems. Furthermore, emphasis is placed on developing higher-order skills, which include critical analysis, the evaluation of solutions, and a comprehensive understanding of the project in its entirety. The article seeks to teach a set of skills that combine the fundamentals of data science and software engineering with the critical use of generative AI. Among the course content, practical data analysis, project planning, and data-driven reasoning are highlighted. Additionally, the course promotes the critical assessment of AI-generated responses and their synthesis with human knowledge.", "aiEmployment": "The central strategy was to maintain the project-based learning structure while deeply integrating the mandatory and assessed use of Generative Artificial Intelligence. This integration was guided by two objectives: to facilitate data analysis (especially for students with limited Python experience) and to ensure that students utilized GenAI to assist in their projects. The study adopts a qualitative methodology. The analysis was based on three main fronts: (1) student feedback collected in online sessions and the virtual learning environment, reporting experiences, uses of ChatGPT, and difficulties in planning analyses; (2) instructor observations, including insights into student limitations, such as accepting generic AI responses, difficulty in decomposing tasks, and an over-reliance on examples; and (3) analysis of student projects, based on the final reports and the prompt engineering report, which allowed for the assessment of both the quality of the data analysis and the proficiency in critical interaction with the AI. Students used ChatGPT to gain initial insights into an industry sector before interviewing a human expert and to create data analysis plans. The main and assessed task required students to create, test, and refine their own prompts to complete the project. The AI acted as a productivity-enhancing tool, for instance, by finding datasets in minutes.", "llm": "ChatGPT", "metrics": "User Satisfaction, Instructor Observation Analysis", "metricsUsage": "The researchers collected and analyzed feedback that students provided continuously throughout the course. This information was gathered during the weekly online sessions designed for Q&A. The assessment included an analysis of the reflections from the instructor who led the course. This encompassed observations on how students interacted with the AI and the difficulties they faced.", "resources": "The main component was a Practical Example, featuring model reports, sample prompts for ChatGPT, and demonstrations of structured outputs. This was created to guide the students but ultimately led to over-reliance. A guide was also developed, detailing criteria and providing structured feedback. Additionally, the course included weekly two-hour online classes, a virtual learning environment as the central platform, and weekly online Q&A sessions, which served both as direct support and as a means of collecting student feedback.", "benefitsAndChallenges": "Among the benefits were improved analytical and decision-making capabilities, the facilitation of technical analysis even for Python beginners, increased productivity and efficiency, an elevation in the quality of the work, a pedagogical shift toward focusing on the “why” of the analysis, and a reduced need for technical support. The challenges, on the other hand, included difficulties with prompt engineering (generic responses, lack of refinement, and poor task decomposition), a deficiency in critical thinking and initiative, problems in synthesizing human and AI-generated content, and an over-reliance on provided examples.", "swebokAreas": "Professional Practice", "swebokSubAreas": "Professionalism, Communication Skills", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10893452&casa_token=18GYYKemxaEAAAAA:9SzorM71cDb2ScpfzFcRFNEuqGvVYaS9S9skDuF3aRN4fQlMxjeThgPTWt4XDm53cDUANDTtbHg", "interaction": "Free Prompts", "analysis": "Qualitative", "usedByStudents": "Yes" },
    "Analysis of Student-LLM Interaction in a Software Engineering Project": { "id": "ID45", "level": "A", "year": "2024", "source": "International Workshop on Large Language Models for Code (LLM4Code)", "authors": "Agrawal Naman, Ridwan Shariffdeen, Guanlin Wang, Sanka Rasnayaka, Ganesh Neelakanta Iyer", "educationalObjectives": "The primary application was in the generation of code for the project's functionalities, such as the Source Parser, the Program Knowledge Base (PKB), and the Query Processing Subsystem (QPS). The study proposes that the use of AI assistants should evolve beyond being merely a tool for code generation. Students should be encouraged to use AI more strategically throughout the entire software development lifecycle. Students not only used the generated code but frequently modified, refactored, or even removed it. The main motivation of the study was to understand how software engineering students interact with and utilize Large Language Models (LLMs) during the development of a complex, long-term project. Education in this area should extend beyond using AI as a mere code generation tool. The objective is for students to learn how to use AI assistants more broadly and strategically across the entire software development lifecycle. The primary objective was to analyze how software engineering students naturally used AI tools (ChatGPT and CoPilot) in a complex project to, from these observations, extract insights and recommendations for educators.", "aiEmployment": "The course's primary strategy was Project-Based Learning, in which students, organized into teams, developed a Static Program Analyzer over 13 weeks, divided into three delivery milestones. Software Engineering content was taught in a practical manner, requiring the construction of complex components. The main applications of AI included code generation, the creation of test cases, and iterative refinement through dialogue with the tool. Furthermore, students were required to evaluate and label the generated code, indicating the necessary level of human intervention, which promoted critical analysis rather than passive acceptance of the AI's outputs. The study adopted a mixed-methods analysis (quantitative and qualitative) to investigate students' interactions with LLMs. For the quantitative analysis, software metrics were applied to 730 code snippets, showing that CoPilot produced longer and more complex code, while ChatGPT required fewer modifications. The analysis also covered tool usage per task, the levels of human intervention, and a sentiment analysis of the prompts, revealing a pattern of initial optimism, intermediate frustration, and final resolution. For the qualitative analysis, 62 conversations with ChatGPT (318 messages) were examined, highlighting the refinement process, the evolution of prompts from simple to strategic throughout the semester, and the analysis of the final code in the repositories. AI was employed as a software development assistance tool. It played multiple roles, but its primary function can be defined as that of a code co-author and a refinement tool. The prompts were created entirely by the students.", "llm": "ChatGPT and CoPilot", "metrics": "Human Intervention, Code Complexity", "metricsUsage": "The study evaluated student interaction with ChatGPT and CoPilot using metrics for code complexity, human intervention, sentiment in prompts, tool usage, final code similarity, and conversation dynamics, which allowed for the analysis of the quality, engagement, and iterative refinement of the AI-generated code.", "resources": "The environment included code repositories and a labeling system, which enabled the recording of the tool used, the level of human intervention, and conversation history, serving for both self-assessment and data collection. No traditional materials, such as slides or videos, were used.", "benefitsAndChallenges": "The use of ChatGPT resulted in more concise, simple, and easy-to-understand code, with lower complexity and cognitive effort, allowing for iterative refinement through its conversational interface and alignment with student preferences. The LLMs increased productivity, particularly in the initial phases, and promoted active learning and the development of prompt engineering skills, in addition to generating modular and reusable code. Among the challenges were the unnecessary complexity of some solutions, the need for human intervention, the risk of over-reliance, and temporary frustration during interaction. The initial AI-generated code was not always definitive and was frequently refactored or removed in the final project.", "swebokAreas": "Software Construction, Computing Foundations", "swebokSubAreas": "Practical Considerations, User and Developer Human Factors, Programming Fundamentals and Languages", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=11028221&casa_token=no213ApmlwwAAAAA:1Jxt0oGE_O99EKKc-370fRJsjaa5UQgLXJzs7bu9-utlh7OEFJyBeRK9Fk3R2i_giFJoKV-h0es", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Concepts for Teaching Software Development in the Age of AI-Tools": { "id": "ID46", "level": "A", "year": "2024", "source": "Global Engineering Education Conference (EDUCON)", "authors": "Axel Böttcher, Veronika Thurner, e Benedikt Zönnchen", "educationalObjectives": "The most direct purpose was the students' attempt to use ChatGPT and GitHub Copilot to solve programming exercises, especially when they encountered difficulties. Teaching programming promotes valuable skills such as computational thinking, problem-solving, and logic, which are crucial for any field. Furthermore, students first need to develop a solid foundation in programming to be able to critically integrate and evaluate the code suggestions generated by AI. The study focuses on three main areas of development for Software Engineering students. The first involves the fundamentals of programming, reinforcing essential concepts, computational thinking, and logic skills, ensuring that students have a solid foundation to work with code. The second area focuses on specific skills related to generative AI, including prompt engineering, understanding the workflow with AI assistants, and the practical application of AI in programming tasks. Finally, the third area covers cognitive skills, such as critical analysis and evaluation of AI-generated code, integration and validation of solutions, and the responsible use of these tools, preparing students to interact strategically and ethically with intelligent systems.", "aiEmployment": "First, the methodology is cyclical and iterative, involving the design of interventions, in-class application, qualitative evaluation, and continuous refinement. Second, three strategies for GenAI integration are discussed: banning AI, using it from the beginning, or combining conventional teaching with subsequent AI interventions, with the latter considered the most effective for building a solid foundation prior to AI interaction. Finally, the study details specific teaching activities, including the observation of spontaneous AI use and prompted usage with feedback. AI was employed in multiple ways in the educational environment, both through student initiative and by instructor direction. The prompts were created by the students themselves. The study utilized a qualitative analysis based on direct classroom observations and experiences, without quantitative data. The execution followed a cyclical and iterative process, beginning with initial observations of students using ChatGPT independently, followed by the design of interventions, in-class application, and qualitative evaluation. Data collection involved student reports, GitHub Copilot demonstrations with plenary and small-group discussions, and the analysis of anecdotal evidence. Finally, the results of each cycle were used to refine teaching practices and formulate recommendations for integrating GenAI into programming education.", "llm": "ChatGPT and GitHub Copilot", "metrics": "Classroom Observations", "metricsUsage": "The basis for the analysis was the \"\"first observations on the use of GenAI tools in the classroom.\"\" The instructors observed how students, especially those with difficulties, interacted with the tools. During classes, the instructors used Copilot to solve problems, which led to a mix of plenary debates and small-group discussions to raise student awareness about quality issues in the generated code.", "resources": "The main tools used were ChatGPT, initially used spontaneously by students and later in a guided manner, and GitHub Copilot, which was employed both in live demonstrations by instructors and by the students themselves. The activities included standard programming exercises, complex integration tasks, code debugging, and Parsons Problems, all of which were conducted within IDEs and controlled assessment environments.", "benefitsAndChallenges": "The study identified that generative AI tools offer benefits such as increased productivity, serving as a personal tutor, and reducing students' inhibition to ask questions. However, they also present challenges, especially for beginners or struggling students, including shallow learning and confusion.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "User and Developer  Human Factors, Artificial Intelligence  and Machine  Learning", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=11016505&casa_token=f3tR3Ua3qfMAAAAA:9wnnCAtAkEluSuy7srvurav1fyCR3yy30Zt62Upmj_APPo3hwnHVXFSVf7HBcH6YqGoccpElmXE", "interaction": "Free Prompts", "analysis": "Qualitative", "usedByStudents": "Yes" },
    "Enhancing Student Learning in Scrum Projects with Generative AI Assistance": { "id": "ID47", "level": "B", "year": "2023", "source": "21st International Conference on Information Technology Based Higher Education and Training (ITHET)", "authors": "Meryem Boubakri e Khalid Nafil", "educationalObjectives": "The primary motivation of the study was to integrate and evaluate the use of Generative AI tools, specifically ChatGPT and Bard, in teaching the Scrum framework to enhance student learning and collaboration. The study sought to better understand the potential of AI-assisted teaching in project management education. The pedagogical scenario aimed to deepen students' practical understanding of Scrum through simulated activities, including creating a product vision, identifying and prioritizing epics, decomposing them into user stories, and developing agile artifacts (product backlog and sprint backlog). The results showed high effectiveness: 97% of students reported that AI contributed significantly to their understanding of the method. The main objective was to provide students with a practical and in-depth experience in applying the Scrum methodology. Using AI as an assistant, students were taught to create and manage the main Scrum artifacts and concepts in a scenario that simulated the real world.", "aiEmployment": "The teaching strategy was a practical and collaborative workshop in which fourth-year Software Engineering students, divided into groups, used either ChatGPT or Bard to support their learning of Scrum. The process involved an introduction to the tools, execution of tasks guided by prompts (such as creating a product vision, epics, user stories, a product backlog, and a sprint backlog), and validation of the outputs by the instructor. Afterward, students discussed the results within their groups and in a plenary session. The key pedagogical elements were active and hands-on learning, the acceleration of learning through AI, the simulation of real-world scenarios, and the encouragement of collaboration. AI was employed as an assistive tool within a structured pedagogical scenario, specifically a hands-on workshop for fourth-year Software Engineering students. The study clarifies that the students did not create their own prompts. The study utilized a mixed-methods analysis, combining qualitative and quantitative approaches to evaluate the integration of generative AI in Scrum education. The qualitative analysis consisted of comparing the responses from ChatGPT and Bard to the same prompts, assessing criteria such as detail, structure, and accuracy. It was found that ChatGPT produced more comprehensive answers, while Bard was more concise, with no instances of errors or \"\"hallucinations.\"\" The quantitative analysis was based on a questionnaire administered to 32 students, revealing that 97% considered AI effective for understanding Scrum, 94% rated the responses as useful and accurate, and 81% deemed the instructor's presence indispensable.", "llm": "ChatGPT and Bard", "metrics": "Questionnaires, User Satisfaction", "metricsUsage": "A survey was administered to the 32 participating students at the end of the workshop to evaluate the experience, the effectiveness of the AI, the role of the instructor, and to gather recommendations. Student satisfaction with the workshop's approach was explicitly measured, with 72% reporting they were 'Satisfied' and 25% 'Very Satisfied'. The overall experience was also rated positively by the vast majority of participants.", "resources": "The key resources were the generative AI tools (ChatGPT and Bard), which were used directly by students in groups to perform workshop tasks; the structured, hands-on workshop itself, which focused on collaboration; and a series of prompts developed by the instructor, which served as exercises guiding the practical application of Scrum.", "benefitsAndChallenges": "Benefits: AI accelerated the creation of agile artifacts, optimizing classroom time and allowing focus on analysis and discussion, which significantly improved student understanding (97% reported a positive impact). ChatGPT stood out for providing detailed, structured, and clear responses; the content was considered accurate and useful (94% of students agreed), validated without errors by the instructor, and the hands-on experience was seen as positive, engaging, and effective, with unanimous interest in future AI use. Challenges: The irreplaceable role of the instructor was highlighted (half of the students considered it the most valuable aspect, and 81% deemed their presence indispensable). Technical and capability limitations were reported (38% indicated the AI needed better contextual understanding and adaptability). Bard performed worse than ChatGPT, giving concise and less structured responses. Students suggested clearer prompts and more training to optimize tool usage.", "swebokAreas": "Models and Methods", "swebokSubAreas": "Scrum, Software Engineering Methods", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10837605&casa_token=-GOfjj4NHmIAAAAA:qqWdSQFc3RzU6_lQYmsgnBe9kq4OPlBX_JuKAwGszgoC8TxEthQyAgL-ip-M1qtYec8L78EkAfg", "interaction": "Fixed", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Enhancing User Story Generation in Agile Software Development Through Open AI and Prompt Engineering": { "id": "ID48", "level": "A", "year": "2024", "source": " Frontiers in Education Conference (FIE)", "authors": "Vijayalakshmi Ramasamy, Suganya Ramamoorthy, Gursimran Singh Walia, Eli Kulpinski e Aaron Antreassian", "educationalObjectives": "The primary motivation of the study was to investigate how AI technologies, specifically Large Language Models (LLMs) like ChatGPT, could be used to improve the process of generating user stories in Software Engineering educational settings. The objectives include: teaching requirements elicitation and documentation, particularly in the form of user stories; developing practical skills through team-based projects, such as capstone projects; enhancing problem-solving abilities; and aligning the academic curriculum with the actual demands of the job market. The main content addressed by the study is the generation and refinement of user stories. By using generative AI (ChatGPT), the study aims to teach students how to overcome the limitations of traditional brainstorming methods and create more complete, innovative, and effective user stories.", "aiEmployment": "First, students created user stories using conventional methods (as a baseline). Next, they refined these stories with the assistance of ChatGPT, exploring new requirements and functionalities. Afterward, they answered a survey to reflect on the experience and the impact of AI on their skills. Finally, industry experts evaluated the generated user stories to validate their quality. The AI, specifically OpenAI's ChatGPT utilizing models such as GPT-4 Turbo and GPT-3.5 Turbo, was employed as a tool to enhance and expand the generation of user stories in a software engineering educational environment. The study adopted a mixed-methods approach, combining quantitative and qualitative analyses to assess the impact of using ChatGPT on the generation of user stories. In the quantitative analysis, a post-test survey with a Likert scale was administered to 18 student teams. The results indicated perceived improvements in problem-solving, preparation for real-world development environments, quality of ChatGPT's responses, team collaboration, confidence in prompt creation, and the overall effectiveness of the strategies employed. The qualitative analysis was conducted by industry experts, who evaluated the user stories generated by students with and without AI support. They identified that ChatGPT expanded upon initial ideas, suggested additional functionalities, and introduced new requirements and stakeholders, thereby contributing to higher quality and innovation in the work.", "llm": "ChatGPT-4, gpt-3.5 and Whispe", "metrics": "Questionnaires, Industry Expert Evaluation", "metricsUsage": "The study utilized a post-test survey with students to collect feedback following the user story generation activity with AI. In parallel, software industry experts analyzed and compared the user stories generated by the traditional method with those enhanced by AI.", "resources": "The study did not make use of traditional teaching materials, such as slides, videos, or pre-defined handouts", "benefitsAndChallenges": "The study showed that the use of LLMs, such as ChatGPT, brought clear benefits but also relevant challenges. Among the positive aspects, highlights include improved problem-solving, the generation of more complete and innovative user stories, strengthened team collaboration, better preparation for the real-world work environment, and increased confidence in prompt creation. On the other hand, challenges emerged such as dependence on prompt quality, usability difficulties for some students, uncertainty about the effectiveness of the strategies, and the inherent risks of LLMs, including biases, inaccuracies, and privacy concerns.", "swebokAreas": "Software Requirements", "swebokSubAreas": "User Stories, Requirement Elicitation, Requirements Specification", "doiOrLink": "https://ieeexplore.ieee.org/document/10893343", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Exploration of Course Practice on the Integration of AI Language Model and Ideological and Political Education : The Course of \"Software Testing\" as an Example": { "id": "ID49", "level": "B", "year": "2024", "source": "International Conference on Information Science and Education (ICISE-IE)", "authors": "Chang Liu, Dongxia Zheng, Yan Jiang", "educationalObjectives": "The course addresses diverse areas and specific skills within the discipline of Software Testing, utilizing AI as a tool to modernize the learning process. The fundamental objective is to equip students with the practical skills necessary to work in the software testing field, aligning the curriculum with the current demands of the AI and big data industries. This article focuses on teaching Software Testing with the support of generative AI, highlighting five key fronts: Test Case Design: Students use AI to structure testing scenarios. Automated Script Generation: Aligned with industry demands for automation. Critical Thinking Development: Students analyze and validate AI-generated responses. Optimization and Refinement: Adapting artifacts to meet specific project needs. Quality Assessment of AI Outputs: Encouraging innovation in the use of the technology.", "aiEmployment": "The study adopted an integrated approach to teaching Software Testing, combining traditional methods with AI-driven practices under the concept of \"\"AI-Enhanced Enablement.\"\" The core strategy merged theory and practice through progressive projects, real-world industry cases, and the involvement of instructors from the sector. Generative AI was actively used, allowing students to ask questions, critically analyze the responses, and optimize test cases in interactive projects. Real-world scenario simulations and defect repair reinforced applied practice, complemented by a mix of methods and lectures, self-directed learning, discussions, reports, tutorials, and labs. Generative AI was integrated into the Software Testing teaching process, functioning as a tool for both learning and knowledge application. In the study, two types of prompts were used: open-ended prompts, created by the students themselves in an Intelligent Q&A System, and fixed prompts, generated by the AI in an Interactive Case Study, where students answered questions previously structured by the tool. The study's analysis was predominantly qualitative, focusing on the observation and assessment of student performance throughout the reformed course. The evaluation considered innovation reports, final presentations and defenses, observation of practical skills and competencies, as well as instructor reflection and feedback. No numerical data or statistical metrics were presented; the assessment was based on the qualitative interpretation of the students' progress, creativity, and application of AI.", "llm": "Not mentioned", "metrics": "Innovation Report Analysis", "metricsUsage": "The primary metric was the analysis of the students' \"\"innovation reports.\"\" In these documents, they described in detail how they applied AI technology, which demonstrated their \"\"deep understanding and innovative thinking\"\" in the field.", "resources": "The teaching process focused on interactive and practical materials rather than traditional resources like slides or videos. Generative AI models were utilized, including a Question and Answering (Q&A) system with open-ended prompts and an Interactive Case Study with structured prompts. The curriculum also explored real-world case studies and industry projects, online tutorials, and laboratory environments for applied practice. Learning was reinforced through structured exercises and reports, enabling students to apply AI, document their solutions, and develop both practical and analytical skills.", "benefitsAndChallenges": "The study indicates that using LLMs in Software Testing education yielded significant benefits, including the enhancement of technical skills, increased test efficiency and coverage, mastery of practical skills, and the development of critical thinking and innovation capabilities. Furthermore, it fostered student engagement and professional competencies such as teamwork and self-learning. The main challenge identified was pedagogical: teaching students how to interact critically with the AI by evaluating the rationality and completeness of its responses, and developing the ability to create effective prompts. Thus, the focus is not on the tool's limitations but on the need to cultivate reflective users who can leverage the technology consciously and effectively.", "swebokAreas": "Software Testing", "swebokSubAreas": "Testing Techniques", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=11025195&casa_token=NFFzAyilcLcAAAAA:zeL7xWmkMzM962wSa6X2uKZh7R-8l69ykx9uWIOlvxNqV3EeccTDbxaftJ9OFoAe6ydVORxE1aw", "interaction": "Hybrid", "analysis": "Qualitative", "usedByStudents": "Yes" },
    "Prompting Large Language Models to Power Educational Chatbots": { "id": "ID50", "level": "B", "year": "2023", "source": " Proceedings of the 22nd International Conference on Web-Based Learning (ICWL 2023)", "authors": "Juan Carlos Farah, Sandy Ingram, Basile Spaenlehauer, Fanny Kim-Lan Lasne e Denis Gillet", "educationalObjectives": "Students interacted with the chatbot to discuss issues in code snippets, understand the corrections, and deepen their knowledge of the good programming practices taught in the course. The primary motivation of the study was to develop and test an architecture to facilitate the integration of educational chatbots powered by Large Language Models (LLMs) into digital education platforms. The main objective of the study was to teach good software engineering practices, with a focus on JavaScript. The activity covered code style standards, the concept of linting, the ESLint tool, and the use of style guides, using the Airbnb JavaScript Style Guide as a practical example. The core competency the study sought to develop in students was the ability to analyze and debug code.", "aiEmployment": "The study utilized the \"\"Fixer-Upper\"\" pedagogical pattern, in which students analyzed code snippets that were functionally correct but contained intentional style flaws in order to learn good programming practices. The activity took place in a 45-minute online lesson structured into 10 phases, which included pre- and post-tests, concept presentations (linting, ESLint, style guides), code review exercises, reflection, and feedback. In the experimental group, generative AI (the Graasp Bot) was integrated, offering hints in three stages (explaining the problem, suggesting a correction, and posing a question to engage the student), functioning as interactive support in the learning process. The AI was employed in the form of a custom educational chatbot. The prompts were entirely fixed and created by the researchers/educators. Students had no role in creating or modifying the prompts. The chatbot played a supportive role in the lesson, offering explanations and engaging students in dialogues about the learning topics. The study adopted a mixed-methods analysis, combining quantitative and qualitative data. For the quantitative part, t-tests were used to compare the groups in terms of learning gains (pre- and post-test), engagement (time spent on phases), usability (UEQ), and sentiment analysis (VADER). For the qualitative part, open-ended responses were coded, revealing positive perceptions but also criticisms that the chatbot was repetitive and insistent. The analysis of the 150 conversations showed that they were relevant to the topic and most were short.", "llm": "Graasp Bot, this chatbot was specifically developed for the study and powered by OpenAI's GPT-3 language model.", "metrics": "Questionnaires, Time Comparison, User Satisfaction", "metricsUsage": "The User Experience Questionnaire (UEQ), a standard instrument for measuring the usability of the lesson across six dimensions: Attractiveness, Perspicuity (clarity), Efficiency, Dependability, Stimulation, and Novelty. Student engagement was measured by calculating the total time they spent on each of the 10 phases of the lesson. The researchers then compared the time spent between the group with the chatbot and the group without the chatbot. This was complemented by a qualitative analysis of student feedback from open-ended questions, where they described what they liked and what could be improved in the lesson and the chatbot.", "resources": "The study used the Graasp platform with the integrated Code Capsule application and Graasp Bot (GPT-3). The materials included flawed code snippets (Fixer-Upper), explanations, and hints from the chatbot. The assessment was conducted using pre/post-tests, self-reflection, and the UEQ.", "benefitsAndChallenges": "Among the benefits, it was highlighted that students found the chatbot useful, interactive, and innovative. They also noted that it helped them focus on the activity, provided quick answers, and stimulated deeper reflection when the questions were well-formulated. On the other hand, the main challenges were its repetitiveness and the lack of naturalness in the interactions, which some perceived as irritating, leading them to question its actual necessity. The study also pointed out the sensitivity of prompt engineering and broader challenges such as bias, privacy, and the tool's lack of adaptability.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Data Structures and Algorithms, Programming Fundamentals and Languages", "doiOrLink": "https://juancarlosfarah.com/assets/pdfs/farah2023prompting_am.pdf", "interaction": "Fixed", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Innovative Approach to Agile Education: Generative AI-Supported Planning Poker Simulation": { "id": "ID51", "level": "B", "year": "2024", "source": "International Conference on Information Technology Based Higher Education and Training (ITHET)", "authors": "Khalid Nafil e Youssef Lefdaoui", "educationalObjectives": "The primary problem that the study aimed to address is the challenge of teaching Planning Poker in a university setting. The effectiveness of this ceremony relies on expert judgment, where experienced team members estimate task effort. However, in an academic context, students are not yet experienced experts, which makes the effective execution of the ceremony a significant challenge. The educational objectives in Software Engineering, as addressed in the study, are quite specific and focused on teaching agile methodologies. The main content taught is the Planning Poker ceremony from the Scrum framework.", "aiEmployment": "In the activity, students acted as facilitators, while AI agents assumed the roles of Scrum Master and developers, complete with realistic competencies and cognitive biases, to conduct user story estimation. The process involved theoretical preparation, simulation setup, iterative execution of estimates by the AI agents, and analysis of interaction logs. In the experience described in the article, AI was employed as an active part of the Planning Poker simulation process in a Scrum course. The prompts were fixed and created by the instructors; the AI played the roles of Scrum team members (tutor, co-author, expert). The study conducted a quantitative analysis of the interactions between students and AI agents (Scrum Master and developers) during the Planning Poker simulation. Chat logs were exported to CSV format, recording the sender, receiver, interaction type, and assigned estimates. The analysis followed five axes: agent interactions, student participation, collaboration patterns, communication, and decision-making. Techniques such as interaction counting, frequency analysis, and the construction of communication graphs were used to visualize message flows.", "llm": "Character.ai", "metrics": "Quantitative Analysis of Chat Messages", "metricsUsage": "Data were collected from a chat log and recorded in a CSV file for analysis.", "resources": "In the study, the teaching materials and resources were directed towards the practical simulation of Planning Poker. Students used the Character.ai platform to create and interact with AI agents (a Scrum Master and developers), which were configured using custom prompts that defined their competencies, biases, communication style, and role in Scrum. The activity included a user story with detailed acceptance criteria and an explanation of the Planning Poker rules (objective, mechanics, the Fibonacci sequence, and reaching consensus). The virtual chat environment was used to conduct the real-time simulation and to record data for analysis.", "benefitsAndChallenges": "The study indicates that LLMs and generative AI offer significant benefits in Software Engineering education, including the creation of innovative pedagogical scenarios, the simulation of realistic professional environments, increased student engagement and collaboration, and support for inexperienced practitioners, in addition to the automation of specific tasks. However, the challenges include ensuring information accuracy, the need for human oversight, the inability to completely replace human judgment, and the presence of cognitive biases in the AI agents.", "swebokAreas": "Software Testing", "swebokSubAreas": "Planning Poker, Testing Techniques", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10837671&casa_token=PYgR7GiWUL4AAAAA:O-XNTEPxV6YPhUwRz9pdNmm5Quf4aIW4z8Pktcl55O2j3vZalbkkSLsTNpn_ur-dFW2A2rRQ71k", "interaction": "Fixed", "analysis": "Quantitative", "usedByStudents": "Yes" },
    "Leveraging Lecture Content for Improved Feedback: Explorations with GPT-4 and Retrieval Augmented Generation": { "id": "ID52", "level": "C", "year": "2024", "source": "International Conference on Software Engineering Education and Training (CSEE&T)", "authors": "Sven Jacobs e Steffen Jaschke.", "educationalObjectives": "The primary objective is to assist students in learning and applying programming concepts that have been previously taught in an introductory course. The study indicates that the Tutor Kai tool aims to support introductory programming education in Software Engineering by fostering independent problem-solving, skill development, and bridging the gap between theory and practice, in addition to providing individualized support at scale. The research shows that generative AI was used in an introductory programming course to reinforce concepts, develop autonomous problem-solving, and connect theory with practice. The study's focus, however, was on student perceptions of the tool, without formally assessing the effective acquisition of knowledge or skills.", "aiEmployment": "The study employed a guided autonomous learning strategy, in which the AI tutor provides contextualized feedback without revealing the solution, using Retrieval-Augmented Generation (RAG) to integrate excerpts from video lectures. Students could choose between quick or detailed feedback, promoting independent problem-solving and connecting theory to programming practice. The AI was utilized as the core of a customized feedback system named \"\"Tutor Kai,\"\" designed for an introductory programming course. The prompts were entirely fixed and created by the researchers as an integral part of the Tutor Kai system's design. Students did not create, edit, or interact directly with the prompts. The study used a mixed-methods analysis to evaluate Tutor Kai. The quantitative analysis showed that students preferred quick feedback (478 out of 574 interactions) and rated the usability at 74.8. The qualitative analysis revealed that they adopted a situational strategy, using quick feedback for easy tasks and detailed feedback (with links to videos) for difficult tasks, thereby connecting theory with practice.", "llm": "GPT-4", "metrics": "Questionnaires, Time Comparison, User Satisfaction", "metricsUsage": "The primary assessment was conducted through a questionnaire administered to 15 students following a workshop. The questionnaire contained questions about the quality of the feedback, system usability, and general concerns. Satisfaction was measured through the responses to this questionnaire. The results showed that students were, in general, satisfied with the simplicity, length, and clarity of the feedback. The study also explicitly measured and compared the generation time for the two types of feedback.", "resources": "The study's primary materials included the Tutor Kai exercise environment, video lecture recordings, and programming assignments. To generate feedback, the AI analyzed the student's code, the task description, and the compiler output. Supporting technical resources included lecture transcripts and a vector database for implementing the Retrieval-Augmented Generation (RAG) technique.", "benefitsAndChallenges": "The study identified benefits of using LLMs in programming education, such as better concept identification, connecting theory and practice, promoting autonomy, providing understandable and reliable feedback, and reducing incorrect information via RAG. The main challenges included the slowness of the detailed feedback, students' over-reliance on the AI, and the technical complexity of implementing the system.", "swebokAreas": "Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages", "doiOrLink": "https://ieeexplore.ieee.org/document/10837671", "interaction": "Fixed", "analysis": "Mixed", "usedByStudents": "No" },
    "Pair Programming in Programming Courses in the Era of Generative AI: Students' Perspective": { "id": "ID53", "level": "A", "year": "2024", "source": "Asia-Pacific Software Engineering Conference (APSEC) ", "authors": "Mario Simaremare, Chandro Pardede, Irma Tampubolon, Daniel Simangunsong, Putri Manurung.", "educationalObjectives": "The AI acted as an on-demand support tool, a programming assistant, and a private tutor, whose instructional focus was dictated by the immediate needs and difficulties of each student during the proposed activities. The objectives range from learning fundamental and advanced programming techniques to applying theory in practice, generating and debugging code, and refactoring to improve quality. In summary, GenAI helps to consolidate concepts, support coding, and strengthen essential competencies in the field. The study integrates AI as a support tool to assist students in learning the existing content of programming courses and, in this process, seeks to observe and develop a set of practical and metacognitive skills essential for Software Engineering.", "aiEmployment": "Student-centered learning, flipped classroom, and problem-based learning methodologies were applied. The core of the study was pair programming in two phases: in the first, student+AI (with the AI acting as a partner); in the second, student+student with AI support (the model preferred by the students). GenAI was used to clarify concepts, generate examples and code, and debug and refactor solutions. The AI was employed in an integrated and structured manner in the programming courses through an experimental pair programming strategy, divided into two phases over a semester. The AI played multiple roles, depending on the student's needs and the task at hand. The prompts were created entirely by the students. The study conducted a qualitative analysis based on semi-structured interviews with 12 CS1 and CS2 students, selected to represent different performance levels. The data was transcribed and analyzed using Thematic Analysis, resulting in three main categories: GenAI use cases, challenges in using GenAI, and perceptions of pair programming with GenAI.", "llm": "ChatGPT and Copilot", "metrics": "User Satisfaction, Thematic Analysis", "metricsUsage": "The results show that students felt a lack of engagement when pairing with the AI and preferred traditional pairing, but they considered that the AI worked better as an additional reinforcement for the student pair. The qualitative data collected from the interviews were analyzed using this technique to identify patterns and recurring themes, such as use cases, challenges, and perceptions.", "resources": "The study used flipped-learning materials (videos, slides, and notes), Generative AI tools (ChatGPT, GitHub Copilot, Gemini, and Perplexity AI), and practical exercises in problem-based laboratory sessions, complemented by an introductory workshop to train students in the ethical and effective use of AI tools.", "benefitsAndChallenges": "The study identified that students perceived benefits of Generative AI in five areas: clarifying difficult concepts, generating practical examples, developing code, debugging, and refactoring, thereby strengthening their learning and programming practice. On the other hand, they recognized six challenges: excessive dependency, solution complexity, response inaccuracy, language barrier, narrow learning horizons, and difficulty in creating contextual prompts.", "swebokAreas": "Software Construction, Computing Foundations", "swebokSubAreas": "Programming Fundamentals and Languages, Practical Considerations", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10967301&casa_token=7bOgz4JwaIkAAAAA:zfTNe-z4nk7i-EXMnnbgle1u9oYyeGtx1LgaALimIfwyK3JkEmEFylxqgf68xgSC2PR3amTwsBc", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Stimulating Critical Thinking in a Web Programming Module with Generative AI Tools": { "id": "ID54", "level": "A", "year": "2024", "source": "EEE Global Engineering Education Conference, EDUCON.", "authors": "Usman Naeem, Arne Styve, Outi T. Virkki.", "educationalObjectives": "The study focused on teaching the fundamental languages of web programming, which are HTML5, CSS, JavaScript, and PHP. The study defines four objectives: developing solid technical knowledge, fostering critical thinking, using AI responsibly, and preparing students for the job market. The content taught was web programming, and the primary skill developed through generative AI was critical thinking, preparing students to be competent and responsible users of the technology.", "aiEmployment": "The study applied an active and project-based learning approach, integrating Generative AI to stimulate critical thinking. Students developed a portfolio website in phases, using GitHub Copilot to generate code and ChatGPT for critical analysis, refactoring, and improving the code based on these evaluations. The AI was used as a support tool, not to provide ready-made answers, and self-assessment questionnaires measured changes in critical thinking. The AI was used in two complementary roles: GitHub Copilot as an initial code generator and ChatGPT as a peer reviewer, creating a cycle of generation, analysis, critique, and refactoring with the student always at the center of the decisions. The approach evolved from guided prompts to student-created prompts, allowing for the development of prompt engineering and critical analysis skills regarding the AI-generated code. The study primarily conducted a quantitative analysis through pre- and post-intervention questionnaires to measure changes in students' critical thinking. This was complemented by a qualitative assessment of project reports, which focused on prompt formulation, explanation of algorithms, and the refactoring of AI-generated code.", "llm": "GitHub CoPilot and ChatGPT", "metrics": "Questionnaires, Likert Scale, Project and Report Evaluation", "metricsUsage": "The study used a self-assessment questionnaire on critical thinking to measure students’ opinions and practices. This questionnaire was administered before and after the AI-based pedagogical intervention. It employed a five-point Likert scale, with response options indicating the frequency of critical thinking practices, ranging from \"\"never\"\" to \"\"always.\"\" Finally, the instructors evaluated the quality and complexity of the prompts created by the students, as well as the depth of their explanation of the algorithm’s functioning in the submission report.", "resources": "The instruction utilized development environments (VS Code) and AI tools (GitHub Copilot and ChatGPT), weekly exercises, and a 12-week portfolio project. This was complemented by reports, critical thinking questionnaires, diagrams, and screenshots, all organized within a hands-on, problem-based, and project-based approach that included theoretical lectures and lab sessions.", "benefitsAndChallenges": "The study shows that LLMs, such as ChatGPT and GitHub Copilot, offer benefits when integrated in a structured manner: they stimulate critical thinking, provide a starting point for complex tasks, promote deep learning, and develop industry-relevant skills. On the other hand, they present challenges, including the risk of superficial learning and dependency, over-reliance on AI, the need for new pedagogical approaches, time constraints for critical reflection, and the insufficiency of a single intervention to form lasting habits, requiring continuous integration throughout the course.", "swebokAreas": "Software Construction", "swebokSubAreas": "Practical Considerations", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=11016298&casa_token=ER0OXvYxHKgAAAAA:BzXh2QxzQ-uxwL4dy1Qooy0jtZtcKpJhc4Z970OogcHDeV0Nyl5GkbJtxTTIAYG2DiJOV3F01Cc", "interaction": "Free Prompts", "analysis": "Quantitative", "usedByStudents": "Yes" },
    "Supporting Brainstorming Activities with Bots in Software Engineering Education": { "id": "ID55", "level": "B", "year": "2025", "source": "International Workshop on Bots in Software Engineering (BotSE)", "authors": "Juan Carlos Farah, Jérémy La Scala, Sandy Ingram, Denis Gillet.", "educationalObjectives": "The primary motivation was to study the results of a tool integrated into a brainstorming environment through two \"\"bots\"\" (autonomous agents) based on OpenAI's GPT-4o model. These bots participated in the brainstorming sessions as team members, automatically proposing ideas. The educational objectives of the frontend development course include learning the software lifecycle, acquiring knowledge in UX, practicing component-based programming, developing creativity and critical thinking, and exercising ideation on high-level aspects of the project. The main focus is on measuring the impact of collaborating with AI bots on the brainstorming process within an existing Software Engineering course.", "aiEmployment": "The teaching strategy was a semester-long group project based on project-based learning, in which structured brainstorming served as the ideation method to define high-level aspects of a frontend web application. Generative AI was used solely as an experimental variable to observe its impact on the process. Generative AI, specifically OpenAI's GPT-4o model, was employed indirectly through \"\"bots\"\" integrated into an online collaborative brainstorming application. The prompts were fixed and predefined by the researchers, not by the students. The study's analysis was quantitative, based on idea count data and Likert scale questionnaires. The data was processed using descriptive statistics (means, medians, standard deviations, minimums, and maximums) and non-parametric tests, including the Wilcoxon signed-rank test to compare conditions with and without bots, rank biserial correlation to measure effect size, and the Kruskal-Wallis test to assess differences across teams and tasks.", "llm": "ChatGPT 4o", "metrics": "Questionnaires, Likert Scale", "metricsUsage": "Questionnaires were administered after each of the four brainstorming tasks. Specifically, a seven-point Likert scale (1 = Strongly Disagree to 7 = Strongly Agree) was used to measure students' perceptions of accountability, authorship, originality, and utility.", "resources": "The resources used included an introductory presentation, a one-hour brainstorming exercise integrated into a semester-long group project, and the use of an online collaborative brainstorming application within the Graasp platform to support the development of a responsive web application focused on the software lifecycle, UX, and component-based programming.", "benefitsAndChallenges": "In the study, the perception of using LLMs in collaborative brainstorming was predominantly negative. The findings showed that the presence of AI reduced idea generation, the students' sense of authorship, and their accountability, without bringing clear benefits to the utility or originality of the ideas.", "swebokAreas": "Professional Practice", "swebokSubAreas": "UX, Group Dynamics and Psychology", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=11050849&casa_token=VgCvcPVz21YAAAAA:xcKYwgsr_EIdcHE30rCt-7I_adg9aeZHmVC9_AUVLXb7vSM0Np-0rvF3CpwTKxcjpZtwhT94OAs", "interaction": "Fixed", "analysis": "Quantitative", "usedByStudents": "Yes" },
    "Using an LLM to Help with Code Understanding": { "id": "ID56", "level": "B", "year": "2024", "source": " International Conference on Software Engineering (ICSE ’24)", "authors": "Daye Nam, Andrew Macvean, Vincent Hellendoorn, Bogdan Vasilescu, and Brad Myers", "educationalObjectives": "Participants, including a group of 16 students, were assigned software engineering tasks that involved understanding and modifying an unfamiliar Python codebase related to data visualization and 3D rendering. The study focuses on the development of code comprehension as a central educational objective, which includes learning to use unfamiliar APIs, assimilating domain-specific knowledge, enhancing information-seeking skills, and modifying or extending existing code. The paper aimed to investigate how generative AI can support the comprehension of unfamiliar code, assisting developers in learning and using new APIs, assimilating domain concepts, seeking information more efficiently, and modifying or extending existing code.", "aiEmployment": "The study adopted an investigative, AI-mediated learning approach, placing participants in realistic unfamiliar code modification tasks. They were required to seek information independently using either the web (control group) or the GILT tool in VS Code (treatment group). The tool offered on-demand explanations via predefined buttons (e.g., overview, API, concept, examples) and supported open-ended, natural language queries with the selected code automatically included as context. The primary goal of employing AI was not to generate new code, but to assist participants in comprehending an unfamiliar source code. The study combined fixed and open-ended prompts, enabling participants to obtain quick explanations or ask free-form questions, with the selected code always being automatically added as context. The study employed a mixed-methods analysis: quantitative, using regressions, statistical tests, and performance metrics (progress, time on task, comprehension, TAM, TLX, and usage logs); and qualitative, through the analysis of interactions, open-ended responses, emerging themes, and prompt n-grams, to assess the impact of, interaction with, and perception of the GILT tool.", "llm": "ChatGPT-3.5", "metrics": "Questionnaires, Time Comparison, User Satisfaction, Task Completion Rate", "metricsUsage": "The study utilized multiple questionnaires: a pre-study survey to collect demographic and experience data, a post-task questionnaire to measure code comprehension, and a post-study survey to assess perceptions of the tools. The time participants took to complete each subtask was measured and statistically analyzed using regression models to compare the GILT tool condition against the web search condition. The TLX questionnaire measured frustration and the perceived success in performance. Furthermore, the qualitative analysis of open-ended responses captured user feedback on their overall experience. Finally, the researchers evaluated the correctness of each participant's solution to the subtasks and measured how many were implemented correctly.", "resources": "The study provided starter code, tutorials, demonstrations, and pre- and post-task questionnaires, and permitted the use of search engines as a supplementary resource. The experimental design included a control group and a GILT (treatment) group, and the collected data has been made available in an online replication package.", "benefitsAndChallenges": "Participants perceived the GILT tool as useful, efficient, and well-integrated with the code context. This enhanced their sense of success, and they viewed it as complementary to other AI tools. However, they also faced challenges, including difficulty in crafting effective prompts, the risk of outsourcing their own comprehension, inaccurate responses, and varied interface preferences.", "swebokAreas": " Engineering Foundations", "swebokSubAreas": "Empirical Methods and Experimental Techniques", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3597503.3639187", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Leveraging Large Language Models for Enhanced VR Development: Insights and Challenges": { "id": "ID57", "level": "A", "year": "2024", "source": " Gaming, Entertainment, and Media Conference (GEM)", "authors": "Amany Alkhayat, Brett Ciranni, Rupa Samyukta Tumuluri, Rohit Srinivas Tulasi.", "educationalObjectives": "The motivation was driven by the difficulty novices face in VR development and the lack of documented research on how new AI tools could address this problem. The study's research question directly reflects this motivation, questioning the effectiveness of LLMs in guiding interaction design, generating code, and solving common challenges in VR development with Unity. To develop C# programming skills, enhance problem-solving and debugging, learn to implement VR features and interactions, and understand code quality metrics. Generative AI assisted novices in VR development with Unity by supporting them in C# programming, error debugging, VR interaction design and implementation, the use of the Unity tool, and the application of code quality best practices.", "aiEmployment": "The identified learning strategy was self-directed and AI-assisted, where novice developers reactively turned to ChatGPT to solve specific problems. They requested C# code generation accompanied by detailed explanations and instructions for integration into Unity. The process was iterative, involving successive refinements of prompts and alternative attempts, which enhanced their understanding of errors and strengthened their problem-solving skills. Additionally, external verification was conducted using sources such as tutorials and forums, along with collaboration with a senior researcher, ensuring greater accuracy and complementing the solutions provided by the AI. The usage did not follow a fixed script; instead, the AI was triggered whenever a challenge or need arose during project development. The primary uses of the AI included C# code generation and correction, error resolution and debugging in Unity, implementation of VR functionalities with step-by-step instructions, and support for brainstorming and feature ideation. Quantitative Analysis: This evaluated the quality of the C# code generated by ChatGPT using Visual Studio 2019 metrics (Maintainability Index, Cyclomatic Complexity, Depth of Inheritance, Class Coupling, and Lines of Code), comparing script versions with and without corrections to measure improvements. Qualitative Analysis: This explored the researchers' experiences and perceptions through the documentation of prompts and interactions, followed by thematic analysis (identification of patterns, successes, and difficulties) and reflective analysis, which contrasted the perspectives of novices with that of an experienced Unity instructor.", "llm": "ChatGPT ( v3.5  v4) and Gemini", "metrics": "Generated Code Accuracy", "metricsUsage": "The main accuracy metric was code functionality. The study repeatedly compared code that \"\"worked\"\" versus code that \"\"did not work\"\" in the Unity environment to assess the effectiveness of the AI responses.", "resources": "Development tools (Unity and Visual Studio 2019), external verification resources (YouTube, Reddit, Stack Overflow, Unity forums), and collaboration with experienced instructors.", "benefitsAndChallenges": "The study identified several benefits, including accelerated development speed, step-by-step implementation support, learning opportunities from error resolution, ideation support, and the ability to interpret instructions despite inaccuracies. Conversely, the challenges included outdated knowledge and incorrect information, the AI's tendency to agree with the user ('sycophancy'), a lack of visual context and the assumption of prior knowledge, dependency on prompt quality, and inconsistent performance across different LLMs.", "swebokAreas": "Software Maintenance", "swebokSubAreas": "VR Development, Software Maintenance Techniques", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=10585495&casa_token=kVLyhue33mAAAAAA:12f8jWnYxD7gxT-BpZtIq72fMGz_lS8xeXEp1B77XP4UCGffR7LL_w7Haa0gYGnAi__shrsATWs", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "Lifelong Learning in Software Engineering: Towards an AI-driven Tutor for Cloud-Based Software Architectures": { "id": "ID58", "level": "B", "year": "2025", "source": "2025 IEEE European Technology and Engineering Management Summit (E-TEMS)", "authors": "Marcel Mitas; Sabine Sachweh", "educationalObjectives": "The study aims to support novices in software engineering in learning how to create software architectures, apply best practices, and understand software design decisions with the help of an AI tutor. The educational focus also includes helping learners understand design patterns, requirements, domain models, use case scenarios, and the evaluation of parts of software architectures. The target group is explicitly described as students or trainees with no experience in creating domain models, use case scenarios, cloud-based software architectures, and architecture decision practices.", "aiEmployment": "AI was employed through a four-step prompt-engineering method that turns LLMs into a tutor for software architecture learning. First, the model is assigned a tutor role tailored to novice learners. Second, it receives contextual data about the system to be designed, including requirements and architectural artifacts. Third, it generates reference software architectures and Architecture Decision Records (ADRs). Fourth, it interacts with learners by answering relevant questions, giving counter-questions and hints, evaluating architecture parts, and avoiding giving full solutions directly.", "llm": "ChatGPT 4o and Llama 3.1 Tulu 3 70B", "metrics": "No formal quantitative metrics were reported.", "metricsUsage": "No formal quantitative metrics were reported.", "resources": "The study used the MobSTr dataset, which contains textual functional and non-functional requirements, assumptions, potential hazards, and system component models in UML notation for an autonomous driver assistance system. The models also received text documents with requirements, assumptions, and hazards, plus a component diagram from the dataset. In addition, the interaction involved prompts about architectural patterns, ADR creation, requirements separation, the evaluation of component diagrams, and a domain model produced during exploratory analysis.", "benefitsAndChallenges": "The paper reports that ChatGPT 4o behaved in a friendly and often encouraging way, pushing learners to think about architectural patterns and evaluate their own architectures. It also provided detailed feedback on whether best practices and requirement coverage were being considered. At the same time, some answers were too broad. For Llama 3.1, the responses were more formal and detailed, but it had important limitations: it did not properly read architecture examples in PDF/image form, its context window reached 75% capacity quickly, requiring re-initialization, and local deployment demanded substantial memory, GPU, and CPU resources.", "swebokAreas": "Software Architecture", "swebokSubAreas": "Architectural Design, Architecture as Significant Decisions, Architecture Evaluation", "doiOrLink": "https://ieeexplore.ieee.org/abstract/document/11239087", "interaction": "Hybrid", "analysis": "Qualitative", "usedByStudents": "No" },
    "Accelerating Educational Assessment in Software Engineering through Human-AI Collaboration": { "id": "ID59", "level": "C", "year": "2025", "source": "2025 IEEE 37th International Conference on Tools with Artificial Intelligence (ICTAI)", "authors": "Dimitrios-Nikitas Nastos; Themistoklis Diamantopoulos; Andreas Symeonidis", "educationalObjectives": "To support and accelerate educational assessment in Software Engineering while preserving instructor control and assessment quality. The paper focuses on evaluating multiple software engineering artifacts and providing meaningful feedback across requirements, architecture, implementation-related artifacts, and design-related deliverables.", "aiEmployment": "AI was employed as part of a human-AI collaborative assessment workflow. The methodology has four parts: domain knowledge integration, AI review generation, human-AI collaboration, and quality assurance. The system was implemented in the UseRev platform, where the LLM receives course materials, rubrics, examples, and student artifacts, then generates criterion-specific scores and detailed feedback, which instructors can review, edit, adopt, or override.", "llm": "Claude 3.7 Sonnet", "metrics": "Assessment time, percentage reduction, criterion-specific scores, weighted overall scores, and project-level score.", "metricsUsage": "The evaluation compared 15 manually assessed projects with 15 AI-assisted projects in a graduate software engineering course. The authors measured assessment time by artifact type and total time per project. Total assessment time decreased from 125.6 minutes to 69.5 minutes, a 44.7% reduction. The system also generated weighted criterion-level scores and overall artifact/project scores to support instructor review.", "resources": "Course materials, lecture content, textbook/reference material, assessment rubrics, examples of good and poor work, and student project artifacts.", "benefitsAndChallenges": "Benefits: improved efficiency, transparent AI reasoning, instructor control, criterion-level feedback, and support for identifying technical and pedagogical issues that instructors might miss. Challenges: single-course context, only 3 instructors, dependence on Claude 3.7 Sonnet, required setup effort for domain knowledge integration, and no direct measurement of student learning outcomes.", "swebokAreas": "Software Requirements, Software Architecture", "swebokSubAreas": "Requirements Specification, Architecture Evaluation, Architectural Design, Software Architecture Description", "doiOrLink": "https://ieeexplore.ieee.org/abstract/document/11272487", "interaction": "Used by professors", "analysis": "Mixed", "usedByStudents": "No" },
    "A Comparative Study on ChatGPT and Checklist as Support Tools for Unit Testing Education": { "id": "ID60", "level": "A", "year": "2025", "source": "FSE Companion ’25: Proceedings of the 33rd ACM International Conference on the Foundations of Software Engineering", "authors": "Zihan Fang; Jiliang Li; Anda Liang; Gina R. Bai; Yu Huang", "educationalObjectives": "To improve unit testing education by comparing three support conditions: checklist, ChatGPT, and checklist + ChatGPT. The study examines how these tools affect students’ test design, test implementation, and subjective experience in unit testing tasks.", "aiEmployment": "ChatGPT was used as a student-facing support tool during unit testing tasks. Students either used only ChatGPT or ChatGPT together with the checklist while designing test cases and implementing JUnit tests. The study then compared their interactions, performance, and perceptions against students using only the checklist.", "llm": "ChatGPT-4.0", "metrics": "Requirements Coverage; Instruction Coverage; Branch Coverage; Mutation Coverage; Identified Bugs; Maintainability Issues; Test Name Quality; Erroneous Test Cases; Total Test Count; Normalized Erroneous Implementations; time spent on actions; post-task survey responses.", "metricsUsage": "The authors evaluated student work from four angles: completeness, effectiveness, maintainability, and implementation barriers. They manually computed requirement coverage and identified bugs, used EclEmma for instruction and branch coverage, PITest for mutation coverage, and SonarQube for maintainability issues. They also measured normalized erroneous implementations to capture cases where written tests did not match the student’s intended logic or contained compilation or logic problems. Statistical analysis used two-way ANOVA, Mann-Whitney U, and Wilcoxon Signed-Rank tests.", "resources": "A unit testing checklist, ChatGPT, JUnit 5, two tasks, screen recordings, and a post-task survey. The two tasks were: Mars Rover API for test design in comments, and Bowling Score Keeper for JUnit test implementation. The second task used a program with three classes, 86 lines of code, and three seeded faults. Assignment materials were distributed through GitHub repositories.", "benefitsAndChallenges": "Benefits: ChatGPT helped students finish tasks faster, rely less on external resources, and deal with programming-language issues. Challenges: its usefulness depended heavily on prompt quality; many students accepted generated tests without checking the logic; ChatGPT did not solve implementation barriers and could encourage superficial engagement. When both tools were available, students preferred the checklist.", "swebokAreas": "Software Testing", "swebokSubAreas": "Unit Testing, Test Design and Implementation, Test-Related Measures", "doiOrLink": "https://dl.acm.org/doi/epdf/10.1145/3696630.3727244", "interaction": "Free prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
    "A Student-Centric Evaluation Survey to Explore the Impact of LLMs on UML Modeling": { "id": "ID61", "level": "B", "year": "2025", "source": "Information, 2025, Volume 16, Article 565", "authors": "Bilal Al-Ahmad, Anas Alsobeh, Omar Meqdadi, Nazimuddin Shaikh", "educationalObjectives": "To evaluate how well LLMs can support UML modeling education by generating Class, Deployment, Use Case, and Sequence diagrams, and to examine how students judge their completeness and correctness compared with human-created diagrams.", "aiEmployment": "GPT-4-turbo was used to generate UML diagrams from natural-language scenarios through a rule-based prompt-engineering framework. The generated UML code was rendered with PlantUML and then compared with human-created diagrams in a student-centered survey involving 121 students from three U.S. universities.", "llm": "GPT-4-turbo", "metrics": "Completeness Ratio (CR), Constraint Satisfaction / correctness score (CS), survey-based completeness and correctness scores, paired t-tests, Wilcoxon signed-rank tests, and effect sizes (Cohen’s d)", "metricsUsage": "The study evaluated diagrams on two main dimensions: completeness and correctness. Students judged specific elements of each UML diagram type, and responses were converted into binary values and aggregated into average scores. The authors then compared LLM-assisted and human-created diagrams using paired t-tests, Wilcoxon signed-rank tests, and Cohen’s d. Across all four diagram types, LLM-assisted diagrams scored significantly lower than human-created ones.", "resources": "The study used the iCoot Car Rental System scenario from a textbook, human-created UML diagrams from the same textbook, GPT-4-turbo, PlantUML, and a Qualtrics survey completed by 121 computer science and software engineering students from three U.S. universities.", "benefitsAndChallenges": "Benefits: LLMs showed meaningful support for UML modeling, especially for Sequence and Deployment diagrams, and the study provides a validated evaluation framework for UML education. Challenges: LLM-assisted diagrams consistently underperformed human-created diagrams; the largest gaps appeared in Class and Use Case diagrams, especially in relationships, multiplicities, visibility, links, and generalization. The study also notes limitations related to the use of a single model, a single domain, and student evaluator variability.", "swebokAreas": "Software Engineering Models and Methods, Software Architecture", "swebokSubAreas": "Structural Modeling, Behavioral Modeling, Architecture Description, Architecture Evaluation", "doiOrLink": "https://www.mdpi.com/2078-2489/16/7/565", "interaction": "Fixed Prompts", "analysis": "Quantitative", "usedByStudents": "No" },
    "Benchmarking AI Tools for Software Engineering Education: Insights into Design, Implementation, and Testing": { "id": "ID62", "level": "B", "year": "2026", "source": "SIGCSE TS 2026: Proceedings of the 57th ACM Technical Symposium on Computer Science Education V.1", "authors": "Nimisha Roy, Oleksandr Horielko, Olufisayo Omojokun", "educationalObjectives": "To benchmark AI tools for software engineering education across design, implementation, debugging, and testing, and to derive guidance for how instructors can integrate these tools into SE courses. The paper also aims to help students learn tool selection, prompt refinement, verification, and critical evaluation of AI outputs.", "aiEmployment": "AI tools were used as task-support tools across multiple SE phases. The study benchmarked tools for design documentation (e.g., UML/UI generation), feature implementation, debugging/refactoring, testing, and full project implementation using standardized prompts and controlled comparison procedures.", "llm": "GPT-4 / GPT-4o, Claude 3.5, Gemini 1.5, GitHub Copilot, Codeium, Supermaven, TabNine, Replit AI", "metrics": "Prompt Iterations (PI); Task Completion Time (TCT); Setup Time (ST); Human Edits (HE); Output Controllability Score (OCS); IDE Integration Score (IIS); Hallucination Rate (HR); Cross-file Inconsistency (CFI); Failure Rate (FR); Autocompletion Rate (ACR); Test Precision (PR); Accuracy Score (AS).", "metricsUsage": "The metrics were used to compare tools on four dimensions: cognitive load, usability, negative behavior, and performance. They captured how much effort was needed to obtain usable output, how reliable the tool was, how often it hallucinated or failed, and how accurate its outputs were across SE tasks. The study used these metrics to distinguish tools better suited for UML/UI design, code generation, debugging, white-box testing, and full-project implementation.", "resources": "A collaborative whiteboard web application was used as the common context for design, implementation, and testing tasks. A separate Location Finder app was used for full-project implementation. The study also used standardized prompts, counterbalanced task roles, and multiple AI tools across IDE and web-based environments", "benefitsAndChallenges": "Benefits: AI tools accelerated boilerplate generation, UML/UI sketching, debugging help, and some testing workflows. GPT-4o, Copilot, and Codeium performed especially well in several implementation/testing tasks. Challenges: tools varied widely by task; common problems included hallucinations, cross-file inconsistency, test coverage weaknesses, plausible but incorrect outputs, and the need for strong human verification. The paper stresses that students must learn prompt specificity and critical review.", "swebokAreas": "Software Construction", "swebokSubAreas": "Coding, Construction Testing, Integration", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3770762.3772551", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "No" },
"A comparison of different Large Language Models for the generation of UML class diagrams": { "id": "ID63", "level": "C", "year": "2025", "source": "2025 ACM/IEEE 28th International Conference on Model Driven Engineering Languages and Systems Companion (MODELS-C)", "authors": "Giacomo Garaccione, Diego Maria Calabrese, Riccardo Coppola, Luca Ardito", "educationalObjectives": "To evaluate how different LLMs can support UML class diagram modeling in university-level software engineering education, especially for exercises defined through natural-language specifications. The paper also aims to understand whether LLMs can act as educational modeling assistants for students and educators.", "aiEmployment": "Four LLMs were used to generate UML class diagrams from textual university exercises. The study applied a role-based few-shot prompting strategy, asking the models to behave like an expert UML modeling professor. The generated diagrams were then manually evaluated for syntax, semantics, and completeness.", "llm": "ChatGPT-4o, DeepSeek v3, Gemini 2.5 Pro, Qwen 3", "metrics": "Syntax Errors, Semantic Errors, Diagram Completeness.", "metricsUsage": "The authors compared each generated diagram with the reference solution. Diagram Completeness was calculated as the ratio of matching elements to total elements in the original diagram. Syntax Errors captured UML notation violations, and Semantic Errors captured domain or relationship mistakes such as wrong multiplicities, wrong association types, or wrong attribute/method typing. The study also applied a fixed effect linear model and analyzed error-category distributions across models.", "resources": "The study used 15 real university-level UML class diagram exercises taken from official teaching materials of Italian universities, written in Italian natural-language requirements. Diagrams were represented in Apollon, an open-source UML web modeling editor using JSON, and generated through a structured few-shot prompt with examples.", "benefitsAndChallenges": "Benefits: all models showed reasonable ability to generate sufficiently complete class diagrams; ChatGPT and Gemini performed best on completeness and syntax, while DeepSeek performed best on semantic correctness. Challenges: models still made important semantic mistakes, especially with association type and multiplicity; Qwen struggled with UML syntax more than the others. The paper also notes limitations related to prompting strategy and human evaluation.", "swebokAreas": "Software Engineering Models and Methods, Software Design", "swebokSubAreas": "Structural Modeling, Analyzing for Completeness, Structural Design Descriptions", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&arnumber=11273211", "interaction": "Fixed Prompts", "analysis": "Quantitative", "usedByStudents": "No" },
"An Exploration of How Generative AI Affects Workflow and Collaboration in a Software Engineering Course": { "id": "ID64", "level": "A", "year": "2025", "source": "SPLASH-E ’25: Proceedings of the 2025 ACM SIGPLAN International Symposium on SPLASH-E", "authors": "Marie Salomon, Kyle D. Chin, Reid Holmes, Thomas Fritz, Gail C. Murphy", "educationalObjectives": "To understand how GenAI affects software engineering workflows and team collaboration in a project-based SE course, and to derive pedagogical implications for teaching students in GenAI-augmented teams. The course required students to iteratively design, build, and evolve three versions of a software system in pairs.", "aiEmployment": "GenAI was available with unrestricted use during the course project. Students used chatbots and code-completion tools throughout requirements, design, implementation, and testing. Reported uses included summarizing specifications, getting architectural suggestions, generating/refactoring/debugging code, performing “instant code review”, identifying missing test cases, and retrospectively checking alignment with requirements and design.", "llm": "ChatGPT and GitHub Copilot", "metrics": "Survey responses; GenAI usage rate; perceived usefulness; prompt refinement behavior; semi-structured interviews; thematic analysis; theme support counts.", "metricsUsage": "The study combined a course-wide survey with semi-structured interviews. The survey received 349 responses and the authors report GenAI-use results on 341 valid responses. It measured whether students used GenAI, why they used it, concerns, and how often they had to refine prompts. The interview phase involved 24 students, and the transcripts were analyzed with thematic analysis, producing five themes related to workflow and collaboration.", "resources": "A project-based software engineering course in which pairs of students developed a TypeScript-based backend, a domain-specific query language, and later a frontend and backend server across three project phases. Students also had access to an automated grader, weekly scrum-like TA meetings, office hours, an online forum, and unrestricted GenAI tools.", "benefitsAndChallenges": "Benefits: GenAI was used extensively; most users found it useful; it helped students start faster, summarize specifications, get quick code feedback, reduce blocking, and support testing/debugging. Challenges: students often moved more quickly into implementation and spent less time in requirements/design; GenAI sometimes became the first point of contact before teammates; this reduced direct peer collaboration and raised concerns about wrong solutions and over-reliance.", "swebokAreas": "Software Engineering Process", "swebokSubAreas": "Software Development Life Cycle", "doiOrLink": "http://dl.acm.org/doi/pdf/10.1145/3758317.3759680", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Assessing UML diagrams by GPT: Implications for education": { "id": "ID65", "level": "B", "year": "2026", "source": "The Journal of Systems & Software, Volume 234, Article 112709", "authors": "Chong Wang, Beian Wang, Peng Liang, Jie Liang", "educationalObjectives": "To investigate whether GPT can support assessment of UML diagrams in software engineering education, reducing the grading burden for educators and helping evaluate students’ competence in use case, class, and sequence diagram modeling.", "aiEmployment": "GPT-4o was used as an automatic evaluator/grader for UML diagrams. The researchers designed a grading prompt that included the case description, reference UML diagrams, and detailed scoring criteria. GPT then graded each student’s three UML diagrams and produced deductions and reasons in JSON format. The GPT scores were compared against human expert grading.", "llm": "GPT-4o", "metrics": "Eleven evaluation criteria across three diagram types: UC1–UC4 for use case diagrams, CC1–CC4 for class diagrams, and SC1–SC3 for sequence diagrams. The study also analyzed score differences between GPT and human experts and five discrepancy types: Perfect Match, Misunderstanding, Overstrictness, Wrong Identification, Reasonable Identification.", "metricsUsage": "The authors graded 40 student reports containing 120 UML diagrams in total. GPT and human experts used the same criteria to score the diagrams. The study then compared highest, lowest, and average scores, and analyzed where GPT differed from human experts. GPT generally gave lower scores than human evaluators, with an average grading difference of 1.18 points out of 11.", "resources": "The data came from undergraduate Software Engineering students at Wuhan University in a Requirements Analysis and Modeling course. Students completed a UML modeling task for an Order Processing System case study and produced a use case diagram, class diagram, and sequence diagram. The final dataset included 40 project reports selected from an initial 60, after excluding hand-drawn diagrams.", "benefitsAndChallenges": "Benefits: GPT can complete UML assessment tasks, provide reasons for deductions, and potentially help teachers and students receive faster feedback. Challenges: GPT cannot yet replace human experts. The main weaknesses were misunderstanding grading criteria, overstrict scoring, and wrong identification of UML elements or relationships, with different strengths and weaknesses across use case, class, and sequence diagrams.", "swebokAreas": "Software Engineering Models and Methods", "swebokSubAreas": "", "doiOrLink": "https://www.sciencedirect.com/science/article/pii/S0164121225003784", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
"Bridging Academia and Industry: Leveraging Generative AI in a Software Engineering Course for Practical Industry Experiences": { "id": "ID66", "level": "A", "year": "2025", "source": "ITiCSE 2025: Proceedings of the 30th ACM Conference on Innovation and Technology in Computer Science Education V. 1", "authors": "Daniel Mejia, Ernest D.V. Holmes, Jenn Marroquin, Jamie Gorson Benario", "educationalObjectives": "To provide early undergraduate students with industry-relevant software engineering experience by integrating generative AI into a project-based Software Engineering course. The course objectives include full-stack development, debugging and troubleshooting, testing, Agile practices, version control, cloud computing, and the responsible use of generative AI in software development.", "aiEmployment": "Generative AI was integrated directly into the course as a free-use tool for all assignments and the final project. Students were taught to use it mainly as a prompting tool, a coding assistant, and a service for software engineering tasks such as understanding tools, writing code, debugging, testing, drafting design documents, writing commit messages, and integrating AI features into deployed applications.", "llm": "ChatGPT, Gemini, and Gemini", "metrics": "Post-semester student survey with two open-ended questions; thematic analysis of student responses; inter-rater reliability on 20% of the data; instructor interviews and reflections.", "metricsUsage": "The research team collected a post-semester survey asking students how generative AI supported or impeded their learning. Responses were analyzed using ground-up thematic analysis, and the authors reported category percentages. They also checked inter-rater reliability, reaching 85% agreement for the first open-ended question and 90% agreement for the second. In addition, the team interviewed the two course instructors to capture instructor perspectives on the course’s successes and limitations.", "resources": "The study was based on the Software Development Studio (SDS) course in Google’s Tech Exchange program. The course used tools such as Git/GitHub Classroom, Streamlit, Figma, Google Skills Boost, Google Cloudshell, Google Data Storage, BigQuery, Google Cloud Storage, VertexAI API, Google Gemini, and Gemini Code Assist. The course included five units plus a final project, and students worked in groups to build and deploy cloud-based applications with generative AI features.", "benefitsAndChallenges": "Benefits: students and faculty reported a positive experience; many students said generative AI improved their understanding, productivity, debugging, problem solving, and exploration of new solutions. Instructors also reported strong student growth and greater exposure to real-world software engineering practices. Challenges: some students reported over-reliance, reduced originality, inaccurate responses, and occasional difficulty understanding generated code. Instructors also noted breadth-versus-depth tradeoffs, setup/access issues, and cases where AI-generated unit tests were wrong.", "swebokAreas": "Software Engineering Process, Software Engineering Professional Practice", "swebokSubAreas": "Professional Practice and Industry Readiness, Software Development Processes", "doiOrLink": "https://dl.acm.org/doi/10.1145/3724363.3729036", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Developing Critical Thinking with AI Coding Assistants: An Educational Experience focusing on Testing and Legacy Code": { "id": "ID67", "level": "B", "year": "2025", "source": "ITiCSE 2025: Proceedings of the 30th ACM Conference on Innovation and Technology in Computer Science Education V. 1", "authors": "Isabelle Blasquez", "educationalObjectives": "To develop students’ critical thinking when using AI coding assistants, especially in unit testing, business-rule implementation, legacy code understanding, code review, debugging, and refactoring. The experience aims to help students refine prompts, detect errors and hallucinations, and preserve autonomy while applying software quality best practices.", "aiEmployment": "AI coding assistants were used as student-facing support tools in a guided tutorial. Students used them to generate code, create and review unit tests, implement business rules, explore and understand legacy projects, fix environment issues, and support code review/refactoring. The tutorial was intentionally designed to expose students to assistant limitations so they would analyze, validate, and correct the generated outputs.", "llm": "GitHub Copilot", "metrics": "Questionnaire results; code coverage; compilability of generated tests; test success rate; frequency of hallucinations; perceived usefulness/effectiveness; qualitative student reflections.", "metricsUsage": "The study used a 48-question questionnaire aligned with the tutorial. It measured students’ prior familiarity with coding assistants, the quality of generated code and tests, success/failure of generated tests, code coverage, hallucinations, usefulness of the assistant in legacy-code tasks, and students’ perceptions about productivity, learning, and autonomy. The experience involved 38 second-year CS students.", "resources": "A guided tutorial plus a structured questionnaire. The tutorial had three parts: (1) getting started with the assistant, (2) implementing business rules and generating tests in a simple Java legacy project, and (3) working on a more complex real legacy project. Materials included Java classes such as LibraryMember, Library, ISBN validation tasks, and a real project of about 3,650 lines of code and 59 files, including JavaFileParser", "benefitsAndChallenges": "Benefits: students found the assistants useful for overcoming initial roadblocks, generating test starting points, understanding existing projects, debugging, and improving productivity. Unit test generation was the most appreciated use case. Challenges: the assistants produced hallucinations, incomplete suggestions, wrong test data, poor practices, and outputs requiring constant validation. Many students also feared reduced autonomy and possible negative effects on learning if the tools were overused.", "swebokAreas": "Software Testing", "swebokSubAreas": "Test Design and Implementation", "doiOrLink": "https://dl.acm.org/doi/10.1145/3724363.3729050", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
"Direct Automated Feedback Delivery for Student Submissions based on LLMs": { "id": "ID68", "level": "C", "year": "2025", "source": "FSE Companion ’25: Proceedings of the 33rd ACM International Conference on the Foundations of Software Engineering", "authors": "Maximilian Sölch, Felix T. J. Dietrich, Stephan Krusche", "educationalObjectives": "To provide timely, iterative, and individualized formative feedback on student submissions so that students can better understand mistakes, refine solutions before deadlines, and improve learning outcomes. In the evaluated course settings, the objectives included improving code quality, refactoring, handling edge cases, design-pattern understanding, UML modeling, and written design explanations.", "aiEmployment": "AI was employed through DAFeeD, an LLM-based automated feedback process integrated into the learning platform Artemis via the reference implementation Athena. The system collects context such as the problem statement, grading criteria, submission content, and learner profile, generates a prompt, invokes the LLM, parses the JSON response, and returns inline feedback so students can iteratively resubmit improved work.", "llm": "GPT-4 Turbo", "metrics": "Likert-scale survey measures for comfort, perceived effectiveness, usability, and helpfulness; score distributions across submission attempts; and score differences between Athena and human tutors.", "metricsUsage": "The evaluation had two stages. In the first stage, 20 students used the feedback system in a controlled programming exercise and completed a survey mapped to the research questions on comfort, effectiveness, usability, and helpfulness. In the second stage, Athena was deployed in a large software engineering course, and the authors analyzed score improvements across iterative submissions and compared Athena’s scores with tutor scores on unchanged final submissions.", "resources": "The main resources were Artemis, the reference implementation Athena, and LLM-generated inline feedback. The controlled study used a Java Code Review programming exercise involving code-quality improvements, refactoring duplicated code with the template method pattern, edge cases, and missing methods. The field study used a text exercise on the difference between the strategy and bridge design patterns and a modeling exercise requiring a UML class diagram of a car rental system.", "benefitsAndChallenges": "Benefits: students found the feedback immediate, convenient, relevant, and helpful for understanding mistakes and iteratively improving submissions. Many preferred the integrated system over external AI tools. Challenges: some students reported false positives/negatives, unclear messages, and a need for better categorization and prioritization of feedback. The paper also notes broader concerns such as over-reliance on AI, hallucinations, bias, privacy, and the need for careful prompt and system design.", "swebokAreas": "Software Design", "swebokSubAreas": "Design Quality Analysis and Evaluation", "doiOrLink": "https://dl.acm.org/doi/10.1145/3696630.3727247", "interaction": "Used by Professors", "analysis": "Mixed", "usedByStudents": "Yes" },
"EXPLORING THE USE OF CHATGPT BY COMPUTER SCIENCE STUDENTS IN SOFTWARE DEVELOPMENT: APPLICATIONS, ETHICAL CONSIDERATIONS, AND INSIGHTS FOR ENGINEERING EDUCATION": { "id": "ID69", "level": "A", "year": "2025", "source": "SEFI 2025 - 53rd Annual Conference of the European Society for Engineering Education: Engineering and Society, Proceedings", "authors": "D. Xu, D. Martin", "educationalObjectives": "To understand how computer science students use ChatGPT in software development projects, and how they navigate ethical use, autonomy, critical thinking, and responsible AI-supported learning. The study also aims to inform engineering education by clarifying how students use ChatGPT for coding, debugging, testing, report writing, and project-related decision making while trying to preserve independent thinking.", "aiEmployment": "ChatGPT was used by students as a student-facing support tool across software development tasks. Reported uses included task analysis, brainstorming, code generation, debugging, testing, explanations, and report writing. Students described using it conversationally as a thinking partner, while usually reserving more creative and high-level design decisions for themselves. The study itself examined these practices through semi-structured interviews, rather than through an intervention.", "llm": "ChatGPT", "metrics": "Semi-structured interviews; thematic analysis; intercoder reliability", "metricsUsage": "The study interviewed 6 undergraduate Computer Science students and analyzed the transcripts using thematic analysis. The authors coded the interview data, extracted themes and subthemes, and checked reliability through a focused intercoder agreement process, reaching 92% agreement. The study is primarily qualitative and relies on students’ self-reports rather than experimental performance metrics.", "resources": "The main resources were students’ own software development project experiences, a semi-structured interview protocol, and Zoom interviews. This was not a formal classroom intervention with a tutorial or controlled assignment; instead, it explored how students reported using ChatGPT in their existing software development coursework and related academic tasks.", "benefitsAndChallenges": "Benefits: students reported that ChatGPT helped with understanding assignment requirements, brainstorming, coding, debugging, testing, and report writing. Many used it conversationally to deepen understanding and broaden problem-solving approaches. Challenges: students also reported risks of overreliance, reduced critical thinking, privacy concerns, possible copyright issues, and skill degradation. Although many said they limited ChatGPT’s contribution to around 30%, only a minority reported thoroughly checking AI-generated code line by line.", "swebokAreas": "Software Construction", "swebokSubAreas": "Coding; Debugging", "doiOrLink": "https://arxiv.org/pdf/2511.13996", "interaction": "Free Prompts", "analysis": "Qualitative", "usedByStudents": "Yes" },
"Evaluating GenAI’s Effectiveness for Students with Varied Programming Backgrounds in a Software Development Course": { "id": "ID70", "level": "A", "year": "2025", "source": "SIGCSE 2025: Proceedings of the 56th ACM Technical Symposium on Computer Science Education V. 2", "authors": "Larry Heimann, Shihong Huang", "educationalObjectives": "To examine whether GenAI tools help less technically prepared students succeed in a sophomore Application Design and Development course. The course objectives include user-centered design, software design processes, design patterns, testing, refactoring, and building a functional web application.", "aiEmployment": "GenAI tools were integrated into course labs and projects as student-facing support tools. Students used ChatGPT and GitHub Copilot during programming tasks and were required to report the tool used, filenames, prompts, and AI-generated code segments they accepted, distinguishing their own code from AI-assisted code.", "llm": "ChatGPT, GitHub Copilot", "metrics": "Pre-college technical background survey; self-rated programming proficiency; GenAI impact rating; project performance, exam scores, code quality, efficiency, and time to completion measured through GitHub commits and timing", "metricsUsage": "The study analyzed a semester-long course with 162 students across five parallel sessions on two continents. Students’ project and exam performance were compared with a prior-year control group without GenAI access. Preliminary findings showed that GenAI improved project scores by an average of 8.65 points and reduced grade variability by 5.95 points, but this improvement did not transfer to closed-book exams, especially for less technically prepared students.", "resources": "A sophomore-level Application Design and Development course with 13 labs, 7 project checkpoints, 4 project phases, and 3 closed-book exams. The final deliverable was a fully functional web application. The study also used a pre-college survey, GenAI usage records, and a control-group comparison.", "benefitsAndChallenges": "Benefits: GenAI tools helped students complete programming tasks and seemed to help less-prepared students temporarily close performance gaps in projects. Challenges: these gains did not extend to deeper learning or closed-book exams. Heavy reliance on AI may weaken critical thinking, transformative knowledge, and long-term understanding, and may even widen the gap between novice and stronger students.", "swebokAreas": "Software Construction", "swebokSubAreas": "Coding; Debugging", "doiOrLink": "https://dl.acm.org/doi/10.1145/3641555.3705175", "interaction": "Free Prompts", "analysis": "Quantitative", "usedByStudents": "Yes" },
"Fine-Tuned LLMs Versus Rule-Based NLP for UML Diagram Generation: An Educational Evaluation": { "id": "ID71", "level": "B", "year": "2025", "source": "IEEE Access, Volume 13, 2025", "authors": "Reshma P. Nair, M. G. Thushara, and Vijayan Sugumaran", "educationalObjectives": "To support students in learning UML modeling from natural language software requirements, especially the generation and interpretation of class diagrams and use case diagrams, including actors, classes, use cases, associations, inheritance, include/extend relationships, and semantic correctness of software models.", "aiEmployment": "The study compared a traditional rule-based NLP pipeline with fine-tuned LLMs for generating UML class and use case diagrams from textual requirements. The main LLM approach fine-tuned Qwen2.5-Coder-7B-Instruct using domain-specific prompts and PlantUML-based ground truth. The generated diagrams were evaluated against expert-annotated UML diagrams and used in an educational context to assess accuracy, usability, student effort, and engagement.", "llm": "Qwen2.5-Coder-7B-Instruct; Gemma2:9B; Mistral-Nemo:12B; Llama3:8B; CodeLlama:7B; DeepSeek-Coder:6.7B; GPT-4", "metrics": "Semantic fidelity, G-Eval correctness score, syntactic validity, completeness, structural similarity, manual correction effort, accuracy, precision, recall, expert validation, Cohen’s Kappa, MANOVA, ANOVA, Tukey post hoc tests, student usability feedback, cognitive effort, engagement.", "metricsUsage": "The metrics were used to compare UML diagrams generated by students, the NLP pipeline, and the fine-tuned LLM against ground-truth PlantUML diagrams. G-Eval assessed semantic and syntactic alignment; expert validation checked semantic coherence; statistical tests verified group differences; student feedback assessed usability, effort reduction, and engagement.", "resources": "A dataset of textual software requirements from industry and educational projects; 75 annotated specifications for evaluation; ground-truth UML class and use case diagrams in PlantUML; library and banking system case studies; NLP tools including NLTK, spaCy, Stanford NLP, and dependency parsing; Qwen2.5-Coder-7B-Instruct fine-tuning with LoRA; Python scripts; PlantUML; a learning interface for student usability feedback.", "benefitsAndChallenges": "Benefits: The LLM-generated diagrams showed higher semantic fidelity, better relationship modeling, reduced manual correction effort, improved student engagement, and lower perceived effort during modeling tasks. Challenges: The study reports hallucinations in about 5% of LLM outputs, computational demands for fine-tuning, limited generalizability due to the dataset’s industry focus, and the need for instructor validation to avoid over-reliance or incorrect interpretations.", "swebokAreas": "Software Engineering Models and Methods", "swebokSubAreas": "Software Design", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?arnumber=11271276", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
"GenScore: Agent-Based Short-Answer Question Generation and Scoring in Software Engineering Courses": { "id": "ID72", "level": "B", "year": "2025", "source": "IEEE Access, Volume 13, 2025", "authors": "Ta Nguyen Binh Duong and Lwin Khin Shar", "educationalObjectives": "To support assessment and practice in theory-oriented Software Engineering courses, especially topics such as software processes, DevOps, software design, security, testing, versioning, XP practices, automation, and project management. The objective is to help students practice short-answer questions across Bloom’s Taxonomy levels and receive immediate scoring and feedback.", "aiEmployment": "The study proposed GenScore, an agent-based LLM system for generating and scoring short-answer questions in Software Engineering courses. LLM agents generated questions and reference answers from lecture notes, refined questions, rated question quality, and scored student answers using few-shot examples and course-material context retrieved through file search.", "llm": "GPT-3.5-turbo; GPT-4o-mini", "metrics": "Human rating of generated questions, LLM rating of generated questions, validity, clarity, relevance, Bloom’s Taxonomy alignment, percentage of usable questions, percentage agreement, Pearson correlation coefficient, mean absolute error, root mean square error, percentage agreement between scoring agents, Krippendorff’s Alpha, token usage, and API cost.", "metricsUsage": "Question generation was evaluated by a human rater using validity, clarity, and relevance criteria for both questions and reference answers. LLM Rating Agents were compared with the human rater to assess whether generated questions were usable. Auto-scoring was evaluated by comparing LLM-predicted scores with human scores using Pearson’s r, MAE, and RMSE. Multi-agent scoring was additionally assessed with inter-rater reliability measures and cost analysis.", "resources": "Software Engineering lecture notes in PDF format, sample questions in Excel files, course topics and keywords, short-answer question banks, student answers, reference answers, the Mohler dataset, a Software Engineering dataset, a generated dataset, OpenAI Assistants API, file search, MongoDB, NextJS web interface, Wooclap export format, and GenScore web application.", "benefitsAndChallenges": "Benefits: The system can reduce instructor effort in creating and grading short-answer questions, support on-demand student practice, provide immediate scoring and feedback, generate mostly usable questions at lower and intermediate Bloom levels, and perform reasonably well without extensive model training or fine-tuning. Challenges: The system struggled more with higher Bloom levels such as Evaluate and Create, LLM Rating Agents were overly optimistic compared with the human rater, human review is still needed for high-stakes assessments, scoring consistency depends on examples and model choice, and multi-agent scoring increases cost.", "swebokAreas": "Software Engineering Process", "swebokSubAreas": "Software process models", "doiOrLink": "https://ieeexplore.ieee.org/stamp/stamp.jsp?tp=&arnumber=11311457", "interaction": "Fixed Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Generative AI in Student Software Development Projects: A User Study on Experiences and Self-Assessment": { "id": "ID73", "level": "A", "year": "2025", "source": "ECSEE 2025: Proceedings of the 6th European Conference on Software Engineering Education", "authors": "Uwe M. Borghoff, Mark Minas, and Jannis Schopp", "educationalObjectives": "To help students gain practical experience in a team-based software development project, including planning, requirements analysis, design, programming, testing, documentation, teamwork, and communication.", "aiEmployment": "Students were encouraged to use freely available generative AI tools during a programming project. They used AI across project phases for code comprehension, code generation, code improvement, debugging, documentation, requirements specification, use case generation, diagram generation, GUI mockups, design comparison, test generation, and image generation. The study collected students’ experiences and self-assessments through a structured questionnaire.", "llm": "ChatGPT; GitHub Copilot; Claude; Gemini; LLaMA", "metrics": "Structured questionnaire, AI adoption rate, phase-specific AI usage, perceived helpfulness, self-reported time savings, reported challenges, likelihood of future AI use, perceived overall usefulness, and open-ended qualitative responses.", "metricsUsage": "The questionnaire measured whether students used AI tools, which tools they used, which tasks they used them for, how helpful AI was in each project phase, how much time they believed AI saved, what challenges they encountered, whether they would use AI again, and whether they believed similar results could have been achieved without AI.", "resources": "A programming project course, student teams, multiplayer 3D game projects in Java, jMonkeyEngine, Battleship example project, requirements documents, class diagrams, use cases, acceptance test descriptions, user manuals, software specification documents, BPMN diagrams, sequence diagrams, state diagrams, test case tables, code bases, final game presentations, and a structured questionnaire.", "benefitsAndChallenges": "Benefits: Students perceived AI as useful for text-heavy and structured tasks, especially documentation, coding support, code comprehension, code improvement, debugging, test generation, and requirements-related writing. Many students reported time savings and a willingness to use AI again in future projects. Challenges: AI often produced inaccurate, incomplete, or non-integrable code; struggled with domain-specific frameworks such as jMonkeyEngine and Lemur; lacked sufficient project context; produced hallucinated methods or incorrect outputs; had difficulty generating useful diagrams; and required careful oversight and prompt formulation.", "swebokAreas": "Software Engineering Professional Practice", "swebokSubAreas": "Software Construction", "doiOrLink": "https://dl.acm.org/doi/10.1145/3723010.3723012", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Nurturing Code Quality: Leveraging Static Analysis and Large Language Models for Software Quality in Education": { "id": "ID74", "level": "A", "year": "2025", "source": "ACM Transactions on Computing Education, Volume 25, Issue 2", "authors": "Eman Abdullah AlOmar", "educationalObjectives": "To teach students software quality assurance practices through static analysis, code review, bug fixing, refactoring, and critical evaluation of LLM-generated recommendations for improving Java code quality.", "aiEmployment": "Students used ChatGPT together with the PMD static analysis tool. PMD identified code quality issues in Java open-source projects, and students used ChatGPT to understand the issues, decide whether they should be fixed, and propose or evaluate code changes. Students were also expected to critically assess ChatGPT’s recommendations rather than accept them as ground truth.", "llm": "ChatGPT 3.5", "metrics": "PMD ruleset categories, number of analyzed PMD issues, issue resolution time, students’ acceptance/rejection of PMD issues, ChatGPT success in fixing buggy code", "metricsUsage": "The study analyzed 155 student submissions and 1,658 PMD issues. PMD categories were used to identify which types of quality problems students selected. Resolution time was used to determine which categories took longer to fix. Student responses were analyzed quantitatively to measure ChatGPT’s perceived success, regressions, prompt usage, and additional issue detection. Open-ended responses and ChatGPT conversations were analyzed qualitatively using thematic analysis.", "resources": "Software Quality Assurance course materials, PMD static analysis tool, Java open-source projects, Eclipse/PMD plugin or standalone PMD, ChatGPT 3.5, online questionnaire, assignment instructions, PMD documentation, student reports, code snippets, and selected open-source projects such as Ant, GanttProject, Hutool, JCommander, JFreeChart, JHotDraw, Log4J, Nutch, Rhino, RxJava, and Xerces.", "benefitsAndChallenges": "Benefits: ChatGPT helped students understand PMD warnings, explain code quality problems, suggest bug fixes, automate parts of the code review process, support beginner learners, and stimulate critical thinking about static analysis warnings and LLM-generated fixes. Challenges: ChatGPT sometimes produced compilation errors, incomplete or repetitive fixes, code regressions, and suggestions based on limited code context. It struggled especially with broader design issues such as God Class refactoring because those require understanding the wider architecture and dependencies of the codebase.", "swebokAreas": "Software Quality", "swebokSubAreas": "code quality; code review; bug fixing", "doiOrLink": "https://doi.org/10.1145/3722229", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Outcomes, Perceptions, and Interaction Strategies of Novice Programmers Studying with ChatGPT": { "id": "ID75", "level": "A", "year": "2025", "source": "CUI ’25: Proceedings of the 7th ACM Conference on Conversational User Interfaces", "authors": "Jacob Penney, Pawan Acharya, Peter Hilbert, Priyanka Parekh, Anita Sarma, Igor Steinmacher, and Marco Aurelio Gerosa", "educationalObjectives": "To examine how novice programming students learn programming concepts, specifically pointers in C, when studying with ChatGPT compared with a human tutor. The study also aimed to understand students’ AI literacy, help-seeking behavior, prompt strategies, trust, and interaction patterns when using conversational agents for programming learning.", "aiEmployment": "Students in one group studied a programming concept using ChatGPT through a conversational interface. Their interactions were compared with another group that studied with a human tutor through Discord. The study analyzed learning outcomes, students’ perceptions of ChatGPT, and the strategies students used when asking questions to the AI tutor.", "llm": "ChatGPT 3.5", "metrics": "Pre-test and post-test quiz scores, learning gains, Likert-scale sentiment questionnaires, trust, ease of use, perceived usefulness, think-aloud protocols, tutor interaction logs, question types, response types, message length, response length, prompt strategies, debriefing interviews, paired t-test, Cohen’s d, Bayesian analysis, Wilcoxon signed-rank test, Mann-Whitney U test, FDR correction, and qualitative coding.", "metricsUsage": "Quiz scores were used to compare learning outcomes before and after studying with ChatGPT or a human tutor. Questionnaires measured changes in trust, usefulness, and ease of use. Interaction logs were coded to analyze the types of questions students asked, how they formulated prompts, whether they refined their questions, and how tutor responses differed. Think-aloud and debriefing data were analyzed qualitatively to understand students’ perceptions, trust, anxiety, and learning strategies.", "resources": "Introductory programming course content, a programming concept about C pointers, pre- and post-study quizzes, ChatGPT/GPT-3.5, Discord human tutoring, Zoom study sessions, sentiment questionnaires, think-aloud protocols, debriefing interviews, conversational transcripts, and coding taxonomies for analyzing student questions and tutor responses.", "benefitsAndChallenges": "Benefits: Students felt more comfortable asking ChatGPT basic or “silly” questions because it reduced fear of judgment and social anxiety. ChatGPT provided fast, lengthy, and context-rich explanations, which some students found useful for foundational programming questions. Challenges: Students distrusted ChatGPT’s accuracy, often felt the need to verify its answers externally, rarely refined their prompts, and generally treated ChatGPT’s responses as fixed rather than adjustable. ChatGPT responses were sometimes perceived as too verbose, insufficiently pedagogical, or less reliable for learning new concepts.", "swebokAreas": "Software Construction", "swebokSubAreas": "Programming fundamentals", "doiOrLink": "https://doi.org/10.1145/3719160.3736625", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Simulating Requirement Elicitation: Development and Evaluation of a Persona-Based Tool": { "id": "ID76", "level": "A", "year": "2025", "source": "SIGCSE TS 2025: Proceedings of the 56th ACM Technical Symposium on Computer Science Education V. 2", "authors": "Ildar Akhmetov and Mirjana Prpa", "educationalObjectives": "To help students practice requirements elicitation by interviewing simulated stakeholders, clarifying ambiguities, identifying user needs, and synthesizing requirements into conceptual models and Entity-Relationship diagrams.", "aiEmployment": "The study developed a Requirement Elicitation Tool using LLM-based synthetic personas. Students interacted with three AI personas representing different stakeholders in a ticketing company project. The personas responded conversationally based on predefined user stories but did not reveal the stories, tables, columns, or direct database solutions.", "llm": "ChatGPT-4o-mini", "metrics": "Number of student-persona messages, number of messages per team, number of messages per persona, quality of produced ER diagrams, and preliminary observations of student engagement.", "metricsUsage": "The authors tracked student interactions with the personas during a two-week requirements elicitation sprint. They counted total messages, messages by team, and messages by persona. They also assessed whether teams produced ER diagrams that captured essential entities, attributes, and relationships.", "resources": "Requirement Elicitation Tool, three synthetic personas, predefined user stories, a semester-long Database Management Systems project, ticketing company scenario, conceptual modeling activity, ER diagram assignment, Streamlit, LangChain, Render deployment, OpenAI Assistants, and gpt-4o-mini.", "benefitsAndChallenges": "Benefits: The tool encouraged students to engage in discovery, ask probing questions, synthesize information from multiple stakeholder perspectives, and avoid simply copying predefined requirements into AI tools. All teams produced high-quality ER diagrams. Challenges: The findings are preliminary; the study does not yet report detailed student interview data or deeper evaluation of student experience. Message distribution varied substantially between teams and personas.", "swebokAreas": "Software Requirements", "swebokSubAreas": "Requirements elicitation", "doiOrLink": "https://doi.org/10.1145/3641555.3705250", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Student Engagement with GenAI’s Tutoring Feedback: A Mixed Methods Study": { "id": "ID77", "level": "C", "year": "2025", "source": "Koli Calling ’25: Proceedings of the 25th Koli Calling International Conference on Computing Education Research", "authors": "Sven Jacobs, Jan Haas, and Natalie Kiesler", "educationalObjectives": "To support introductory programming students in solving Python programming tasks, understanding programming mistakes, applying concepts, interpreting feedback, and improving their code through immediate GenAI-generated tutoring feedback.", "aiEmployment": "The study used an online learning environment, Tutor Kai, that generated four types of AI tutoring feedback for students’ Python code: Find Problems, Explanations and Examples, Next Step Hint, and Strategic Approach. Students could request and open feedback components while solving programming tasks.", "llm": "ChatGPT-4.1", "metrics": "Think-aloud verbalizations, eye-tracking data, screen recordings, feedback requests, feedback components collected, feedback components read or ignored, students’ immediate actions, code improvements, setbacks, no-action cases, questionnaire responses, perceived task difficulty, and inter-coder reliability.", "metricsUsage": "Think-aloud data were coded to identify students’ thoughts while reading feedback. Eye-tracking was used to determine whether students visually attended to feedback components. Screen recordings and logs were used to connect feedback engagement with actions such as code changes, collecting another feedback component, or taking no action. The study analyzed how different thoughts related to improvements, setbacks, and feedback-seeking behavior.", "resources": "Tutor Kai online learning environment, Python programming tasks, code editor, compiler output, unit tests, GenAI-generated feedback components, lecture transcripts, video lecture links, corrected code versions, task descriptions, student code, RAG-based lecture retrieval, think-aloud protocol, Tobii Glasses 3 eye-tracking, screen recordings, MAXQDA, and questionnaires.", "benefitsAndChallenges": "Benefits: Students often understood or agreed with the feedback, and many GenAI feedback requests led to code improvements. The next-step hint component was especially associated with improvements. The self-directed selection of feedback components allowed students to choose the type and amount of support they needed. Challenges: Students sometimes needed more specific information, disagreed with feedback, found some feedback irrelevant or already known, or did not know where to apply suggested changes. The fixed feedback components did not allow students to steer the feedback focus or ask conversational follow-up questions.", "swebokAreas": "Software Construction", "swebokSubAreas": "Programming fundamentals", "doiOrLink": "https://doi.org/10.1145/3769994.3770034", "interaction": "Fixed Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Students’ Perception of ChatGPT in Software Engineering: Lessons Learned from Five Courses": { "id": "ID78", "level": "A", "year": "2025", "source": "2025 IEEE/ACM 37th International Conference on Software Engineering Education and Training (CSEE&T)", "authors": "Luciano Baresi, Andrea De Lucia, Antinisca Di Marco, Massimiliano Di Penta, Davide Di Ruscio, Leonardo Mariani, Daniela Micucci, Fabio Palomba, Maria Teresa Rossi, and Fiorella Zampetti", "educationalObjectives": "To investigate how students use LLM-based tools in Software Engineering courses and projects, including requirements engineering, modeling, architecture, documentation, coding, testing, debugging/fault localization, and code review. The study also aimed to understand students’ perceived usefulness, interaction challenges, and adaptation effort when applying LLM outputs to their own projects.", "aiEmployment": "Students were trained on the use of LLMs for software development tasks and on prompting strategies, including role prompting, contextualization, few-shot learning, and chain-of-thought. They then used LLM-based tools, mainly ChatGPT, during course projects across five Software Engineering courses. Their experiences were collected through questionnaires and, in two courses, semi-structured interviews.", "llm": "GitHub Copilot, Gemini and ChatGPT", "metrics": "Survey questionnaires, Likert-scale ratings, LLM usage frequency by task, perceived usefulness, interaction effort, adaptation effort, open-ended answers, semi-structured interviews, open coding of qualitative responses, and comparison across Bachelor’s and Master", "metricsUsage": "The survey measured how often students used LLMs for different SE tasks, how useful they perceived LLMs to be, how difficult it was to interact with them, and how much effort was required to adapt LLM outputs to project contexts. Open-ended answers and interviews were coded to identify reasons for usefulness, interaction difficulties, adaptation challenges, and desired tool improvements.", "resources": "Five Software Engineering courses from four universities, course projects, LLM training sessions, prompt engineering examples, survey questionnaires, Google Forms, semi-structured interview guides, student project artifacts, software development tasks covering requirements, modeling, architecture, documentation, coding, testing, debugging, and code review.", "benefitsAndChallenges": "Benefits: Students perceived LLMs as useful for repetitive and code-related tasks such as code generation, debugging, testing support, documentation, and code review. They also used LLMs as learning resources, replacing or complementing Stack Overflow, documentation, and code searches. Challenges: LLMs were perceived as less useful for requirements, modeling, and architecture tasks because these require broader project context and domain understanding. Students also reported difficulty crafting task-specific prompts, steering conversations after wrong answers, evaluating generated solutions, adapting outputs to project constraints, and dealing with outdated or framework-specific code.", "swebokAreas": "Software Engineering Professional Practice", "swebokSubAreas": "Use of software engineering tools", "doiOrLink": "https://ieeexplore.ieee.org/document/11024336", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Uncovering Behavioral Patterns in Student–LLM Conversations during Code Refactoring Tasks": { "id": "ID79", "level": "A", "year": "2025", "source": "Koli Calling ’25: Proceedings of the 25th Koli Calling International Conference on Computing Education Research", "authors": "Eduardo Carneiro Oliveira, Hieke Keuning, and Johan Jeuring", "educationalObjectives": "To understand how students interact with LLMs while performing code refactoring tasks, and how these interaction behaviors relate to prompt quality, LLM response quality, and the quality of students’ refactored code.", "aiEmployment": "Students individually worked on three C# code refactoring exercises and were allowed to use ChatGPT 3.5 in any way to assist them. The study analyzed student–LLM conversations to identify behavioral patterns, evaluate prompt usefulness and response quality, and relate these behaviors to the quality of submitted refactored code.", "llm": "ChatGPT 3.5", "metrics": "Student–LLM conversation logs, student prompts, LLM responses, prompt type, prompt follow-up type, prompt usefulness, response quality, interaction topic, interaction format, number of interactions, whether students attempted refactoring before using the LLM, whether students copied LLM-generated code, student solution quality scores, survey responses, and intercoder reliability.", "metricsUsage": "The authors qualitatively coded 41 student–LLM conversations and 318 interactions to identify interaction patterns. Prompt usefulness and LLM response quality were analyzed across patterns. Student submissions were scored from 1 to 5 according to code quality improvement, and these scores were compared with the identified behavioral patterns.", "resources": "Three C# refactoring exercises, JDoodle online code editor, ChatGPT 3.5, student conversation links, student code submissions, survey responses, coding book for interaction analysis, and exercises involving code duplication, lack of abstraction, low cohesion, public fields, large class, lack of encapsulation, primitive obsession, and magic numbers.", "benefitsAndChallenges": "Benefits: Students who first attempted refactoring themselves and then used the LLM for specific questions tended to produce higher-quality solutions. The LLM could assist with refactoring suggestions, explanations, and targeted questions when students provided a clear direction. Challenges: Many students delegated the entire refactoring task to the LLM. The LLM often followed student requests uncritically, even when prompts contained misconceptions or unsuitable design-pattern choices. Unguided LLM use was not recommended for inexperienced students, especially because misleading responses and poor prompts could reinforce misunderstandings.", "swebokAreas": "Software Construction", "swebokSubAreas": "Code refactoring; code quality improvement", "doiOrLink": "https://doi.org/10.1145/3769994.3770000", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Person is a person, a tool is a tool - ChatGPT’s Role in Student Help-Seeking Behavior and Peer Support": { "id": "ID80", "level": "A", "year": "2025", "source": "FSE Companion ’25: Proceedings of the 33rd ACM International Conference on the Foundations of Software Engineering", "authors": "Sonja M. Hyrynsalmi, Micheal Tuape, and Antti Knutas", "educationalObjectives": "To understand how first-year software engineering students seek help when facing learning challenges, and how GenAI tools affect peer support, social interaction, and help-seeking behavior in software engineering education.", "aiEmployment": "The study did not implement a controlled AI-based learning intervention. Instead, it surveyed students about their use of ChatGPT or other AI tools as sources of help during software engineering studies and course exercises, comparing AI-based help-seeking with help from peers, teaching assistants, and teachers.", "llm": "ChatGPT", "metrics": "Online survey responses, help-seeking preference percentages, perceived amount of help from different sources, Likert-scale responses about social interaction and ChatGPT use, and thematic analysis of open-ended responses.", "metricsUsage": "Closed-ended survey questions were analyzed with descriptive statistics to identify students’ preferred help-seeking sources and perceptions of peer interaction. Open-ended responses were analyzed thematically to understand whether students felt ChatGPT replaced, complemented, or reduced the need for peer interaction.", "resources": "First-year software engineering bachelor’s introductory course, online questionnaire, course exercises, questions about help-seeking sources, questions about ChatGPT use, Likert-scale statements about social interaction and learning support, and open-ended questions about AI and peer support.", "benefitsAndChallenges": "Benefits: Students valued ChatGPT for speed, accessibility, ease of use, and quick answers to basic questions. Many saw AI tools as useful complements to peer interaction and as a way to make learning more efficient. Challenges: ChatGPT may reduce students’ need to discuss learning-related questions with peers, potentially weakening peer support and social interaction. Students also recognized limitations such as hallucinations, lack of new ideas, and the need for human interaction for more complex problems and critical thinking.", "swebokAreas": "Software Engineering Professional Practice", "swebokSubAreas": "professional and social skills", "doiOrLink": "https://doi.org/10.1145/3696630.3727235", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Unlocking Potential with Generative AI Instruction: Investigating Mid-level Software Development Student Perceptions, Behavior, and Adoption": { "id": "ID81", "level": "A", "year": "2025", "source": "SIGCSE TS 2025: Proceedings of the 56th ACM Technical Symposium on Computer Science Education V. 1", "authors": "Jamie Gorson Benario, Jenn Marroquin, Monica M. Chan, Ernest D. V. Holmes, and Daniel Mejia", "educationalObjectives": "To teach mid-level software development students how to use generative AI tools safely, responsibly, and productively in software development tasks, including learning concepts, explaining code, fixing bugs, writing code, testing, and working with professional development tools and workflows.", "aiEmployment": "The course incorporated formal instruction on generative AI tools, including their capabilities, limitations, ethical implications, prompt engineering, and use in software development workflows. Students used generative AI tools during the semester for learning concepts, explaining code, fixing errors, generating examples, modifying code, writing tests, writing code, and supporting project work.", "llm": "ChatGPT; Duet AI; GitHub Copilot", "metrics": "Pre-survey, post-survey, six unit surveys, self-reported prior use of generative AI, frequency of generative AI use by task, student behavior ratings, Likert-scale responses, paired two-tailed t-tests, open-ended survey responses, perceived helpfulness for learning programming", "metricsUsage": "The surveys measured students’ prior use of generative AI, how they used the tools during the course, changes in behaviors before and after instruction, and perceptions of learning outcomes. Likert-scale responses were summarized quantitatively, paired t-tests compared pre- and post-course behaviors, and open-ended responses were coded to identify common uses and perceptions.", "resources": "Software Development Studio course, Google-led lectures, live demonstrations, project coaches, Cloud Console, Cloudshell, Streamlit, Figma, generative AI APIs, prompt engineering instruction, priming techniques, course projects, unit surveys, pre/post surveys, and industry-oriented software development tools and workflows.", "benefitsAndChallenges": "Benefits: Students reported that generative AI tools helped them learn new concepts, explain code, fix bugs, understand syntax, debug, write code more efficiently, and explore different problem-solving approaches. After instruction, students reported greater engagement with AI outputs, including reading, testing, and understanding generated code. Challenges: The study notes concerns about over-reliance, hallucinations, unequal access to training, and the need for students to critically evaluate and test AI-generated outputs. Some students still needed to debug, adjust, or reprompt generated code to make it accurate and useful.", "swebokAreas": "Software Engineering Professional Practice", "swebokSubAreas": "software engineering tools", "doiOrLink": "https://dl.acm.org/doi/pdf/10.1145/3641554.3701859", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"An Evaluation of Prompt Engineering Strategies by College Students in Competitive Programming Tasks": { "id": "ID82", "level": "A", "year": "2025", "source": "", "authors": "Sita V. Gunturi, Jeremy J. Blum, and Tyler S. Love", "educationalObjectives": "To evaluate how undergraduate computer science students use prompt engineering strategies when applying generative AI tools to competitive programming tasks, with emphasis on improving AI-assisted problem solving, code generation, debugging, and solution refinement.", "aiEmployment": "Student teams used generative AI tools during a two-hour competitive programming contest. They interacted with tools such as ChatGPT, GitHub Copilot, and Claude to solve programming problems, generate code, refine outputs, handle test cases, and improve solutions. The researchers analyzed submitted AI interaction transcripts to identify prompt engineering practices.", "llm": "ChatGPT; GitHub Copilot; Claude", "metrics": "Submitted LLM interaction transcripts, directed content analysis, 14 prompt engineering best practices, six prompt engineering strategies, descriptive statistics, adherence/compliance rate to best practices, percentage of teams using each practice, and problem success rates.", "metricsUsage": "The researchers qualitatively analyzed 60 submitted transcripts to identify whether teams applied specific prompt engineering best practices. These qualitative observations were then converted into descriptive statistics to calculate how frequently each practice was used and to assess students’ overall adherence to prompt engineering strategies.", "resources": "Competitive programming contest, 12 programming problems, teams of three undergraduate students, generative AI tools, LLM conversation transcripts, sample test cases, problem statements, constraints, additional test cases, HackerRank problem repository, and a framework of prompt engineering strategies and best practices.", "benefitsAndChallenges": "Benefits: Generative AI tools could help students solve simpler problems, generate code components, handle input/output routines, suggest solution approaches, and refine solutions through iterative prompting. Challenges: Students showed limited use of advanced prompt engineering strategies. Chain-of-thought prompting, persona prompting, task-step specification, and meta-prompting were absent from the analyzed transcripts. The average compliance rate across best practices was only 34.2%, showing a need for structured prompt engineering instruction.", "swebokAreas": "Software Construction", "swebokSubAreas": "code generation", "doiOrLink": "https://peer.asee.org/an-evaluation-of-prompt-engineering-strategies-by-college-students-in-competitive-programming-tasks", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Impact of Developer Queries on the Effectiveness of Conversational Large Language Models in Programming": { "id": "ID83", "level": "A", "year": "2025", "source": "", "authors": "Viktor Taneski, Sašo Karakatič, Patrik Rek, and Gregor Jošt", "educationalObjectives": "To examine how students use LLM-based assistance while learning frontend web application development with React and TypeScript, especially for implementing features, fixing errors, understanding code, and formulating effective programming queries.", "aiEmployment": "Students used LLMs during React programming assignments and, in one controlled exam, were required to rely only on LLMs to generate and refine their code. The researchers collected students’ LLM chat histories and categorized their prompts into seven query types: Error Fixing, Feature Implementation, Code Optimization, Code Understanding, Best Practices, Documentation, and Concept Clarification.", "llm": "ChatGPT", "metrics": "Runnable code, assignment/exam grades, grade differences between no-LLM and LLM-only exams, query type categories, tagged versus untagged queries, component hierarchy diagrams, cyclomatic complexity, prior assignment scores, Cohen’s kappa, Shapiro–Wilk test, Mann–Whitney U test, Pearson correlation, p-values, and average ranks.", "metricsUsage": "The authors compared student performance in a no-LLM exam and an LLM-only exam to isolate the impact of LLM assistance. Student prompts were manually tagged by query type, and statistical tests were used to determine whether specific query types were associated with runnable code and better performance. Prior scores were used to control for baseline coding ability.", "resources": "Web development course, React, TypeScript, HTML5, CSS3, JavaScript ES6, four React programming assignments, two controlled exams, official React documentation, Google search, LLM chat histories, task specifications, grading criteria for functionality and correctness, component hierarchy diagrams, and SonarQube Cloud for cyclomatic complexity.", "benefitsAndChallenges": "Benefits: LLMs were especially useful for error fixing and code understanding. Students who asked debugging or comprehension-oriented questions were more likely to produce runnable code and maintain performance on a more complex LLM-only task. Challenges: LLM assistance was less clearly beneficial for feature implementation, code optimization, best practices, documentation, and concept clarification. The study emphasizes that effective benefits depend on query clarity, prompt formulation, and students’ ability to ask precise questions.", "swebokAreas": "Software Construction", "swebokSubAreas": "Coding; debugging and error fixing", "doiOrLink": "https://www.mdpi.com/2076-3417/15/12/6836", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Engineered Prompts in ChatGPT for Educational Assessment in Software Engineering and Computer Science": { "id": "ID84", "level": "C", "year": "2025", "source": "", "authors": "Ayman Diyab, Russell Morris Frost, Benjamin David Fedoruk, and Ahmad Diyab", "educationalObjectives": "To support educational assessment in Software Engineering and Computer Science courses by grading student responses, identifying knowledge gaps, providing feedback, and generating practice questions aligned with course topics and learning outcomes.", "aiEmployment": "The study proposed AI Assess, a ChatGPT-based assessment system composed of four prompt-engineered components: automated grading, weakness identification, feedback provision, and question generation. The prompts were iteratively refined and converted into LMQL implementations to structure inputs, outputs, and validation constraints.", "llm": "ChatGPT", "metrics": "Instructor grades, ChatGPT-generated grades, scatter plots comparing human and AI grading, zero-shot and few-shot prompt performance, correctness of weakness identification, quality of generated feedback, quality of generated assessment questions, and examples of generated outputs.", "metricsUsage": "The authors compared ChatGPT’s automated grades with instructor grades, first without sample grading and then with sample human grading. They also evaluated whether ChatGPT could correctly identify common student weaknesses, provide useful feedback on student answers, and generate assessment questions from syllabus and topic information.", "resources": "Software Engineering and Computer Science exam questions, student answers, instructor grades, syllabus information, course descriptions, topic lists, learning outcomes, prompt templates, LMQL programs, automated grading examples, weakness identification examples, feedback examples, and question generation examples.", "benefitsAndChallenges": "Benefits: The system can reduce instructor workload, support grading of constructed-response questions, identify common weaknesses in a student cohort, generate practice questions, and provide near-instant feedback to students. Challenges: The system requires human-in-the-loop supervision, careful prompt engineering, validation of generated grades and feedback, and instructor review to avoid incorrect or incomplete outputs. Some generated questions may contain conceptual inaccuracies unless the topic overview is sufficiently detailed.", "swebokAreas": "Software Engineering Professional Practice", "swebokSubAreas": "", "doiOrLink": "https://doi.org/10.3390/educsci15020156", "interaction": "Used by Professors", "analysis": "Mixed", "usedByStudents": "No" },
"Exploring the Impact of LLM Prompting on Students’ Learning": { "id": "ID85", "level": "A", "year": "2025", "source": "", "authors": "Murimo Bethel Mutanga, Jotham Msane, Thaddeus Ndumiso Mndaweni, Bongokuhle Brightman Hlongwane, and Neliswa Ziyanda Ngcobo", "educationalObjectives": "To examine how IT/software development students use LLM prompting strategies while completing programming tasks, and how these strategies support or limit programming learning, problem solving, debugging, conceptual understanding, and independent coding skills.", "aiEmployment": "Students used their own LLM accounts during laboratory programming tasks. They interacted with ChatGPT, Gemini, or Claude to request explanations, step-by-step guidance, code generation, debugging help, and reflective explanations. The researchers analyzed students’ prompts and immediate LLM responses to identify dominant prompting strategies and their learning implications.", "llm": "ChatGPT; Gemini; Claude", "metrics": "842 student prompts, 140 student participants, prompt frequency, prompt length, LLM used, five prompting strategy categories, thematic coding, descriptive statistics, Cohen’s kappa, Bloom’s Taxonomy, constructivist learning interpretation, and qualitative analysis of prompt purpose and cognitive demand.", "metricsUsage": "The researchers cleaned and coded the prompt dataset, then categorized prompts according to their purpose and cognitive complexity. Descriptive statistics were used to report the prevalence of each prompting strategy, while qualitative coding and theoretical interpretation were used to assess how each strategy reflected different levels of learning engagement.", "resources": "Diploma in Software Development programme, four core software development modules, laboratory programming tasks, students’ personal ChatGPT/Gemini/Claude accounts, LLM prompt and response histories, CSV exports, Python script for data cleaning, and programming tasks related to databases, C#, SQL, Python, machine learning concepts, and software development tools.", "benefitsAndChallenges": "Benefits: Step-by-step guidance, debugging, and reflective prompts supported more structured learning, problem decomposition, conceptual clarification, and active engagement with programming tasks. LLMs helped students obtain explanations, examples, and timely assistance. Challenges: Most prompts were direct instruction prompts, often limited to lower-order thinking such as remembering and understanding. Code-centric prompts risked passive learning because students sometimes requested ready-made code without reflection. Reflective and debugging prompts were rare, suggesting limited higher-order engagement and possible over-reliance on LLM-generated answers.", "swebokAreas": "Software Construction", "swebokSubAreas": "", "doiOrLink": "https://doi.org/10.3390/higheredu4030031", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Human-AI Collaboration in Coding: A Trust Perspective": { "id": "ID86", "level": "C", "year": "2025", "source": "Electronic Communications of the EASST, Volume 84; 12th International Symposium on Leveraging Applications of Formal Methods, Verification and Validation / 2nd AISoLA Doctoral Symposium", "authors": "Sonja Niemann and Ute Schmid", "educationalObjectives": "To discuss how trust, distrust, overtrust, and calibrated trust affect the use of GenAI in coding, Computer Science education, and software development, especially when students or developers rely on AI-generated code.", "aiEmployment": "The paper does not report a direct educational intervention or experiment with students using AI. It is a conceptual and interdisciplinary discussion of trust in GenAI for code generation and human-AI collaboration, drawing from computer science, psychology, philosophy, and trust-in-automation research.", "llm": "ChatGPT and Llama", "metrics": "Trust frameworks, trustworthiness requirements, calibrated trust, overtrust, distrust, trust-in-automation dimensions, General Attitudes towards Artificial Intelligence Scale, Trust in Automation questionnaire, propensity-to-trust questionnaires, and behavioral trust measurement proposals.", "metricsUsage": "The paper reviews existing trust definitions and measurement approaches to discuss whether and how they can be adapted to GenAI and code generation contexts. It argues that questionnaires offer partial evidence, but behavioral measures of trust in GenAI are still needed.", "resources": "No teaching intervention materials were used. The paper discusses literature on GenAI in CS education, code generation, trust in automation, trustworthy AI guidelines, philosophical definitions of trust, and possible trust measurement instruments.", "benefitsAndChallenges": "Benefits: Calibrated trust can help students and developers use GenAI more appropriately, avoiding both unnecessary rejection and blind reliance. Trust frameworks may support future research on sustainable GenAI use in programming education. Challenges: GenAI can be perceived as human-like, which may encourage overtrust. Students may rely on generated code without checking correctness, potentially weakening critical thinking. Existing trust measures are not fully adapted to GenAI coding contexts.", "swebokAreas": "", "swebokSubAreas": "", "doiOrLink": "https://eceasst.org/index.php/eceasst/article/view/2679", "interaction": "Used by Professors", "analysis": "Qualitative", "usedByStudents": "No" },
"A friend or a foe? Evaluating ChatGPT’s Impact on Students’ Computational Thinking Skills": { "id": "ID87", "level": "A", "year": "2025", "source": "EASE Companion ’25: Proceedings of the 2025 29th International Conference on Evaluation and Assessment in Software Engineering Companion", "authors": "May Mahmoud, Eric Asare, Nourhan Sakr, and Sarah Nadi", "educationalObjectives": "To investigate whether ChatGPT support affects students’ learning and retention of computational thinking skills in object-oriented design tasks, especially decomposition and abstraction into classes, attributes, and methods.", "aiEmployment": "Students in the experimental group had access to ChatGPT during the learning phase while solving object-oriented design and programming tasks. ChatGPT was available in a split-screen setup, and students could use it to ask for solutions, modifications, corrections, clarifications, and explanations. The control group used traditional resources only.", "llm": "ChatGPT", "metrics": "Task completion time, solution correctness, retention test score, MCQ quiz answers, post-study questionnaire, confidence in solutions, perceived task complexity, confidence in future skill use, screen recordings, ChatGPT interaction logs, and prompting pattern categories.", "metricsUsage": "The study compared the ChatGPT-assisted group and the control group in terms of time, correctness, confidence, perceived complexity, and retention. The authors also analyzed ChatGPT logs and screen recordings to identify prompting patterns, such as direct solution requests, modification requests, code correction, problem statement clarification, and explanatory inquiry.", "resources": "Brief lecture on decomposition and abstraction, educational videos on abstraction and Python classes, Google Colab notebooks, object-oriented design tasks, Python class implementation tasks, university student information system task, event management system retention task, MCQ quiz, post-session questionnaire, screen recordings, and ChatGPT logs.", "benefitsAndChallenges": "Benefits: Preliminary results suggest that students with ChatGPT access completed tasks faster and performed better during the learning phase. They also reported higher confidence in their solutions and perceived the tasks as less complex. Challenges: The ChatGPT-assisted group performed slightly worse in the testing phase and reported lower confidence in applying the skills in future tasks. The most common prompt pattern was direct solution seeking, which may indicate risk of over-reliance and weaker retention of abstraction and decomposition skills.", "swebokAreas": "Software Construction", "swebokSubAreas": "", "doiOrLink": "https://doi.org/10.1145/3727967.3756830", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"AI-Driven Dynamic Competency Graph Model for Bridging Industry-Academia Gaps in Software Engineering Education": { "id": "ID88", "level": "B", "year": "2025", "source": "ISAIE 2025: Proceedings of the 2025 2nd International Symposium on Artificial Intelligence for Education", "authors": "Guangxi Peng and Aihua Yang", "educationalObjectives": "To align Software Engineering education with evolving industry needs by dynamically mapping emerging technologies to student competencies, improving employability, technical readiness, adaptability, and mastery of new software frameworks.", "aiEmployment": "The study proposed the Dynamic Competency Graph Model, which integrates real-time technology monitoring, competency mapping, generative AI-driven personalized learning, and continuous evaluation. Generative AI tools were used to create adaptive coding exercises, context-aware feedback, tutorials, and project-based learning resources aligned with emerging industry technologies.", "llm": "Gemini and Cursor", "metrics": "Employment rate, average salary, median time-to-mastery for new frameworks, course completion rate, learning satisfaction, employer feedback, technical readiness, adaptability, ACM-ICPC standardized evaluation scale, GitHub activity index, programming pre-test, novelty score, code complexity index, t-tests, chi-square test, Mann–Whitney U test, and regression analysis.", "metricsUsage": "The authors conducted a three-blind randomized controlled trial with 240 students divided into a DCGM-based curriculum group and a traditional curriculum group. The metrics were used to compare employability, learning efficiency, student satisfaction, competency development, and innovation outcomes between the experimental and control groups.", "resources": "DCGM platform, Dynamic Tech Radar, Competency Graph, Generative AI Integration module, Measurement Matrix, GitHub repositories, PyPI package updates, technical reports, AWS Lambda data pipeline, Gemini, Cursor, adaptive coding exercises, tutorials, project-based learning resources, ACM-ICPC standardized evaluation scale, employer surveys, GitHub activity index, PAT programming pre-test, Power BI dashboards, and cloud-native AWS infrastructure.", "benefitsAndChallenges": "Benefits: DCGM improved curriculum-industry alignment, employability, salary outcomes, employment rate, time-to-mastery, course completion, satisfaction, technical readiness, and adaptability. Moderate AI use supported creativity and reduced cognitive load. Challenges: Excessive AI use led to over-reliance, reduced originality, and lower code quality. The study also notes implementation costs, limited generalizability due to the trial being conducted in three universities in one country, and the need for long-term career tracking and qualitative user experience analysis.", "swebokAreas": "Software Engineering Professional Practice", "swebokSubAreas": "", "doiOrLink": "https://doi.org/10.1145/3775073.3775102", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
"Encouraging responsible GenAI use in software engineering education: A design-oriented model": { "id": "ID89", "level": "B", "year": "2026", "source": "The Journal of Systems & Software, Volume 237", "authors": "Vəhid Gəruslu, Zafar Jafarov, Aytan Movsümova, Atif Namazov, and Hüseyn Mirzayev", "educationalObjectives": "To support responsible GenAI use in Software Engineering Education, especially by developing students’ AI literacy, critical thinking, validation of AI-generated software artifacts, responsible use of GenAI in coursework, and ability to verify AI-generated code, tests, bug reports, and SE documentation.", "aiEmployment": "The study proposed Guide-AI-Ed, a design-oriented conceptual model to help instructors design GenAI-aware Software Engineering courses and curricula. The model was applied in two contexts: redesigning a final-year Software Testing course and embedding GenAI-related competencies into a new Software Engineering BSc curriculum. Students were encouraged to use GenAI tools, but with declarations, reflection, validation tasks, and critique of AI-generated artifacts.", "llm": "ChatGPT, GitHub Copilot, Google Gemini", "metrics": "Design-based research evidence, instructor observations, student artifacts, GenAI usage declarations, AI-output validation tasks, peer-review of AI artifacts, lab report reflections, raw GenAI outputs, revised student outputs, curriculum mapping, program-level outcomes, course-level learning outcomes, and rubric alignment.", "metricsUsage": "The authors used the Guide-AI-Ed model to redesign course and curriculum elements, then examined instructor observations and student artifacts to assess whether students engaged more critically with GenAI outputs. At the curriculum level, they mapped GenAI-related program outcomes to courses, assessments, and rubric elements.", "resources": "Guide-AI-Ed model, final-year Software Testing course CSC3056 at Queen’s University Belfast, four software testing lab assignments, lab report templates, GenAI usage declaration sections, AI-output validation checklists, peer-review tasks, bug reports, exploratory test plans, JUnit test cases, API testing tasks, GitHub submissions, Zoho BugTracker, QUB GenAI usage policy, and Software Engineering BSc curriculum design materials at Azerbaijan Technical University.", "benefitsAndChallenges": "Benefits: The model helped instructors redesign SE coursework to promote responsible GenAI use, critical reflection, validation of AI-generated artifacts, academic integrity, and AI literacy. Course-level observations suggested increased critical engagement with GenAI, reduced passive reliance, and improved awareness of validation practices. Challenges: The study warns that students may use GenAI as a shortcut, rely on unverified outputs, bypass deep learning, and submit AI-generated code, tests, or reports without understanding them. The model is conceptual and design-oriented, so the reported effects are illustrative rather than statistically validated.", "swebokAreas": "Software Engineering Professional Practice", "swebokSubAreas": "software engineering tools", "doiOrLink": "https://doi.org/10.1016/j.jss.2026.112846", "interaction": "Hybrid", "analysis": "Qualitative", "usedByStudents": "Yes" },
"Enhancing Accessibility in Software Engineering Projects with Large Language Models (LLMs)": { "id": "ID90", "level": "A", "year": "2025", "source": "SIGCSE TS 2025: Proceedings of the 56th ACM Technical Symposium on Computer Science Education V. 1", "authors": "Wajdi Aljedaani, Marcelo Medeiros Eler, and P D Parthasarathy", "educationalObjectives": "To improve software engineering students’ awareness, knowledge, and practical skills in digital accessibility, especially by identifying, understanding, and fixing accessibility violations in web development projects.", "aiEmployment": "Students first evaluated their own websites using accessibility checker tools, then used ChatGPT 3.5 to help fix the accessibility violations identified by the tools. After applying the suggested fixes, they evaluated the websites again to check whether the accessibility issues had been resolved.", "llm": "ChatGPT 3.5", "metrics": "Number of accessibility violations before and after remediation, WCAG Success Criteria, AChecker results, WAVE results, percentage of bugs fixed, post-survey responses, participants’ prompt strategies, number of ChatGPT iterations, time spent fixing issues, perceived usefulness of ChatGPT, accessibility awareness, confidence, attitude toward future accessibility practices, and satisfaction with the assignment.", "metricsUsage": "The authors compared accessibility violations detected before and after students used ChatGPT to fix issues. Survey responses were analyzed with descriptive statistics, and open-ended responses were analyzed using open coding to understand students’ perceptions, strategies, and learning experience.", "resources": "Software engineering course websites developed by students, accessibility improvement assignment, WAVE, AChecker, WCAG 2.0 Success Criteria, ChatGPT 3.5, students’ source code, accessibility violation reports, post-survey, and students’ prompt strategies for accessibility remediation.", "benefitsAndChallenges": "Benefits: The assignment improved students’ accessibility awareness, confidence, and willingness to integrate accessibility checks into future projects. ChatGPT helped students fix many accessibility violations, and prompt formulation required students to understand the issues before asking for solutions. Challenges: Students were more successful fixing some accessibility issues than others. Problems related to contrast, resize text, and labels or instructions remained harder to solve. Some students needed several iterations with ChatGPT, showing that LLM support still requires refinement, contextual prompting, and student understanding.", "swebokAreas": "Software Quality", "swebokSubAreas": "", "doiOrLink": "https://doi.org/10.1145/3641554.3701841", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Evaluating lab assistant chatbot on student learning and behaviors in a programming short course": { "id": "ID91", "level": "B", "year": "2026", "source": "", "authors": "Thanapon Noraset, Akara Supratak, Chaiyong Ragkhitwetsagul, Nubthong Worathong, and Suppawong Tuarob", "educationalObjectives": "To evaluate how chatbot assistance affects students’ learning of introductory Python programming, including syntax, control flow, functions, data structures, debugging, and independent problem solving during programming lab exercises.", "aiEmployment": "The study compared three learning conditions in a Python short course: no chatbot, an unrestricted GPT-4 chatbot, and a customized Assistant chatbot. The Assistant chatbot was designed as a Python lab assistant that provided hints, conceptual explanations, debugging support, and guidance without giving complete runnable solutions. Students used the chatbots inside a Visual Studio Code extension during lab exercises.", "llm": "GPT-4", "metrics": "Pre-test scores, post-test scores, improvement scores, coding and conceptual questions, independent t-tests, paired t-tests, Cohen’s d, chatbot interaction logs, number of prompts, preset versus free-text prompt usage, prompt categories, exploitation attempts, prompt injection success rate, usability questionnaire, and inter-rater reliability for prompt coding.", "metricsUsage": "The authors compared learning gains across the control, unrestricted chatbot, and Assistant chatbot groups using pre- and post-test scores. Chat logs were coded to analyze student interaction patterns, including productive prompts and exploitation attempts. Prompt injection tests were used to evaluate whether the Assistant chatbot could be manipulated into giving full solutions or going off-topic.", "resources": "Python programming short course, lectures, lab assignments, Visual Studio Code extension, integrated chatbot interface, GPT-4 backend, programming exercises, pre-test and post-test, lab chat logs, preset prompt categories, free-text prompts, usability questionnaire, and course topics covering Python syntax, functions, iterations, conditions, lists, tuples, sets, and dictionaries", "benefitsAndChallenges": "Benefits: The Assistant chatbot produced significantly greater learning improvement than the unrestricted chatbot, suggesting that guided interaction and scaffolding can support programming learning better than open-ended AI access. Students also used the chatbot consistently during labs and reported positive usability and learning support. Challenges: Students strongly preferred free-text prompts and often attempted to exploit the chatbot to obtain direct solutions. The Assistant chatbot remained vulnerable to prompt injection, showing that simple prompt-based guardrails are insufficient to fully prevent misuse.", "swebokAreas": "Software Construction", "swebokSubAreas": "Programming fundamentals", "doiOrLink": "https://doi.org/10.1016/j.caeai.2025.100527", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
"Insights from the Frontline: GenAI Utilization Among Software Engineering Students": { "id": "ID92", "level": "A", "year": "2025", "source": "2025 IEEE/ACM 37th International Conference on Software Engineering Education and Training (CSEE&T)", "authors": "Rudrajit Choudhuri, Ambareesh Ramakrishnan, Amreeta Chatterjee, Bianca Trinkenreich, Igor Steinmacher, Marco Gerosa, and Anita Sarma", "educationalObjectives": "To understand how Software Engineering students use GenAI tools to support learning of SE concepts and implementation tasks, and to identify where GenAI helps or hinders learning, problem solving, critical thinking, and AI literacy development.", "aiEmployment": "The study did not implement a controlled AI intervention. Instead, it investigated students’ real academic use of GenAI tools through reflective interviews. Students reported using GenAI for initial and incremental learning, code comprehension, brainstorming, boilerplate generation, framework setup, syntax learning, debugging support, code optimization, and support for term or capstone projects.", "llm": "ChatGPT; Gemini/Bard; GitHub Copilot", "metrics": "Semi-structured reflective interviews, 16 student participants, participants’ GenAI conversation histories, member checking, instructor interviews, reflexive thematic analysis, Atlas.ti coding, thematic categories of benefits and challenges, and triangulation with instructors and social science theories.", "metricsUsage": "The authors analyzed interview data to identify when, how, and where students used GenAI in SE learning and implementation. They categorized perceived benefits and challenges across four phases: initial learning, incremental learning, initial implementation, and advanced implementation. They also analyzed causes and consequences of challenges, then validated findings through member checking and instructor triangulation.", "resources": "Software Engineering courses, senior SE courses, capstone courses, students’ GenAI conversation histories, ChatGPT, Gemini/Bard, Copilot, SE learning topics, implementation tasks, codebases, term projects, capstone projects, course materials, software design tasks, testing tasks, APIs, microservices, version control, code review, deployment, CI/CD, and instructor feedback.", "benefitsAndChallenges": "Benefits: Students perceived GenAI as useful for incremental learning and initial implementation tasks. Benefits included clarifying concepts and code, obtaining structured outlines, getting surface-level understanding, revising concepts, generating examples, learning syntax, brainstorming ideas, comprehending code snippets, and finding useful resources. Challenges: Students faced challenges mainly in initial learning and advanced implementation tasks. These included unclear understanding of GenAI’s limitations, difficulty communicating context, difficulty aligning GenAI with preferences or processes, lack of clear rationales, misleading or confusing responses, hallucinations, incomplete assistance, and difficulty verifying, modifying, or generalizing GenAI outputs.", "swebokAreas": "Software Engineering Professional Practice", "swebokSubAreas": "professional judgment and critical thinking", "doiOrLink": "https://ieeexplore.ieee.org/document/11024444", "interaction": "Free Prompts", "analysis": "Qualitative", "usedByStudents": "Yes" },
"Leveling Up Software Project Management Education: From Manual Mastery to AI Empowerment": { "id": "ID93", "level": "A", "year": "2025", "source": "10th International Conference on Computer Science and Engineering (UBMK)", "authors": "Sevgi Koyuncu Tunç", "educationalObjectives": "To teach undergraduate students software project management competencies, including SRS refinement, UML modeling, WBS creation, task dependencies, three-point estimation, Gantt chart scheduling, risk analysis, presentation, and critical use of AI tools in project planning.", "aiEmployment": "The study used a two-phase instructional model. First, students completed core software project management tasks manually to build foundational understanding. Then, during an AI-assisted capstone “Planathon,” teams used AI tools to revise flawed SRS documents and generate or refine project deliverables such as UML diagrams, WBS, task estimates, dependencies, Gantt charts, and risk registers.", "llm": "ChatGPT 4o/o1; Claude 3.5 Sonnet; Google Gemini", "metrics": "Manual phase task scores, rubric-based project evaluation, number of mistakes by task, AI Experience Tables, student reflections, tool usage frequency, task completion time, number of prompt iterations, manual correction frequency, post-Planathon perception survey, Likert-scale satisfaction ratings, and qualitative coding of reflections.", "metricsUsage": "Manual task scores were used to identify students’ baseline strengths and weaknesses before AI adoption. In the AI-assisted phase, rubric evaluations assessed the quality of deliverables, while AI Experience Tables and reflections documented tools used, challenges, time spent, iterations, and improvement strategies. Survey responses measured students’ perceptions of the Planathon experience and AI integration.", "resources": "Undergraduate Software Project Management course, flawed SRS document, manual lab exercises, SRS correction tasks, UML diagrams, WBS, task dependency mapping, three-point estimation, Gantt charts, risk registers, AI-powered Plant Disease Detection System capstone project, AI Experience Table, Planathon event, rubric, presentation videos, jury evaluation, ChatGPT, Claude, Gemini, PlantUML AI, Mermaid AI, Smartsheet AI, MS Project AI, and ChatUML.", "benefitsAndChallenges": "Benefits: The scaffolded model helped students build manual project management foundations before using AI, supported AI literacy, improved prompt engineering awareness, and encouraged critical evaluation of AI-generated deliverables. Students found AI useful for structured tasks such as SRS review and task estimation. Challenges: Students struggled with AI-generated visual planning artifacts, especially Gantt charts and UML diagrams. Common problems included resource overallocations, syntax errors, incomplete diagrams, circular dependencies, generic risks, context loss, and incomplete or inconsistent outputs. Ethical awareness and reflection on bias remained limited.", "swebokAreas": "Software Engineering Management", "swebokSubAreas": "Software project planning", "doiOrLink": "https://ieeexplore.ieee.org/abstract/document/11206923?casa_token=ETVRmmDJHUEAAAAA:O0gM9qWiXbyOacMnA8ivM-bTFxW8cW-NjIDi1yxeDlu2lJ1fWq2p6G2OmZ8LByTQXeLJwhdnCAY", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Not All Chatbots Teach: Evidence for Pedagogical Design in AI-Assisted Technical Education": { "id": "ID94", "level": "B", "year": "2025", "source": "ACM SIGCITE 2025: Proceedings of the 26th ACM Annual Conference on Cybersecurity & Information Technology Education", "authors": "Lucas P. Cordova, Teo Mendoza, Sam Holmes, Kayle Megginson, Ben Webster, and Derec Gregory", "educationalObjectives": "To support students’ conceptual understanding and technical reasoning in data structure selection, abstraction, implementation, justification of design decisions, documentation, and explanation of program behavior. The study is not specifically a Software Engineering course, but the targeted skills are relevant to software construction and design reasoning.", "aiEmployment": "The study compared two AI-assisted learning conditions in an undergraduate Data Structures course. One group used a structured AI assistant with metacognitive scaffolding based on the Feynman Technique, requiring students to explain, predict, reflect, and revise before receiving support. The control group used the same interface configured as a minimally prompted ChatGPT wrapper with unrestricted queries.", "llm": "ChatGPT", "metrics": "Overall project scores, rubric-based subcategory scores, functional implementation, data structure usage, code modularity and style, report accuracy, documentation quality, independent samples t-test, Cohen’s d, performance variance, tool usage logs, and brief post-project surveys.", "metricsUsage": "The authors compared project performance between students using the structured AI assistant and students using the unstructured ChatGPT wrapper. Rubric scores were used to evaluate implementation quality, data structure choices, code quality, report accuracy, and documentation. Statistical tests assessed differences between the two groups.", "resources": "Undergraduate Data Structures course, Bistro Ordering System capstone assignment, custom conversational AI tool, structured “Project Design Journey,” Feynman-style prompts, explain–predict–reflect–revise workflow, ChatGPT wrapper, project rubric, implementation tasks, design documentation, README files, code comments, and blinded TA grading.", "benefitsAndChallenges": "Benefits: The structured AI assistant significantly improved student performance compared with unstructured ChatGPT access, especially in abstraction, data structure justification, report accuracy, and documentation. The structured prompts encouraged reflection, prediction, explanation, and reduced passive reliance on AI-generated answers. Challenges: Unstructured AI use may encourage shallow engagement, automation bias, and solution-seeking rather than learning. The study also notes limitations related to non-random section assignment, variable tool engagement in the control group, small sample size, and limited evidence about long-term transfer.", "swebokAreas": "Software Construction", "swebokSubAreas": "code quality", "doiOrLink": "https://doi.org/10.1145/3769694.3771107", "interaction": "Hybrid", "analysis": "Qualitative", "usedByStudents": "Yes" },
"A ‘watch your replay videos’ Reflection Assignment on Comparing Programming without versus with Generative AI: Learning about Programming, Critical AI Use and Limitations, and Reflection": { "id": "ID95", "level": "A", "year": "2025", "source": "SIGCSE TS 2026: Proceedings of the 57th ACM Technical Symposium on Computer Science Education V.1", "authors": "Sarah “Magz” Fernandez and Greg L. Nelson", "educationalObjectives": "To help students reflect on their programming process in a software engineering team project, compare programming with and without GenAI, develop metacognitive skills, improve debugging and help-seeking behaviors, and learn to use GenAI critically rather than only for task completion.", "aiEmployment": "Students recorded two programming sessions while working on their team project: one without GenAI and one with GenAI. They then watched their own videos and completed a scaffolded reflection assignment based on the DEAL framework, comparing their programming process, help-seeking behavior, debugging, planning, and AI use.", "llm": "ChatGPT, Gemini and GitHub Copilot", "metrics": "Student reflection submissions, comparative video reflection responses, DEAL framework questions, qualitative thematic analysis, student-reported learning", "metricsUsage": "The authors conducted qualitative thematic analysis of students’ written reflections, focusing on what students reported learning and what future goals they set after comparing their programming sessions with and without GenAI.", "resources": "Introductory software engineering course, team software projects, screen-recorded programming sessions, web development projects using React and Firebase, one Discord bot project, GenAI tools, Cursor demonstration, GenAI use for requirements feedback and test generation, DEAL reflection framework, scaffolded reflection questions, and written reflection submissions.", "benefitsAndChallenges": "Benefits: Students reported learning about planning, debugging, help-seeking, prompt engineering, critical AI use, productivity gains, and the importance of understanding code before generating or accepting AI outputs. The reflection activity also helped students identify future goals related to collaboration, self-reflection, planning, and balanced AI use. Challenges: Students identified AI limitations, unreliable or flawed generated code, possible negative impacts on learning, over-reliance, reduced understanding, and situations where GenAI could be counterproductive. Some students concluded that human help, documentation, or manual debugging could be better than AI in certain contexts.", "swebokAreas": "Software Construction", "swebokSubAreas": "programming process, debugging", "doiOrLink": "https://doi.org/10.1145/3770762.3772668", "interaction": "Free Prompts", "analysis": "Mixed", "usedByStudents": "Yes" },
"Adaptable Metrics to Assess and Improve Introductory CS": { "id": "ID96", "level": "A", "year": "2025", "source": "CompEd 2025: Proceedings of the ACM Global Computing Education Conference 2025 Vol. 1", "authors": "Rui Lin, Edward Donson, and Zachary Dodds", "educationalObjectives": "To assess and improve introductory students’ software project work by using pedagogical code metrics that reveal changes in code structure, concision, complexity, documentation, and use of course concepts, especially before and after LLM adoption.", "aiEmployment": "The study did not implement a specific AI intervention. Instead, it analyzed student final projects from CS1 and CS2 courses before and after the curriculum embraced LLM use in 2023. The authors used static code-analysis metrics to identify LLM-correlated changes in student software artifacts and to inform curriculum adaptations.", "llm": "not clearly", "metrics": "Lines of code, number of functions, cyclomatic complexity, maximum static function-call nesting depth, percentage of comments, number of course topic “weeks” used, Kolmogorov–Smirnov tests, pre-LLM versus post-LLM project distributions, and comparisons across CS1 project themes.", "metricsUsage": "The authors applied six code metrics to more than a thousand CS1 and CS2 final projects from 2018 to 2024. They compared pre-LLM and post-LLM project distributions and also compared metrics across CS1 project types to identify how LLM adoption and project scaffolding affected student code.", "resources": "CS1 and CS2 final projects, seven years of student project submissions, five CS1 project themes, static code-analysis metrics, project rubrics, instructor and alumni grading, student presentations, and course adaptations emphasizing project variety, student agency, and demonstration of student work.", "benefitsAndChallenges": "Benefits: The metrics suggested that LLMs may help introductory students produce more concise and streamlined code. The study also showed that code metrics can help instructors monitor curriculum effects and adjust project scaffolding, assessment, and student demonstrations. Challenges: LLM-correlated changes may make it harder to determine what is genuinely “student” code. Some metrics, such as Weeks Used, may become less reliable indicators of student understanding when LLMs generate more professional or concise code. The study also highlights the need to balance student agency, project variety, and curricular outcomes.", "swebokAreas": "Software Construction", "swebokSubAreas": "Programming and implementation", "doiOrLink": "https://doi.org/10.1145/3736181.3747157", "interaction": "Free Prompts", "analysis": "Quantitative", "usedByStudents": "Yes" },
"Reimagining feedback through generative AI in engineering education": { "id": "ID97", "level": "C", "year": "2026", "source": "", "authors": "Janka Pecuchova, Lubomir Benko, and Martin Drlik", "educationalObjectives": "To support students in learning software modeling through requirements specification and UML diagram construction, including use case diagrams, class diagrams, and activity diagrams, with emphasis on abstraction, semantic correctness, structural consistency, and design reasoning.", "aiEmployment": "ChatGPT was used through API-based prompts to generate formative feedback in Slovak for student-created UML diagrams exported from Enterprise Architect in XMI/XML format. The study compared GenAI-generated feedback, teacher-generated feedback, and no-feedback conditions. The model was also tested as an evaluator of final exam UML diagrams using different prompt strategies.", "llm": "ChatGPT", "metrics": "Student Likert-scale ratings of feedback usefulness, assignment scores, quiz scores, final exam scores, two independent human graders, unweighted Cohen’s Kappa, quadratic weighted Cohen’s Kappa", "metricsUsage": "The study compared student perceptions of GenAI and teacher feedback, categorized feedback as diagnostic, design-oriented, motivational, or metacognitive, analyzed linguistic richness and sentiment, measured learning outcomes across assignments and final UML modeling tasks, and evaluated agreement between GenAI grading and human grading under different prompt configurations.", "resources": "Bachelor-level Introduction to Software Engineering course, Moodle LMS, Enterprise Architect, XMI/XML exports, four modeling assignments, requirements specification tasks, use case diagrams, class diagrams, activity diagrams, six theoretical quizzes, final exam UML tasks, teacher feedback, GPTo1-generated feedback, and rubric-aligned grading prompts.", "benefitsAndChallenges": "Benefits: Students generally rated GenAI feedback as useful and sometimes comparable to teacher feedback. GenAI feedback offered scalable, immediate formative support for large cohorts and could identify structural or semantic issues in UML submissions. GPTo1 also achieved substantial to almost perfect agreement with human graders for some UML grading tasks. Challenges: Teacher feedback remained more effective for learning gains, especially in complex visual modeling tasks. GenAI feedback was more repetitive, less linguistically rich, less motivational or metacognitive, and sometimes overly diagnostic. Its effectiveness depended strongly on prompt structure, input representation, and task complexity.", "swebokAreas": "Software Engineering Models and Methods", "swebokSubAreas": "UML modeling", "doiOrLink": "https://doi.org/10.1016/j.caeai.2026.100574", "interaction": "Used by Professors", "analysis": "Mixed", "usedByStudents": "No" },
"Using Peer Assessment Leveraging Large Language Models in Software Engineering Education": { "id": "ID98", "level": "B", "year": "2025", "source": "International Journal of Software Engineering and Knowledge Engineering, Volume 35, Issue 1", "authors": "Marco Fiore and Marina Mongiello", "educationalObjectives": "To improve students’ understanding of software engineering modeling through peer assessment of AI-generated solutions, including functional and non-functional requirements, FURPS+, actors, use cases, UML class diagrams, UML sequence diagrams, and critical evaluation of modeling inconsistencies.", "aiEmployment": "ChatGPT was used to generate a solution for a software modeling exercise about an appointment-booking platform for professors, assistants, and students. The AI-generated solution included requirements, actors, use cases, a class diagram, and a sequence diagram in PlantUML. Students were asked to evaluate, critique, and improve the AI-generated modeling solution as if ChatGPT were a colleague in a software engineering company.", "llm": "ChatGPT 3.5", "metrics": "Student survey responses, qualitative comments, perceived clarity and quality of the ChatGPT-generated UML solution, perceived contribution to understanding GenAI in software engineering, completion time, pre- and post-intervention assessment scores", "metricsUsage": "The authors analyzed students’ perceptions of the AI-based peer assessment activity through a survey completed by 141 students. They also compared pre- and post-intervention test scores and completion rates to evaluate changes in learning outcomes and participation after the AI-integrated assessment.", "resources": "Software Engineering course assessment exam, ChatGPT-generated modeling solution, appointment-booking platform scenario, functional requirements, non-functional requirements using FURPS+, actors and use cases, UML class diagram, UML sequence diagram, PlantUML, survey form, pre- and post-intervention assessments, and traditional course materials.", "benefitsAndChallenges": "Benefits: Students were able to identify inconsistencies in ChatGPT’s solution, reflect critically on AI-generated modeling artifacts, and better understand the potential and limitations of GenAI in software engineering contexts. The activity was perceived as engaging and different from traditional exams, and post-intervention scores and completion rates improved. Challenges: ChatGPT produced incomplete or inconsistent modeling outputs, such as missing login-related elements, incomplete class attributes, and a sequence diagram that did not properly use the assistant lifeline. The study also notes that AI cannot replace human creativity and judgment in UML modeling.", "swebokAreas": "Software Engineering Models and Methods", "swebokSubAreas": "UML modeling; class diagram modeling; sequence diagram modeling", "doiOrLink": "https://www.worldscientific.com/doi/abs/10.1142/S0218194024500359?casa_token=_-Gpci9zbvUAAAAA:eRrv7YR2mkTBNtGisBpShA2qS68r-_gAKVDodTxVGSUvYXJTaztiK9Dvxp-Zl4rMMNxX-ETEZZfRwg", "interaction": "Hybrid", "analysis": "Mixed", "usedByStudents": "Yes" },
};
